(window.GIM_TS=window.GIM_TS||{})["Berakhot.2"]={"from":48,"a":[["\u0003אקמטרה\u0004 \u0005[על תיבה המונחת על ארגז]\u0006 — \u0003ככלי בתוך כלי דמי\u0004 \u0005[מחשיבה\u0006 אותו\u0005].\u0006 וכעין זה \u0003אמר ר' יהושע בן לוי:\u0004 אם יש \u0003ספר תורה\u0004 בחדר — \u0003צריך לעשות לו מחיצה\u0004 הגבוהה \u0003עשרה\u0004 טפחים אם רוצה לשמש מיטתו בחדר זה. ומסופר: \u0003מר זוטרא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב אשי, חזייה לדוכתיה\u0004 \u0005[ראהו את מקום משכבו]\u0006 של \u0003מר בר\u0004 \u0005[בנו]\u0006 של \u0003רב אשי דמנח ביה\u0004 \u0005[שמונח בו]\u0006 \u0003ספר תורה ועביד ליה\u0004 \u0005[ועשויה לו]\u0006 \u0003מחיצה עשרה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כמאן\u0004 \u0005[כמי]\u0006 עושה אתה דבר זה? \u0003כ\u0004שיטת \u0003ר' יהושע בן לוי? אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' יהושע בן לוי\u0004 רק כפתרון בשעת הדחק וכגון באופן \u0003דלית ליה ביתא אחרינא\u0004 \u0005[שאין לו בית אחר],\u0006 ואילו \u0003מר הא אית ליה ביתא אחרינא\u0004 \u0005[אדוני הרי יש לו בית אחר],\u0006 ואם כן מדוע לא להעביר את ספר התורה למקום אחר כפתרון לכתחילה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אכן \u0003לאו אדעתאי\u0004 \u0005[לא\u0006 עלה \u0005על דעתי]\u0006 כדבריך.","שנינו במשנה: \u0003כמה ירחיק מהן\u0004 ממי רגלים \u0003ומן הצואה\u0004 ויוכל לקרוא את שמע — \u0003ארבע אמות. אמר רבא אמר רב סחורה אמר רב הונא: לא שנו\u0004 שדי בהרחקת ארבע אמות \u0003אלא\u0004 כשהיתה הצואה \u0003לאחוריו, אבל\u0004 אם היתה הצואה \u0003לפניו\u0004 — \u0003מרחיק\u0004 ממנה \u0003מלא עיניו, וכן\u0004 הדין \u0003לתפלה.\u0004","על כך מקשים: \u0003איני\u0004 \u0005[כן היא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רפרם בר פפא אמר רב חסדא: עומד אדם כנגד בית הכסא ומתפלל!\u0004 ומתרצים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003בבית הכסא שאין בו צואה,\u0004 ולכן אין צורך להרחיק ממנו כל כך.","ושוב שואלים: \u0003איני\u0004 \u0005[כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יוסף בר חנינא: בית הכסא שאמרו\u0004 בכל דיני הרחקה דינו כך \u0003אף על פי שאין בו צואה, ובית המרחץ שאמרו\u0004 להימנע בו מדברי קדושה, \u0003אף על פי שאין בו אדם\u0004 ערום! \u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בחדתי\u0004 \u0005[בחדש],\u0006 בבית שנבנה לצורך בית הכסא, ועדיין לא השתמשו בו.","על כך שואלים: \u0003והא מיבעי ליה\u0004 \u0005[והרי\u0006 כבר \u0005נשאלה לו\u0006 שאלה זו\u0005]\u0006 על ידי \u0003רבינא,\u0004 ששאל: אם \u0003הזמינו\u0004 (הכין) לבית \u0003ל\u0004צורך \u0003בית הכסא, מהו\u0004 דינו? האם \u0003יש\u0004 ל\u0003זימון\u0004 תוקף כאן, \u0003או אין\u0004 ל\u0003זימון\u0004 תוקף? ועונים: \u0003כי קא מבעיא ליה\u0004 \u0005[כאשר נשאלה לו\u0006 השאלה\u0005]\u0006 \u0003לרבינא,\u0004 זה שנשאלה לו: \u0003למיקם עליה לצלויי בגויה\u0004 \u0005[לעמוד עליו,\u0006 בתוכו, \u0005להתפלל בתוכו]\u0006 \u0003אבל\u0004 לענין בית הכסא העומד \u0003כנגדו\u0004 — \u0003לא\u0004 שאל.","\u0003אמר רבא: הני בתי כסאי דפרסאי\u0004 \u0005[אותם בתי כסא של הפרסים]\u0006 \u0003אף על גב דאית בהו\u0004 \u0005[שיש בהם]\u0006 \u0003צואה\u0004 — \u0003כסתומין דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 שעשויים היו שהצואה תתגלגל ותצא מתחת לארץ ולא תישאר בתוכם.","בהמשך לדיני טבילת בעל קרי להיטהר לתורה ותפילה דנים במקרה שאפילו אנשים שיש בהם טומאה חמורה, אם נוסף לכך נטמאו בטומאת קרי — חייבים הם לטבול ולהיטהר ממנה. ועל כן אפילו \u0003זב\u0004 הטמא טומאת שבעה — \u0003שראה קרי,\u0004 שאילולי היה זב היתה טומאתו בשל הקרי רק בת יום אחד, \u0003ו\u0004כן \u0003נדה שפלטה שכבת זרע,\u0004 אף שהיא טמאה טומאה חמורה שעדיין אין הטבילה מועילה לה, \u0003ו\u0004כן \u0003המשמשת\u0004 עם בעלה \u0003שראתה\u0004 אחר כך \u0003נדה\u0004 — \u0003צריכין טבילה. ור' יהודה פוטר.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לבני הישיבה\u0005]\u0006 שאלה זו: אדם שהוא \u0003בעל קרי\u0004 וככזה הוא חייב בטבילה, ואולם אחר כך \u0003ראה זיבה, ל\u0004דעת \u0003ר' יהודה מהו\u0004 דינו? ומפרשים את צדדי השאלה: האם נאמר \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003פטר ר' יהודה התם\u0004 \u0005[שם\u0006 במשנתנו\u0005]\u0006 \u0003בזב שראה קרי, דמעיקרא\u0004 \u0005[ש\u0006כן \u0005מתחילה]\u0006 \u0003לאו בר טבילה הוא,\u0004 שאינו ראוי לטבילה, שהלא אינו יכול להטהר בה מטומאת זיבה. \u0003אבל בעל קרי שראה זיבה, דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003בר\u0004 \u0005[בן]\u0006 \u0003טבילה הוא\u0004 (נתחייב בטבילה) ורק אחר כך נטמא טומאה חמורה שמא \u0003מחייב\u0004 \u0005[מחייב]\u0006 בו ר' יהודה, \u0003או דילמא לא שנא\u0004 \u0005[שמא אין\u0006 זה \u0005שונה]\u0006 והוא פוטר בכל מקרה.","כדי לפתור את הבעיה \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 את הקטע האחרון של המשנה \u0003המשמשת וראתה נדה צריכה טבילה, ור' יהודה פוטר. והא\u0004 \u0005[והרי]\u0006 ה\u0003המשמשת וראתה נדה\u0004 הריהי \u0003כ\u0004של \u0003בעל קרי שראה זיבה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 שגם במקרה זה יש טומאה קלה מקודם, וטומאה חמורה אחר כך, \u0003וקא\u0004 \u0005[ובכל זאת]\u0006 \u0003פוטר ר' יהודה,\u0004 ואם כן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שאין ר' יהודה מבדיל בין המקרים. ואכן, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא בהדיא\u0004 \u0005[במפורש]:\u0006 \u0003בעל קרי שראה זיבה צריך טבילה, ור' יהודה פוטר.\u0004","\u0003הדרן עלך מי שמתו\u0004","במשנה זו מדובר על קביעת סוף זמן התפילות (מאירי). לדעת חכמים זמן \u0003תפלת השחר\u0004 הוא \u0003עד חצות\u0004 היום. \u0003ר' יהודה אומר:\u0004 זמן תפילת שחרית מוגבל \u0003עד ארבע שעות\u0004 מזריחת החמה בלבד. זמן \u0003תפלת המנחה\u0004 לדעת חכמים הוא \u0003עד הערב,\u0004 ו\u0003ר' יהודה אומר: עד פלג המנחה\u0004 בלבד, כלומר, אמצע הזמן שמהקרבת תמיד של בין הערבים ועד הלילה, שהוא סוף שעת בין הערבים.","\u0003תפלת הערב אין לה קבע,\u0004 שזמנה אינו מוגבל עד לשעה מסויימת בלילה, וזמנה במשך כל הלילה. ובגמרא עוד יבואר משום מה נקטו בלשון זו דווקא. \u0003ו\u0004הזמן \u0003של מוספים\u0004 (תפלת מוסף) לדעת חכמים הוא \u0003כל היום,\u0004 ו\u0003ר' יהודה אומר\u0004 לשיטתו כי הזמן מוגבל \u0003עד לשבע שעות\u0004 מן הזריחה.","שנינו במשנה בדרך סתמית כי זמן תפילת השחר נמשך שעות אחדות בתוך היום. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו בברייתא: \u0003מצותה\u0004 (של קריאת שמע בשחרית) \u0003עם הנץ החמה, כדי שיסמוך גאולה\u0004 האמורה בברכות שלאחר קריאת שמע \u0003לתפלה\u0004 הנאמרת מיד לאחר הנץ החמה, \u0003ונמצא מתפלל ביום,\u0004 הרי שנקבע זמן תפילת שחרית מיד עם זריחת השמש!","על כך משיבים: ברייתא זו לא נתכוונה לקבוע הלכה מחייבת, אלא \u0003כי תניא\u0004 \u0005[כאשר שנוייה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 הרי זה \u0003לותיקין\u0004 המדקדקים במצוות. וכשם ש\u0003אמר ר' יוחנן: ותיקין היו גומרים אותה,\u0004 את קריאת שמע של שחרית \u0003עם הנץ החמה.\u0004 אבל לשאר האנשים שאינם מן הותיקין מותר לאחר תפילתם אף יותר מכן.","ומעתה מקשים בגמרא לצד אחר: \u0003ו\u0004האם \u0003כולי עלמא\u0004 \u0005[כל העולם]\u0006 סבורים שתפילת שחרית היא \u0003עד חצות\u0004 היום \u0003ותו לא\u0004 \u0005[ולא עוד],\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' ירמיה בר אבא\u0004 שכך \u0003אמר ר' יוחנן: טעה ולא התפלל ערבית\u0004 — \u0003מתפלל בשחרית שתים,\u0004 טעה ולא התפלל \u0003שחרית\u0004 — \u0003מתפלל במנחה שתים.\u0004 הרי שזמן תפילת שחרית (או לפחות הזמן בו אפשר להשלים תפילת שחרית שחסרה) נמשך עד הערב!","ומשיבים: אכן, \u0003כולי יומא מצלי ואזיל\u0004 \u0005[כל היום מתפלל והולך]\u0006 ואין מונעים ממנו, אלא שאם התפלל \u0003עד חצות, יהבי ליה\u0004 \u0005[נותנים לו]\u0006 \u0003שכר תפלה בזמנה,\u0004 ואולם אם התפלל לאחר מכן, הרי \u0003מכאן ואילך, שכר תפלה\u0004 — \u0003יהבי ליה\u0004 \u0005[נותנים לו],\u0006 \u0003שכר תפלה בזמנה\u0004 — \u0003לא יהבי ליה\u0004 \u0005[אין נותנים לו].\u0006","בקשר לנושא זה של השוכח להתפלל ורוצה להשלים \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לבני בית המדרש\u0005]\u0006 שאלה זו: אם \u0003טעה ולא התפלל מנחה, מהו\u0004 הדין לענין \u0003שיתפלל\u0004 תפילת \u0003ערבית שתים\u0004 (פעמיים)? ומפרטים את צדדי השאלה: \u0003אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר,\u0004 אף אם תחליט שזה ש\u0003טעה ולא התפלל ערבית\u0004 תקנתו שיהא \u0003מתפלל שחרית שתים,\u0004 הרי אפשר לומר שהטעם \u0003משום דחד יומא\u0004 \u0005[שיום אחד]\u0006 \u0003הוא, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויהי ערב ויהי בקר יום אחד\"\u0004 (בראשית א, ה), והרי שהערב והיום הבא אחריו יחידה אחת הם. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 במקרה שלנו הלא \u0003תפלה במקום קרבן היא\u0004 באה, \u0003ו\u0004כמו בקרבנות אפשר לומר גם כאן כי \u0003כיון\u0004 ש\u0003עבר יומו בטל קרבנו,\u0004 ואין אם כן עוד דרך להשלים חסרון זה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון דצלותא רחמי\u0004 \u0005[שתפילה\u0006 בקשת \u0005רחמים]\u0006 \u0003היא,\u0004 ואם כן \u0003כל אימת דבעי מצלי ואזיל\u0004 \u0005[כל זמן שרוצה מתפלל והולך].\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ש\u0003אמר רב הונא בר יהודה אמר ר' יצחק אמר ר' יוחנן:\u0004 אם \u0003טעה ולא התפלל מנחה\u0004 — \u0003מתפלל ערבית שתים, ואין בזה משום\u0004 ש\u0003עבר יומו בטל קרבנו.\u0004","על אפשרות זו להשלים תפילה שלא נאמרה בזמנה \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עתה ממה ששנינו בברייתא. פירוש הנאמר \u0003\"מעוות לא יוכל לתקון וחסרון לא יוכל להמנות\"\u0004 (קהלת א, טו) הוא כך: \u0003\"מעות לא יוכל לתקן\"\u0004 — הכוונה ל\u0003זה שבטל קריאת שמע של ערבית וקריאת שמע של שחרית, או תפלה של ערבית או תפלה של שחרית. \"וחסרון לא יוכל להמנות\"\u0004 — הכוונה ל\u0003זה שנמנו חביריו\u0004 והחליטו \u0003לעשות דבר מצוה, ו\u0004הוא \u0003לא נמנה עמהם\u0004 ושוב לא יוכל להצטרף עימם בכך. הרי שבברייתא זו מובא בפשטות שביטול תפילה אין לו עוד תקנה.","כדי לתרץ קושי זה \u0003אמר ר' יצחק אמר ר' יוחנן: הכא במאי עסקינן\u0004 \u0005[כאן\u0006 בברייתא זו \u0005במה אנו עוסקים]\u0006 — באופן \u0003שבטל\u0004 תפילה \u0003במזיד,\u0004 והוא שאין לו תקנה, ואולם מי שטעה ולא התפלל — יכול להשלים תפילתו.","\u0003אמר רב אשי: דיקא נמי\u0004 \u0005[מדוייק גם כן],\u0006 כדבריך מסגנון הדברים, \u0003דקתני\u0004 \u0005[ששנינו]\u0006 בברייתא לשון \u0003\"בטל\", ולא קתני\u0004 \u0005[שנינו]\u0006 לשון \u0003\"טעה\",\u0004 והרי שבטעה ההלכה שונה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 מהוכחה זו."],["בדומה למקרה שהובא \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: אם \u0003טעה ולא התפלל מנחה\u0004 של חול \u0003בערב שבת\u0004 — \u0003מתפלל בליל שבת שתים\u0004 של שבת. \u0003טעה ולא התפלל מנחה בשבת\u0004 — \u0003מתפלל במוצאי שבת שתים\u0004 של חול. \u0003מבדיל\u0004 (אומר \"אתה חוננתנו\" בברכת \"חונן הדעת\" להבדיל בין שבת לחול) \u0003ב\u0004תפילה ה\u0003ראשונה,\u0004 לפי שהיא תפילת ערבית ממש, \u0003ואינו מבדיל בשניה,\u0004 שכן היא במקום תפילת מנחה שאינה צריכה להבדלה. \u0003ו\u0004יתר על כן, \u0003אם הבדיל בשניה ולא הבדיל בראשונה\u0004 — \u0003שניה עלתה לו\u0004 (נחשבת לו) ויצא בה ידי חובה, ואילו ה\u0003ראשונה לא עלתה לו.\u0004","מתוך פסק ההלכה האחרון אפשר להוציא מסקנות מסויימות, ועל כך מעירים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שמ \u0003כיון\u0004 ש\u0003לא אבדיל בקמייתא\u0004 \u0005[הבדיל ב\u0006תפילה ה\u0005ראשונה]\u0006 הרי זה \u0003כמאן\u0004 \u0005[כמי]\u0006 ש\u0003לא צלי דמי, ומהדרינן ליה\u0004 \u0005[התפלל נחשב, ומחזירים אותו]?\u0006 ואם כן נסיק מכאן שכל שלא הבדיל בתפילה יחזור ויתפלל.","ומביאים ראיה מן התוספתא לסתור הנחה זו, \u0003ורמינהו\u0004 \u0005[ומשליכים\u0006 מראים סתירה\u0005]\u0006 לדבר ממה ששנינו בברייתא: אם \u0003טעה ולא הזכיר גבורות גשמים\u0004 (\"משיב הרוח ומוריד הגשם\") \u0003ב\u0004ברכת \u0003תחיית המתים,ו\u0004כן אם לא הזכיר \u0003שאלה\u0004 (הבקשה על הגשם, \"ותן טל ומטר\") \u0003בברכת השנים\u0004 — \u0003מחזירין אותו\u0004 להתפלל בשנית. ואולם אם שכח לומר \u0003הבדלה ב\u0004ברכת \u0003\"חונן הדעת\"\u0004 — \u0003אין מחזירין אותו, מפני שיכול לאומרה\u0004 (את ההבדלה) \u0003על הכוס\u0004 לעצמה. הרי שאי אמירת הבדלה אינה מעכבת את התפילה! סתירה זו לא נתיישבה ועל כן היא נשארת \u0003קשיא\u0004 \u0005[קשה],\u0006 בלא שינתן לה פתרון.","למחלוקת בין חכמים ור' יהודה בקביעת זמני התפילות יש רקע מעמיק המתבטא גם במחלוקת מאוחרת של אמוראים. וכך \u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003ר' יוסי בר' חנינא אמר: תפלות אבות תקנום.\u0004 שראשית הקביעה של תפילות שלוש פעמים ביום (אף כי לא בלשונן המאוחרת) קדומה היא ושורשה עוד בימי האבות. ואילו \u0003ר' יהושע בן לוי\u0004 סבור כי \u0003תפלות כנגד תמידין תקנום.\u0004 כלומר, שהתפילות מקבילות לקרבנות התמיד שבמקדש, וצמודות לזמניהם ולאופיים.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוסי בר' חנינא, ותניא כוותיה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יהושע בן לוי.\u0004 ומפרטים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוסי בר' חנינא: אברהם תקן תפלת שחרית,\u0004 וכפי \u0003שנאמר\u0004 כאשר בא אברהם לראות את סדום ביום לאחר שהתפלל עליה: \u0003\"וישכם אברהם בבקר אל המקום אשר עמד שם\u0004 את פני ה' \"(בראשית יט, כז) ומתוך הענין, ואף מצד הלשון יודעים אנו ש\u0003אין\u0004 משמעות לשון \u0003\"עמידה\" אלא\u0004 ביטוי ל\u0003תפלה,\u0004 וכפי \u0003שנאמר\u0004 לשון זו בקשר לתפילת פינחס אחר המגיפה: \u0003\"ויעמד פינחס ויפלל ותעצר המגפה\"\"\u0004 (תהלים קו, ל). והרי שאברהם כבר נהג לעמוד בתפילה בשעות הבוקר.","\u0003יצחק תקן תפלת מנחה,\u0004 וכפי \u0003שנאמר \"ויצא יצחק לשוח בשדה לפנות ערב\"\u0004 (בראשית כד, סג), \u0003ואין\u0004 משמעות לשון \u0003\"שיחה\" אלא\u0004 ביטוי ל\u0003תפלה,\u0004 וכפי \u0003שנאמר \"תפלה לעני כי יעטף ולפני ה' ישפך שיחו\"\u0004 (תהלים קב, א). הרי שיצחק הוא הראשון ההולך לשוח—להתפלל לפנות ערב, בזמן המנחה.","ואילו \u0003יעקב תקן תפלת ערבית,\u0004 וכפי \u0003שנאמר: \"ויפגע במקום וילן שם\u0004 כי בא השמש\u0003\"\u0004 (בראשית כח, יא) \u0003ואין\u0004 משמעות לשון \u0003\"פגיעה\" אלא\u0004 ביטוי ל\u0003תפלה,\u0004 וכפי \u0003שנאמר\u0004 בדברי ה' לירמיהו: \u0003\"ואתה אל תתפלל בעד העם הזה ואל תשא בעדם רנה ותפלה ואל תפגע בי\u0004 כי אינני שומע אותך \u0003\" (ירמיהו ז, טז), הרי שיעקב התפלל בשעות בוא השמש —\u0004 שעת ערב.","\u0003ותניא כוותיה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יהושע בן לוי\u0004 שדיני התפילה נסמכים על דיני הקרבנות: \u0003מפני מה אמרו\u0004 חכמים שזמן \u0003תפלת השחר עד חצות\u0004 היום — \u0003שהרי\u0004 קרבן \u0003תמיד של שחר\u0004 אף שכרגיל מקריבים אותו בהשכמה, מותר שיהיה \u0003קרב והולך עד חצות. ור' יהודה אומר:\u0004 דעתי זו שזמן תפילת שחרית \u0003עד ארבע שעות\u0004 בלבד נסמכת על זה \u0003שהרי תמיד של שחר קרב והולך עד ארבע שעות.\u0004","\u0003ומפני מה אמרו\u0004 חכמים שזמן \u0003תפלת המנחה עד הערב\u0004 — \u0003שהרי\u0004 היא נסמכת על תמיד של בין הערביים, ו\u0003תמיד של בין הערבים קרב והולך עד הערב.\u0004 ו\u0003ר' יהודה אומר\u0004 שזמן תפילת המנחה \u0003עד פלג המנחה\u0004 בלבד, \u0003שהרי\u0004 לשיטתו \u0003תמיד של בין הערבים קרב והולך עד פלג המנחה.\u0004","\u0003ומפני מה אמרו\u0004 ש\u0003תפלת הערב אין לה קבע\u0004 — \u0003שהרי\u0004 על שריפת \u0003אברים ופדרים\u0004 (חלבי הקרבנות) \u0003שלא נתעכלו\u0004 באש המזבח \u0003מבערב,\u0004 שהם נשארים על המזבח ו\u0003קרבים והולכים כל הלילה.\u0004","\u0003ומפני מה אמרו\u0004 שהזמן \u0003של\u0004 תפילת ה\u0003מוספין כל היום\u0004 — \u0003שהרי קרבן של מוספין קרב כל היום.\u0004 ואילו לדעת \u0003ר' יהודה\u0004 ש\u0003אומר\u0004 שזמן תפילת המוספים הוא \u0003עד שבע שעות\u0004 ביום, זהו משום \u0003שהרי קרבן מוסף קרב והולך עד שבע שעות.\u0004 עוד שנינו בברייתא שלזמן המנחה שני מועדים, מנחה גדולה ומנחה קטנה.","ומבארים את ההבדל בזמן שניהם: \u0003ואיזו היא מנחה גדולה — משש שעות ומחצה\u0004 מהזריחה \u0003ולמעלה,\u0004 כלומר, חצי שעה אחרי חצות היום והלאה שהוא הזמן המוקדם ביותר שבו מקריבים תמיד של בין הערביים, בערב פסח שחל להיות בשבת. \u0003ואיזו היא מנחה קטנה\u0004 — \u0003מתשע שעות ומחצה\u0004 והלאה, שהוא הזמן שבו מקריבים כרגיל את קרבן התמיד של בין הערביים.","אגב הבאת הדברים \u0003איבעיא להו\u0004 \u0005[נשאלה להם],\u0006 לבני הישיבה שאלה זו: \u0003ר' יהודה\u0004 שקבע את זמן המנחה עד לפלג המנחה, האם \u0003פלג מנחה קמא\u0004 \u0005[ראשונה,\u0006 כלומר מנחה גדולה\u0005]\u0006 \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003או פלג מנחה אחרונה\u0004 (קטנה) \u0003קאמר\u0004 \u0005[אמר]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה מפורשת לכך בברייתא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: פלג המנחה אחרונה אמרו, והיא אחת עשרה שעות חסר רביע\u0004 אחר הזריחה (שהן שעה ורבע לפני השקיעה).","בכל אופן ברור כי ברייתא זו מסמיכה את דיני התפילות על הקרבנות, ומכאן ניתן לשאול: \u0003נימא תיהוי תיובתיה\u0004 \u0005[האם נאמר שתהיה\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003ר' יוסי בר' חנינא?\u0004 שלדעתו האבות הם שתיקנו את התפילות! על כך \u0003אמר ר' יוסי בר' חנינא: לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך,\u0004 אמנם \u0003תפלות, אבות תקנום,\u0004 אלא ש\u0003אסמכינהו רבנן אקרבנות\u0004 \u0005[הסמיכום חכמים על הקרבנות],\u0006 בקביעת זמנן ובשאר פרטים, אף כי אינם נובעים ממקור משותף. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כן]\u0006 שאף ר' יוסי בר' חנינא מסכים שיש בכל זאת קשר מסויים בין דיני הקרבנות והתפילות, \u0003תפלת מוסף ל\u0004דעת \u0003ר' יוסי בר' חנינא מאן\u0004 \u0005[מי]\u0006 \u0003תקנה,\u0004 שוודאי אינה נכנסת במסגרת תפילת האבות. \u0003אלא\u0004 ודאי אף לדעתו \u0003תפלות אבות תקנום, ואסמכינהו רבנן\u0004 \u0005[ו\u0006אחר כך \u0005הסמיכום חכמים]\u0006 על דיני ה\u0003קרבנות.\u0004","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 שזמן תפילת שחרית \u0003עד ארבע שעות\u0004 ביום. \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני הישיבה\u0005]\u0006 שאלה זו: האם \u0003\"עד\"\u0004 שאמר ר' יהודה האם הכוונה היא \u0003ועד בכלל,\u0004 שזמן תפילת שחרית כולל גם את השעה הרביעית, \u0003או דילמא\u0004 \u0005[שמא]\u0006 הכוונה היא \u0003עד ולא עד בכלל,\u0004 שכבר בשעה הרביעית עצמה אין להתפלל?! \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממה ששנינו במשנה ש\u0003ר' יהודה אומר\u0004 שזמן תפילת מנחה \u0003עד פלג המנחה.\u0004 ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שכוונתו \u0003עד ולא עד בכלל\u0004 — \u0003היינו דאיכא\u0004 \u0005[זהו שיש,\u0006 הבדל\u0005]\u0006 \u0003בין\u0004 שיטת \u0003ר' יהודה לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים].\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003עד ועד בכלל,\u0004 אם כן שיטת \u0003ר' יהודה\u0004"],["\u0003היינו\u0004 \u0005[זוהי]\u0006 ממש שיטת \u0003רבנן\u0004 \u0005[חכמים]!\u0006","את ההוכחה הזו דוחים מיד: \u0003אלא מאי\u0004 \u0005[מה],\u0006 אף אם נניח ש\u0003עד ולא עד בכלל,\u0004 גם אז לא יהיו הדברים מתקבלים שכן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את הסוף של המשנה\u0005]:\u0006 \u0003ו\u0004זמנם \u0003של\u0004 תפילות ה\u0003מוספין כל היום. ר' יהודה אומר: עד שבע שעות. ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003היו לפניו\u0004 חובת \u0003שתי תפלות, אחת של מוסף ואחת של מנחה\u0004 — \u0003מתפלל\u0004 בתחילה \u0003של מנחה ו\u0004רק \u0003אחר כך של מוסף,\u0004 כיון \u0003שזו,\u0004 המנחה, \u0003תדירה, וזו,\u0004 מוסף, \u0003אינה תדירה.\u0004 שתפילת המוסף מתפללים רק בשבתות בראשי חודשים ובמועדים, ויש איפוא לנהוג כפי הכלל שתדיר קודם לשאינו תדיר. \u0003ר' יהודה אומר: מתפלל\u0004 בתחילה \u0003של מוסף ו\u0004רק \u0003אחר כך של מנחה,\u0004 מאחר \u0003שזו,\u0004 מוסף, \u0003עוברת,\u0004 כלומר זמנה מוגבל יותר, \u0003וזו,\u0004 מנחה, \u0003אינה עוברת,\u0004 שעדיין יש שהות להתפלל מנחה עד זמן פלג המנחה.","והמסקנה הנוגעת לענייננו מדברים אלה היא: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי כשאומרים \u0003\"עד\"\u0004 הרי זה \u0003ועד בכלל, היינו דמשכחת\u0004 \u0005[זהו שאתה מוצא,\u0006 שאתה מסוגל למצוא\u0005]\u0006 \u0003להו שתי תפילות בהדי הדדי\u0004 \u0005[יחד].\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם תאמר]\u0006 כי \u0003\"עד\"\u0004 הוא \u0003ולא עד בכלל,\u0004 הרי \"עד שבע שעות\" משמעו עד תחילת השעה השביעית, עד חצות היום, ואם כן \u0003היכי משכחת להו\u0004 \u0005[איך תמצא אותן]\u0006 \u0003שתי תפלות בהדי הדדי\u0004 \u0005[יחד]?\u0006 שהלא \u0003כיון דאתיא\u0004 \u0005[שבאה]\u0006 \u0003לה\u0004 שעתה \u0003של\u0004 תפילת ה\u0003מנחה\u0004 שהיא חצי שעה לאחר חצות היום, כבר \u0003אזלא\u0004 \u0005[הלכה]\u0006 \u0003לה\u0004 שעתה \u0003של\u0004 תפילת ה\u0003מוספין.\u0004","\u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר, כי \u0003\"עד\"\u0004 הוא \u0003ועד בכלל,\u0004 אם כן \u0003קשיא רישא\u0004 \u0005[קשה ההתחלה]\u0006 כפי שבארנו קודם לגבי פלג המנחה, ו\u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל בהלכה \u0005יש]\u0006 \u0003בין\u0004 שיטת \u0003ר' יהודה ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]?\u0006 על כך משיבים: \u0003מי סברת דהאי\u0004 \u0005[האם סבור אתה שזה]\u0006 \u0003\"פלג מנחה\" פלג\u0004 מנחה \u0003אחרונה קאמר\u0004 \u0005[אמר]?\u0006 לא זו היתה כוונתו, כי אם \u0003פלג ראשונה קאמר\u0004 \u0005[אמר],\u0006 ו\"עד פלג המנחה\" פירושו עד אחרי חציה הראשון של שעת המנחה, \u0003ו\u0004אילו כאשר הזכיר אחת עשרה שעות \u0003הכי קאמר\u0004 \u0005[וכך אמר,\u0006 כך התכוון לומר\u0005]:\u0006 \u0003אימת נפיק\u0004 \u0005[אימתי יוצא]\u0006 \u0003פלג ראשונה ועייל\u0004 \u0005[ונכנס]\u0006 \u0003פלג אחרונה\u0004 — \u0003מכי נפקי\u0004 \u0005[מכאשר,\u0006 מהזמן בו יוצאות] \u0003אחת עשרה שעות חסר רביע.\u0004 ואם כן נמצא סגנון דבריו של ר' יהודה אחיד, וכוונתו תמיד \"עד ועד בכלל\".","המסקנה המעשית אשר הועלתה מהדיון בדברי ר' יהודה היא שלדבריו מותר להתפלל שחרית עד סוף ארבע שעות ביום. כסיוע לדבר \u0003אמר רב נחמן: אף אנן נמי תנינן\u0004 \u0005[אנחנו גם כן שנינו]\u0006 ענין זה במשנה במסכת עדויות.","ששנינו ש\u0003ר' יהודה בן בבא העיד על חמשה דברים\u0004 בהלכה: ילדה יתומה לפני בגרותה שהשיאו אותה אמה או אחיה, וכשהיא מגיעה לבגרות יכולה היא למאן לחיות עם בעלה, ועל ידי זה להפקיע את קשר הנישואין ביניהם מעיקרו. כרגיל מתרחקים מן המיאונים, ואולם במקרים מסויימים מתברר כי אם יהיו נישואיה של ילדה זו בעלי תוקף, יגרום הדבר לבעיה ביחס לחליצה ויבום. על מקרים אלה העיד ר' יהודה בן בבא \u0003שממאנין,\u0004 כלומר משדלים \u0003את הקטנה\u0004 שתמאן בבעלה. ועל ידי כך יפתר הסיבוך בנושא זה. \u0003ו\u0004עוד העיד \u0003שמשיאין את האשה\u0004 שרצתה להינשא שנית לאחר ששמעה על מות בעלה, \u0003על פי עד אחד,\u0004 ואין דורשים כאן (כבשאר עדויות שבתורה) שני עדים כשרים. \u0003ו\u0004עוד העיד מענין מעשה \u0003על תרנגול שנסקל בירושלים על שהרג את הנפש.\u0004 ללמדנו, שהדין בתורה (שמות כא, כח) המחייב לסקול שור שהרג אדם, כולל גם את שאר בעלי החיים \u0003ו\u0004כן העיד \u0003על יין בן ארבעים יום שנתנסך על גבי המזבח. ו\u0004כן העיד \u0003על\u0004 מעשה שהיה ב\u0003תמיד של שחר שקרב\u0004 (הוקרב) \u0003בארבע שעות\u0004 ביום.","מעדות אחרונה זו, שהיא על פי שיטתו של ר' יהודה (שהרי לא העיד על שעה מאוחרת מזו) \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי אכן \u0003\"עד ועד בכלל\".\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","מתוך הסתמכות על משנה זו \u0003אמר רב כהנא: הלכה כר' יהודה, הואיל ותנן בבחירתא כוותיה\u0004 \u0005[ושנינו ב\u0006משנה \u0005המובחרת\u0006 במסכת עדויות \u0005כמותו],\u0006 ומאחר שנפסקה הלכה ככל המשניות במסכת עדויות, הרי שדברי תנא הנוטים לשיטת ר' יהודה משמעותם ההלכתית פסיקת ההלכה כדעתו.","על סמך דברים אלה נגשים עתה לברר \u0003ועל התמיד של שחר שקרב בארבע שעות, מאן תנא להא דתנן\u0004 \u0005[מי שנה את\u0006 המשנה הזו ששנינו] על הנאמר במן שירד לבני ישראל במדבר. הפסוק \u0003\"\u0004וילקטו אותו בבוקר בבוקר איש כפי אכלו \u0003וחם השמש ונמס\"\u0004 (שמות טז, כא), ולדעת תנא זה שעה זו היתה \u0003בארבע שעות\u0004 ביום.","ותוהים: \u0003אתה אומר\u0004 ששעה זו שבה \"חם השמש\" היא \u0003בארבע שעות, או אינו\u0004 כן אלא ששעה זו הריהי \u0003בשש שעות?!\u0004 אלא \u0003כשהוא,\u0004 הכתוב \u0003אומר \"כחם היום\"\u0004 (בראשית יח, א) \u0003הרי שש שעות\u0004 כבר \u0003אמור,\u0004 ששעה זו מכונה במקרא \"כחום היום\", \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה,\u0004 באיזו דרך \u0003אני מקיים\u0004 את דברי הכתוב \u0003\"וחם השמש ונמס\"\u0004 — בזמן מוקדם יותר, כלומר, \u0003בארבע שעות.\u0004 ומעתה \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]\u0006 ברייתא זו? שהרי אינה \u0003לא\u0004 כשיטת \u0003ר' יהודה ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 שכן \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' יהודה\u0004 היא — הלא \u0003עד ארבע שעות נמי צפרא\u0004 \u0005[גם כן בוקר]\u0006 \u0003הוא!\u0004 שהרי לדעתו עדיין מקריבים אז תמיד של שחר, והרי נאמר שהלקיטה עצמה היתה בבוקר. \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — הלא \u0003עד חצות נמי צפרא\u0004 \u0005[גם כן בוקר]\u0006 \u0003הוא,\u0004 שהרי לדעתם קרבן תמיד של שחר קרב עד חצות היום, ולכאורה אם כן לפנינו שיטה חדשה לגמרי.","על כך משיבים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 ופרש את הדבר כשיטת \u0003ר' יהודה, אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 ופרש את הדבר כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 ומפרטים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שזו שיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 ופרש כך: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"בבקר בבקר\"\u0004 (\"וילקטו אותו בבוקר בבוקר איש כפי אכלו וחם השמש ונמס\". להורות שהלקיטה היתה בשעות הבוקר המוקדמות, ו\u0003חלקהו,\u0004 את הבוקר — הנמשך לדעת חכמים עד חצות — \u0003לשני בקרים,\u0004 ו\"בבוקר בבוקר\" פירושו: חציו הראשון של הבוקר — עד תחילת ארבע שעות. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כשיטת \u0003ר' יהודה,\u0004 ופירוש הדבר לשיטתו הוא: \u0003האי\u0004 \u0005[זו]\u0006 המלה \u0003\"בקר\"\u0004 שהיא \u0003יתירא\u0004 \u0005[יתירה]\u0006 בכתוב \"בבוקר בבוקר\" משמעו — \u0003להקדים לו שעה אחת.\u0004 על כל פנים \u0003דכולי עלמא מיהא\u0004 \u0005[לדעת הכל לפחות]\u0006 \u0003\"וחם השמש ונמס\"\u0004 הריהו \u0003בארבע שעות\u0004 ביום.","ועל כך שואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות]?\u0006 כלומר, כיצד נובע דבר זה מן הכתוב? \u0003אמר ר' אחא בר יעקב: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וחם השמש ונמס\",\u0004 ואפשר ללמוד מדיוק לשון הכתוב — \u0003איזו היא שעה שהשמש חם ו\u0004אולם עדיין \u0003הצל צונן\u0004 (ולא הגיע ל\"כחום היום\" שהכל חם) — \u0003הוי אומר בארבע שעות.\u0004","שנינו במשנה שלדעת התנא קמא \u0003תפלת המנחה\u0004 זמנה \u0003עד הערב,\u0004 ולדעת ר' יהודה זמנה עד פלג המנחה בלבד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב יצחק: התם\u0004 \u0005[שם]\u0006 בענין תפילת שחרית \u0003אמר רב כהנא\u0004 ש\u0003הלכה כר' יהודה, הואיל ותנן בבחירתא כוותיה\u0004 \u0005[ושנינו ב\u0006משנה \u0005המובחרת\u0006 במסכת עדויות \u0005כמותו]\u0006 ואולם \u0003הכא מאי\u0004 \u0005[כאן מה,\u0006 נפסוק\u0005]?\u0006 \u0003אישתיק\u0004 \u0005[שתק]\u0006 \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר],\u0006 משום שלא היתה בידו הלכה קבועה בנושא זה. על כן \u0003אמר רב חסדא: נחזי אנן\u0004 \u0005[נראה אנחנו],\u0006 כלומר, ננסה אנו עצמנו לפתור את הבעיה \u0003מ\u0004העובדה ש\u0003רב מצלי\u0004 \u0005[היה מתפלל]\u0006 תפילה של \u0003שבת בערב שבת מבעוד יום,\u0004 וממנהגו זה \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 ש\u0003הלכה כר' יהודה\u0004 שזמן תפילת המנחה מסתיים בפלג המנחה, ומאז אפשר להתחיל להתפלל ערבית.","את ההוכחה הזו ממנהגו של רב דוחים מיד: \u0003אדרבה\u0004 (להיפך) מהעובדה ש\u0003רב הונא ורבנן\u0004 \u0005[וחכמים],\u0006 תלמידיו של רב, \u0003לא הוו מצלו\u0004 \u0005[היו מתפללים]\u0006 \u0003עד אורתא\u0004 \u0005[הערב],\u0006 \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003אין הלכה כר' יהודה.\u0004 ועל כן אין להביא מכאן כל ראיה גמורה. ומסכמים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003לא אתמר הלכתא\u0004 \u0005[נאמרה הלכה]\u0006 \u0003לא כמר\u0004 \u0005[כחכם זה]\u0006 \u0003ולא כמר\u0004 \u0005[כחכם זה],\u0006 \u0003דעבד כמר [\u0004מי \u0005שעשה כחכם זה]\u0006 — \u0003עבד\u0004 \u0005[עשה],\u0006 \u0003ודעבד כמר [ו\u0004מי \u0005שעשה כחכם זה]\u0006 — \u0003עבד\u0004 \u0005[עשה],\u0006 שהלכה זו הושארה תלויה בהחלטתו של כל אדם.","מסופר: \u0003רב איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 החכם \u0003גניבא וצלי\u0004 \u0005[והתפלל]\u0006 תפילה \u0003של שבת בערב שבת, והוה מצלי\u0004 \u0005[והיה מתפלל]\u0006 \u0003ר' ירמיה בר אבא לאחורי\u0004 \u0005[אחורי]\u0006 \u0003רב, וסיים רב\u0004 תפילתו \u0003ולא פסקיה לצלותיה\u0004 \u0005[הפסיק את תפילתו]\u0006 של ר' ירמיה, שלא פסע לאחוריו לפני \u0003ר' ירמיה.\u0004 ומסיפור זה \u0003שמע מינה תלת\u0004 \u0005[למד ממנה שלושה\u0006 דברים\u0005]:\u0006 ראשית, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שמלכתחילה \u0003מתפלל אדם\u0004 תפילה \u0003של שבת בערב שבת.\u0004 שמותר להתפלל תפילה שבת בערב שבת. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 ש\u0003מתפלל תלמיד אחורי רבו,\u0004 ואין בכך משום פגיעה בכבוד הרב. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 ש\u0003אסור לעבור כנגד המתפללין\u0004 שמונה עשרה, בשעת תפילתם.","ומעירים: דבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' יהושע בן לוי.\u0004 ש\u0003אמר ר' יהושע בן לוי: אסור לעבור כנגד המתפללין.\u0004 על כך שואלים \u0003איני\u0004 \u0005[וכן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' אמי ור' אסי חלפי\u0004 לפני המתפללים. ומשיבים: \u0003ר' אמי ור' אסי\u0004 — \u0003חוץ לארבע אמות\u0004 מן המתפללים \u0003הוא דחלפי\u0004 \u0005[שהיו עוברים].\u0006","פרט אחר בסיפור זה עורר אף הוא תמיהה: \u0003ור' ירמיה היכי עביד הכי\u0004 \u0005[כיצד עשה כך]\u0006 שהתפלל אחורי רב?! \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר רב: לעולם אל יתפלל אדם\u0004"],["\u0003לא כנגד רבו,\u0004 כלומר, סמוך לרבו, שמראה בכך שהוא כשווה לרבו, \u0003ולא אחורי רבו\u0004 שהוא נראה כאילו היה משתחוה לרבו (תוס').","\u0003ותניא\u0004 \u0005[ושנויה\u0006 הלכה זו בברייתא\u0005]\u0006 ביתר תוקף, ש\u0003ר' אליעזר אומר: המתפלל אחורי רבו, והנותן שלום לרבו\u0004 ואינו ממתין עד שיקדים רבו לשאול בשלומו, \u0003והמחזיר שלום לרבו\u0004 ואינו אומר \"שלום עליך רבי\", \u0003והחולק על ישיבתו של רבו,\u0004 שהוא קובע לעצמו ישיבה ומלמד בחיי רבו שלא ברשותו (רמב\"ם), \u0003והאומר דבר שלא שמע מפי רבו\u0004 בשם הרב — \u0003גורם לשכינה שתסתלק מישראל!\u0004","את התנהגותו של ר' ירמיה מסבירים כי \u0003שאני\u0004 \u0005[שונה]\u0006 הוא \u0003ר' ירמיה בר אבא\u0004 מפני שלא היה תלמידו המובהק של רב כי אם אך \u0003תלמיד חבר הוה\u0004 \u0005[היה]\u0006 לו, ולכן יכול היה לנהוג כן. \u0003והיינו דקאמר ליה\u0004 \u0005[וזהו שאמר לו]\u0006 \u0003ר' ירמיה בר אבא לרב,\u0004 ושאל אותו כאשר הקדים רב להתפלל תפילת שבת, בלשון זו: \u0003מי\u0004 \u0005[האם]\u0006 \u0003בדלת\u0004 ממלאכה, וקבלת עליך כבר קדושת השבת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003אין, בדילנא\u0004 \u0005[כן, בדלתי],\u0006 \u0003ולא אמר\u0004 אליו בלשון \u0003\"מי בדיל מר\"\u0004 \u0005[\"האם בדל אדוני\"]?\u0006 כדרך שהיה צריך לומר אם היה תלמידו.","רב אמנם השיב כי הפסיק ממלאכת החול, \u0003ו\u0004אולם \u0003מי בדיל\u0004 \u0005[האם בדל]?\u0006 האם היה צריך באמת להפסיק מן המלאכה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבין: פעם אחת התפלל רבי\u0004 תפילה \u0003של שבת בערב שבת, ונכנס\u0004 אחר כך \u0003למרחץ, ויצא ושנה לן פרקין\u0004 \u0005[לנו\u0006 את \u0005פרקנו,\u0006 מה שלמדנו\u0005],\u0006 \u0003ועדיין לא חשכה! אמר רבא: ההוא\u0004 \u0005[אותו]\u0006 מקרה מדובר ש\u0003נכנס להזיע, וקודם גזירה\u0004 שגזרו חכמים לאסור הזעה בשבת \u0003הוה\u0004 \u0005[היה]\u0006 הדבר.","ועוד שואלים: \u0003איני\u0004 \u0005[האומנם]\u0006 היה צריך להפסיק מן המלאכה, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי שרא ליה\u0004 \u0005[התיר לו]\u0006 \u0003לרב דימי בר ליואי לכברויי סלי\u0004 \u0005[לעשן סלים בגפרית]\u0006 אף על פי שכבר התפלל תפילת שבת, והרי שגם אחר תפילת שבת עדיין מותר בעשיית מלאכה!","על כך משיבים: המקרה \u0003ההוא טעותא הוי\u0004 \u0005[טעות היה],\u0006 שלא נתכוון רב דימי במה שהתפלל מוקדם יותר להוסיף על השבת, כי אם סבר בטעות שכבר שקעה השמש, שהיה אותו היום מעונן ולכן התפלל. ואולם אף שהתפלל, אין תפילת השבת מחייבת אותו לנהוג בקדושת שבת, ולכן יכול היה עוד לעשות מלאכה אחרי תפילתו.","על כך מוסיפים ושואלים: \u0003וטעותא מי הדרא\u0004 \u0005[וטעות האם\u0006 היא \u0005חוזרת]?\u0006 וכי אפשר לנהוג כאילו לא התפלל כלל? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר אבידן\u0004 תלמידו של רבי: \u0003פעם אחת נתקשרו שמים בעבים,\u0004 ולכך \u0003כסבורים\u0004 היו \u0003העם לומר\u0004 כי \u0003חשכה הוא, ו\u0004מאחר שכן \u0003נכנסו לבית הכנסת\u0004 והקדימו \u0003והתפללו\u0004 תפילה \u0003של מוצאי שבת בשבת. ו\u0004לאחר זמן, כש\u0003נתפזרו העבים וזרחה החמה,\u0004 התברר שעדיין יום היה,","\u0003ובאו ושאלו את רבי\u0004 מה יעשו. \u0003ואמר: הואיל והתפללו\u0004 — התפללו, ואינם צריכים לחזור ולהתפלל, הרי אף שהתפללו בטעות אין מחזירים טעות זו, ואין מבטלים את המעשה מעיקרו! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 ה\u0003צבור, דלא מטרחינן להו\u0004 \u0005[שאין אנו מטריחים אותו]\u0006 להתפלל שנית תפילה שלמה.","וממשיכים לדון באפשרות להקדים תפילת ערבית אף במקרה של שבת מכמה צדדים. \u0003אמר ר' חייא בר אבין: רב צלי\u0004 \u0005[התפלל]\u0006 תפילה \u0003של שבת בערב שבת, ור' יאשיה מצלי\u0004 \u0005[היה מתפלל]\u0006 תפילה \u0003של מוצאי שבת ב\u0004תוך ה\u0003שבת.\u0004 ביחס למה ש\u0003רב צלי\u0004 \u0005[התפלל]\u0006 תפילה \u0003של שבת בערב שבת,\u0004 נשאלת השאלה: האם עוד בערב שבת \u0003אומר,\u0004 כלומר, יכול הוא לומר \u0003קדושה על הכוס\u0004 (קידוש של שבת), או \u0003אינו אומר קדושה על הכוס\u0004 ועליו להמתין עד צאת הכוכבים? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר רב נחמן אמר שמואל: מתפלל אדם\u0004 תפילה \u0003של שבת בערב שבת ואומר קדושה על הכוס. ו\u0004נפסק ש\u0003הלכתא כוותיה\u0004 \u0005[הלכה כמותו]\u0006 בענין זה.","שאלה מעין זו נשאלה גם ביחס למה ש\u0003ר' יאשיה מצלי\u0004 \u0005[היה מתפלל]\u0006 תפילה \u0003של מוצאי שבת ב\u0004תוך ה\u0003שבת:\u0004 האם \u0003אומר\u0004 אחר תפילתו עוד מבעוד יום \u0003הבדלה על הכוס או אינו אומר הבדלה על הכוס? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר רב יהודה אמר שמואל: מתפלל אדם\u0004 תפילה \u0003של מוצאי שבת בשבת ואומר הבדלה על הכוס.\u0004","\u0003אמר ר' זירא אמר ר' אסי אמר ר' אלעזר אמר ר' חנינא אמר רב: בצד עמוד זה\u0004 (עמוד מסויים שהראו עליו) \u0003התפלל ר' ישמעאל בר' יוסי\u0004 תפילה \u0003של שבת בערב שבת. ו\u0004אולם","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003עולא\u0004 מארץ ישראל לבבל היתה בידו גירסה אחרת לגמרי של סיפור זה ו\u0003אמר\u0004 כפי המסורת שהיתה בידו: \u0003בצד תמרה הוה\u0004 \u0005[היה],\u0006 מעשה זה \u0003ולא בצד\u0004 ה\u0003עמוד הוה\u0004 \u0005[היה].\u0006 \u0003ולא\u0004 ב\u0003ר' ישמעאל בר' יוסי הוה\u0004 \u0005[היה]\u0006 מעשה זה, \u0003אלא\u0004 ב\u0003ר' אלעזר בר' יוסי הוה\u0004 \u0005[היה],\u0006 \u0003ולא\u0004 תפילה \u0003של שבת בערב שבת\u0004 היתה זו, \u0003אלא\u0004 תפילה \u0003של מוצאי שבת בשבת הוה\u0004 \u0005[היה],\u0006 זה.","שנינו במשנה ש\u0003תפלת הערב אין לה קבע.\u0004 ושואלים: \u0003מאי\u0004 \u0005(מה\u0006 פירוש\u0005]\u0006 \u0003\"אין לה קבע\"? אילימא דאי בעי מצלי כוליה ליליא\u0004 \u0005[אם לומר\u0006 שהפירוש הוא \u0005שאם\u0006 הוא \u0005רוצה יכול\u0006 הוא \u0005להתפלל כל הלילה],\u0006 אם כן \u0003ליתני\u0004 \u0005[שישנה\u0006 במשנה\u0005]\u0006 בלשון \u0003\"תפלת הערב כל הלילה\"! אלא מאי\u0004 \u0005[מה\u0006 הפירוש\u0005]\u0006 \u0003\"אין לה קבע\"\u0004 —","\u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר],\u0006 כאותו חכם שפסק ש\u0003תפלת ערבית רשות.\u0004 שכן \u0003אמר רב יהודה אמר שמואל:\u0004 מסורת היא שבענין \u0003תפלת ערבית\u0004 נחלקו חכמי המשנה: \u0003רבן גמליאל אומר\u0004 שהיא \u0003חובה,\u0004 ו\u0003ר' יהושע אמר\u0004 ש\u0003רשות\u0004 היא. \u0003אמר אביי: הלכה כדברי האומר\u0004 שתפילת ערבית \u0003חובה. ורבא אמר: הלכה כדברי האומר\u0004 שתפילת ערבית \u0003רשות.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003מעשה בתלמיד אחד שבא לפני ר' יהושע. אמר לו\u0004 אותו תלמיד: \u0003תפלת ערבית רשות או חובה? אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003רשות.\u0004","שוב \u0003בא\u0004 אותו תלמיד \u0003לפני רבן גמליאל, אמר לו\u0004 אותו תלמיד: \u0003תפלת ערבית רשות או חובה? אמר לו\u0004 רבן גמליאל: \u0003חובה. אמר לו\u0004 אותו תלמיד לרבן גמליאל: \u0003והלא ר' יהושע אמר לי\u0004 שתפילת ערבית \u0003רשות?! אמר לו\u0004 רבן גמליאל לאותו תלמיד: \u0003המתן עד שיכנסו בעלי תריסין\u0004 \u0005[המגינים],\u0006 כינוי מליצי לתלמידי החכמים שהם \"לוחמים במלחמתה של תורה\", \u0003לבית המדרש,\u0004 ואז אפשר יהיה לדון בנושא.","\u0003כשנכנסו בעלי תריסין עמד השואל\u0004 וחזר \u0003ושאל\u0004 במעמד כולם: \u0003תפלת ערבית רשות או חובה? אמר לו רבן גמליאל: חובה. אמר להם רבן גמליאל לחכמים: כלום יש אדם שחולק בדבר זה?\u0004 שרצה לברר אם ר' יהושע עדיין מחזיק בדעתו. נענה ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהושע: לאו\u0004 \u0005[לא],\u0006 אין מי שחולק על דעה זו. שמשום כבוד הנשיא לא רצה להתוכח עמו בהזדמנות זו (צל\"ח). \u0003אמר לו\u0004 רבן גמליאל לר' יהושע: \u0003והלא משמך אמרו לי\u0004 שתפילת ערבית \u0003רשות!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן גמליאל לר' יהושע: \u0003יהושע, עמוד על רגליך ויעידו בך. עמד ר' יהושע על רגליו ואמר אלמלא אני חי והוא\u0004 (התלמיד) \u0003מת\u0004 — \u0003יכול החי להכחיש את המת.\u0004 והייתי יכול לומר שלא כך פסקתי, \u0003ועכשיו שאני חי והוא חי\u0004 — \u0003היאך יכול החי להכחיש את החי?\u0004 ובעל כרחי עלי להודות שכך אמרתי.","ובינתיים \u0003היה רבן גמליאל\u0004 ראש הישיבה \u0003יושב ודורש, ור' יהושע עומד על רגליו,\u0004 שכעונש לא הורה לו רבן גמליאל לשבת, ומפני כבוד הנשיא נשאר עומד. דבר זה נמשך זמן רב כל כך עד שהתעוררה בתוך כל קהל השומעים, החכמים ותלמידיהם שהיו במקום, התמרמרות רבה על רבן גמליאל \u0003עד שרננו כל העם ואמרו לחוצפית התורגמן: עמוד!\u0004 כלומר הפסק לתרגם את דברי רבן גמליאל. ואז המתורגמן פסק מתרגומו.","ומסופר כי בתוך כדי ההתמרמרות \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003עד כמה נצעריה וניזיל\u0004 \u0005[יצערנו וילך],\u0006 הלא \u0003בראש השנה אשתקד צעריה\u0004 \u0005[ציערו]\u0006 כשהורה עליו לבוא בתרמילו ביום בו חל יום הכיפורים לפי חשבונו של ר' יהושע. ו\u0003בבכורות במעשה\u0004 שהיה בשאלתו של \u0003ר' צדוק צעריה\u0004 \u0005[ציערו],\u0006 כמו בפעם זו כשאמר לו לעמוד על רגליו כעונש על שהתחמק מלעמוד לויכוח על דעתו השונה. \u0003הכא נמי צעריה\u0004 \u0005[כאן גם כן ציערו]\u0006 ואם כן, \u0003תא ונעבריה\u0004 \u0005[בואו ונעבירנו,\u0006 ממשרתו כנשיא\u0005]!\u0006","וכך הוסכם אלא שהתעוררה השאלה \u0003מאן נוקים ליה\u0004 \u0005[\u0006את \u0005מי נעמיד לו,\u0006 במקומו\u0005]\u0006 אם \u0003נוקמיה\u0004 \u0005[נעמידו]\u0006 את \u0003ר' יהושע\u0004 — הלא \u0003בעל מעשה\u0004 זה עצמו \u0003הוא,\u0004 שהרי בגללו מעבירים את רבן גמליאל, ויצטער רבן גמליאל על כך ביותר. ואם \u0003נוקמיה\u0004 \u0005[נעמידו]\u0006 את \u0003ר' עקיבא\u0004 — \u0003דילמא עניש ליה\u0004 \u0005[שמא יעניש אותו],\u0006 רבן גמליאל, ועל ידי ההקפדה עליו יגרום שיענישו אותו משמים, משום \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 לר' עקיבא \u0003זכות אבות\u0004 שתגן זכותם עליו, שכן היה ר' עקיבא ממשפחת גרים.","\u0003 אלא נוקמיה\u0004 \u0005[נעמידו]\u0006 את \u0003ר' אלעזר בן עזריה,\u0004 שיש בו צירוף של מעלות שונות שבאחרים שהוזכרו אינן קיימות. שכן, \u0003הוא חכם, והוא עשיר, והוא\u0004 דור \u0003עשירי לעזרא.\u0004 ומפרטים: \u0003הוא חכם\u0004 — \u0003דאי מקשי ליה, מפרק ליה\u0004 \u0005[שאם יקשה לו, יתרץ לו]\u0006 ולא יוכל רבן גמליאל להביכו בקושיות. \u0003והוא עשיר\u0004 — \u0003דאי אית ליה לפלוחי לבי קיסר, אף הוא איזיל ופלח\u0004 \u0005[שאם יש לו לעבוד,\u0006 להשתדל ולשאת ולתת, \u0005בבית הקיסר,\u0006 כנציג ישראל, \u0005אף הוא יכול ללכת ולעבוד],\u0006 שבידו הרכוש המספיק הן לצרכי הנסיעות הארוכות והן למיסים ולמתנות. \u0003והוא עשירי לעזרא\u0004 — \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003זכות אבות, ולא מצי עניש ליה\u0004 \u0005[יוכל להעניש אותו].\u0006 \u0003אתו\u0004 \u0005[באו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 האם \u0003ניחא ליה למר דליהוי ריש מתיבתא\u0004 \u0005[נוח לו לאדוני שיהא ראש ישיבה]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003איזיל ואימליך באינשי\u0004 \u0005[אלך ואתייעץ עם אנשי]\u0006 \u0003ביתי. אזל ואמליך בדביתהו\u0004 \u0005[הלך והתייעץ עם אשתו].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006"],["יש לכאורה חשש \u0003דלמא מעברין לך\u0004 \u0005[שמא יעבירו אותך]\u0006 ממשרה זו כדרך שהעבירו את רבן גמליאל. \u0003אמר לה\u0004 לפי הפתגם העממי: \u0003לשתמש אינש יומא חדא בכסא דמוקרא, ולמחר ליתבר\u0004 \u0005[ישתמש אדם יום אחד בכוס יקרה, ולמחר תישבר],\u0006 כלומר, יש לאדם לנצל הזדמנות הבאה לו ואל לו לחשוש שמא לא תמשך בעתיד. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לית\u0004 \u0005[אין]\u0006 \u0003לך חיורתא\u0004 \u0005[לובן],\u0006 כלומר, שערות לבנות, ואין זה נאה שבראש החכמים יעמוד איש צעיר שעדיין לא הלבין שערו. ומסופר, \u0003ההוא יומא בר תמני סרי שני הוה, אתרחיש ליה ניסא ואהדרו ליה תמני סרי דרי חיורתא\u0004 \u0005[אותו יום בן שמונה עשרה שנה היה, התרחש לו נס וזרו\u0006 והשתנו \u0005לו שמונה עשרה שורות\u0006 של שערות \u0005לובן].\u0006 ומעירים: \u0003היינו דקאמר\u0004 \u0005[זהו שאמר]\u0006 \u0003ר' אלעזר בן עזריה: הרי אני כבן שבעים שנה. ולא\u0004 אמר \u0003\"בן שבעים שנה\",\u0004 מפני שנראה היה זקן הרבה מגילו האמיתי.","\u0003תנא\u0004 \u0005[שנינו]\u0006 כי ב\u0003אותו היום\u0004 שהעבירו את רבן גמליאל מנשיאותו והעמידו במקומו את ר' אלעזר בן עזריה בא גם שינוי יסודי בגישה הכוללת של בית המדרש, שכן \u0003סלקוהו לשומר הפתח ונתנה להם רשות לתלמידים להכנס.\u0004 שבמקום גישתו של רבן גמליאל שיש לבאר היטב את התלמידים נקטו בשיטה שכל הרוצה ללמוד יש לתת לו הזדמנות. \u0003ש\u0004כן \u0003היה רבן גמליאל מכריז ואומר: כל תלמיד שאין תוכו כברו,\u0004 ואינו שלם במדותיו ובלימודיו \u0003לא יכנס לבית המדרש.\u0004","ומסופר כי \u0003ההוא יומא אתוספו\u0004 \u0005[אותו היום נוספו]\u0006 \u0003כמה ספסלי\u0004 [ספסלים] לבית המדרש מהתרבות התלמידים. \u0003אמר ר' יוחנן: פליגי\u0004 \u0005[חלוקים]\u0006 \u0003בה\u0004 בשאלה זו \u0003אבא יוסף בן דוסתאי ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי \u0003אתוספו\u0004 \u0005[נוספו]\u0006 לבית המדרש \u0003ארבע מאה ספסלי\u0004 \u0005[מאות ספסלים].\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי \u0003אתוספו\u0004 \u0005[נוספו]\u0006 לבית המדרש \u0003שבע מאה ספסלי\u0004 \u0005[מאות ספסלים].\u0006 כאשר ראה רבן גמליאל את הריבוי העצום במספר התלמידים \u0003הוה קא חלשה דעתיה\u0004 \u0005[חלשה דעתו]\u0006 של \u0003רבן גמליאל, אמר: דלמא\u0004 \u0005[שמא]\u0006 \u0003חס ושלום מנעתי תורה מישראל. אחזו ליה בחלמיה חצבי חיורי דמליין קטמא\u0004 \u0005[הראו לו בחלומו כדים לבנים שמלאים אפר]\u0006 לרמז שאותם תלמידים שנוספו אינם אלא אנשים ריקנים חסרי ערך. ומעירים על כך בגמרא: \u0003ולא היא,\u0004 לא כך היה הדבר, אלא \u0003ההיא\u0004 \u0005[אותו]\u0006 חלום כדי \u0003ליתובי דעתיה\u0004 \u0005[ליישב\u0006 את \u0005דעתו]\u0006 שלא יצטער, \u0003הוא דאחזו ליה\u0004 \u0005[שהראו לו].\u0006","\u0003תנא\u0004 \u0005[שנינו]:\u0006 קבלה היא במסורת שמסכת \u0003עדיות בו ביום נשנית. וכל היכא דאמרינן\u0004 \u0005[מקום\u0006 במשנה או בברייתא \u0005שאנו אומרים]\u0006 לשון \"\u0003בו ביום\", ההוא יומא הוה\u0004 \u0005[אותו היום היה].\u0006 \u0003ו\u0004בגלל התרבות תלמידי החכמים, והגישה החדשה בבית המדרש \u0003לא היתה הלכה שהיתה תלויה\u0004 (מסופקת) \u0003בבית המדרש שלא פירשוה,\u0004 והגיעו בה לכלל מסקנה הלכה למעשה. \u0003ואף רבן גמליאל לא מנע עצמו מבית המדרש אפילו שעה אחת,\u0004 שלא נטר שנאה או קנאה למדיחיו ונשאר יושב כאחד מבני החבורה, בבית המדרש, ועסק עימם בבירור ההלכה.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בו ביום\u0004 (וכאמור: \"בו ביום\" — הוא יום הדחת רבן גמליאל) \u0003בא יהודה\u0004 שהיה \u0003גר עמוני לפניהם,\u0004 לפני התלמידים \u0003בבית המדרש\u0004. \u0003ואמר להם: מה אני לבא בקהל?\u0004 כלומר, האם מותר לי לשאת בת ישראל?","\u0003אמר לו רבן גמליאל: אסור אתה לבא בקהל. אמר לו ר' יהושע: מותר אתה לבא בקהל. אמר לו רבן גמליאל\u0004 לר' יהושע: \u0003והלא כבר נאמר \"לא יבא עמוני ומואבי בקהל ה'\u0004 גם דור עשירי לא יבוא להם בקהל ה' עד עולם\u0003\"\u0004 (דברים כג, ד), וכיצד אפשר להתירו לקהל? \u0003אמר לו ר' יהושע: וכי עמון ומואב במקומן הן יושבין?\u0004 הרי \u0003כבר עלה סנחריב מלך אשור ובלבל את כל האומות,\u0004 והושיב עמים אחרים במקום יושבי עמון, ואם כן יושבי עמון ומואב באותה תקופה אינם עמונים ומואבים על פי גזעם, \u0003שנאמר\u0004 על סנחריב: \u0003\"ואסיר גבלות עמים ועתודותיהם שושתי ואוריד כביר יושבים\"\u0004 (ישעיהו י, יג). \u0003ו\u0004אף שיתכן שאותו גר הוא כן מצאצאיהם, מכל מקום אין לחשוש לכך שכן כלל הוא בהלכה ש\u0003כל דפריש\u0004 \u0005[הפורש]\u0006 — \u0003מרובא פריש\u0004 \u0005[מן הרוב\u0006 הוא \u0005פורש],\u0006 ואנו מניחים כי פרט היוצא מתוך תערובת שאין אנו מבחינים בין האסור והמותר שבה, יש לשער כי הוא היה שייך לרוב. ועל כן, מאחר שגרים מרוב האומות מותרים לבוא בקהל, גם גר זה שאין אנו יודעים את מוצאו הגזעי יש להתירו בקהל.","\u0003אמר לו רבן גמליאל: והלא כבר נאמר \"ואחרי כן אשיב את שבות בני עמון נאם ה'\"\u0004 (ירמיהו מט, ו), וודאי חזרו כבר העמונים המקוריים לארצם, וגר זה הוא איפוא מצאצאיהם! \u0003אמר\u0004","\u0003לו ר' יהושע:\u0004 אין מכאן ראייה, שכן \u0003והלא כבר נאמר\u0004 בנבואה גם כן \u0003\"ושבתי את שבות עמי ישראל\u0004 ובנו ערים נשמות וישבו ונטעו כרמים ושתו את יינם ועשו גנות ואכלו את פריהם\u0003\"\u0004 (עמוס ט, יד) \u0003ועדיין לא שבו,\u0004 ואין לנו אם כן להתחשב אלא בדברים שיודעים אנו בבטחה שקרו. \u0003מיד התירוהו לבא בקהל.\u0004 ואגב הדברים למדנו שאף באותם הימים ישב רבן גמליאל כרגיל בבית המדרש ונשא ונתן בהלכה.","\u0003אמר רבן גמליאל\u0004 בלבו: \u0003הואיל והכי הוה\u0004 \u0005[וכך היה]\u0006 שהעם כולו נטה אחרי ר' יהושע סימן הוא לצדקתו, ואם כן ראוי הוא כי \u0003איזיל ואפייסיה\u0004 \u0005[אלך ואפייסו]\u0006 \u0003לר' יהושע. כי מטא לביתיה, חזינהו לאשיתא דביתיה דמשחרן\u0004 \u0005[כאשר הגיע לביתו\u0006 של ר' יהושע, \u0005ראה את כתלי ביתו ש\u0006הם \u0005שחורים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בתמיהה: \u0003מכותלי ביתך אתה ניכר שפחמי אתה,\u0004 שעד אז לא ידע שר' יהושע נזקק היה לעבודה קשה של נפחות כדי להתפרנס. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003אוי לו לדור שאתה פרנסו, שאי\u0004 (אין) \u0003אתה יודע בצערן של תלמידי חכמים, במה הם מתפרנסים ובמה הם נזונים.\u0004 הוסיף ר' יהושע להוכיחו על שיטתו בהיותו נשיא הסנהדרין.","\u0003אמר לו\u0004 רבן גמליאל: \u0003נעניתי לך\u0004 (פגעתי בכבודך) ומעתה \u0003מחול לי. לא אשגח ביה\u0004 \u0005[השגיח בו]\u0006 ר' יהושע, ולא מחל. הוסיף ובקשו: \u0003עשה בשביל כבוד אבא,\u0004 הוא רבן שמעון בן גמליאל שהיה מראשי ישראל בזמן החורבן. \u0003פייס\u0004 \u0005[התפייס].\u0006 ומאחר שאין ר' יהושע עוד מקפיד, טבעי הוא שיחזור רבן גמליאל למקומו.","\u0003אמרו: מאן ניזיל ולימא להו לרבנן\u0004 \u0005[מי ילך ויאמר להם לחכמים].\u0006 שלא רצו כנראה לקבל על עצמם שליחות זו שיש בה משום הצעה להשבת הסדרים הקודמים למקומם והורדת ר' אלעזר בן עזריה מנשיאותו. \u0003אמר להו ההוא כובס\u0004 \u0005[להם כובס אחד]:\u0006 \u0003אנא אזילנא\u0004 \u0005[אני אלך].\u0006 \u0003שלח להו\u0004 \u0005[להם]\u0006 \u0003ר' יהושע לבי מדרשא\u0004 \u0005[לבית המדרש]\u0006 על ידי הכובס את השליחות הבאה: \u0003מאן דלביש מדא\u0004 \u0005[מי שלובש מדים]\u0006 — \u0003ילבש מדא\u0004 \u0005[מדים],\u0006 כלומר, ישאר הנשיא הרגיל בנשיאותו, כדי שלא יקרה ש\u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003לא לביש מדא\u0004 \u0005[לובש מדים]\u0006 \u0003יימר ליה למאן דלביש מדא: שלח מדך ואנא אלבשיה?!\u0004 \u0005[יאמר לו למי שלובש מדים: פשוט\u0006 את \u0005מדיך ואני אלבשם].\u0006 החכמים כנראה חשבו ששליחות זו באה ביזמת רבן גמליאל ולא השגיחו בה, ועל כן \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' עקיבא לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003טרוקו גלי\u0004 \u0005[נעלו\u0006 את \u0005השערים]\u0006 כדי ש\u0003לא ליתו\u0004 \u0005[יבואו]\u0006 \u0003עבדי רבן גמליאל ולצערו לרבנן\u0004 \u0005[ויצערו את החכמים].\u0006","כשנודע הדבר \u0003אמר ר' יהושע: מוטב דאיקום ואיזיל אנא לגבייהו\u0004 \u0005[שאעמוד ואלך אני אליהם].\u0006 \u0003אתא טרף אבבא\u0004 \u0005[הלך והקיש על הדלת]\u0006 וחזר בשינוי צורה על הפתגם ששלח: \u0003אמר להו, מזה בן מזה — יזה.\u0004 כלומר, הכהן שתפקידו להזות מים טהורים ראוי שימשיך בתפקידו, \u0003ו\u0004אין זה ראוי שמי \u0003שאינו לא מזה ולא בן מזה יאמר למזה בן מזה! מימיך מי מערה\u0004 (מי מקוה ולא מים חיים) \u0003ואפרך אפר מקלה\u0004 (סתם אפר כירה, ולא מאפרה של הפרה האדומה). כיוון שכך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' עקיבא: ר' יהושע, נתפייסת? כלום עשינו\u0004 כל אותה הדחה \u0003אלא בשביל כבודך,\u0004 ואם אתה מוחל על כבודך אין איש מאתנו מתנגד ו\u0003למחר אני ואתה נשכים לפתחו\u0004 של רבן גמליאל לבקש שיקבל על עצמו את הנשיאות. ואולם נתעוררה השאלה מה לעשות בר' אלעזר בן עזריה.","\u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003היכי נעביד\u0004 \u0005[איך נעשה],\u0006 \u0003נעבריה\u0004 \u0005[נעביר אותו\u0006 מכהונתו\u0005]\u0006 — אין זה נאה, שהרי \u0003גמירי\u0004 \u0005[מקובלנו]\u0006 כהלכה ש\u0003מעלין בקדש ואין מורידין\u0004, ועל כן אדם שהיה נשיא הסנהדרין אין להורידו \u0005(גאונים)\u0006 מדרגה זו. ואם \u0003נדרוש מר חדא שבתא ומר חדא שבתא\u0004 \u0005[אם ידרוש חכם זה שבת אחת וחכם זה שבת אחת]\u0006 — \u0003אתי לקנאויי\u0004 \u0005[יבואו לקנא]\u0006 זה בזה, שבהכרח יצטרכו להגיע להחלטה מי הוא נשיא הסנהדרין בפועל, ועל כן יש להכריע בדבר מראש. \u0003אלא: לדרוש\u0004 \u0005[ידרוש]\u0006 \u0003רבן גמליאל תלתא שבתי\u0004 \u0005[שלוש שבתות]\u0006 \u0003ור' אלעזר בן עזריה\u0004 ידרוש כראש ישיבה \u0003חדא שבתא\u0004 \u0005[שבת אחת].\u0006 ואכן נקבע סידור זה, \u0003והיינו\u0004 \u0005[וזוהי\u0006 הסיבה\u0005]\u0006 שמצאנו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בלשון \u0003שבת של מי היתה\u0004 — \u0003של ר' אלעזר בן עזריה היתה,\u0004 שלא בכל שבת ישב הוא בראש. כדי להשלים את הסיפור מוסיפים ש\u0003אותו תלמיד\u0004 ששאל את השאלה מתחילה \u0003ר' שמעון בן יוחאי הוה\u0004 \u0005[היה].\u0006","\u0003ו\u0004עוד שנינו במשנה שתפילה \u0003של מוספין\u0004 זמנה \u0003כל היום. אמר ר' יוחנן: ו\u0004אף על פי כן \u0003נקרא \"פושע\"\u0004 אם הוא מאחר כל כך את זמן התפילה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: מי ש\u0003היו לפניו שתי תפלות\u0004 להתפלל, \u0003אחת של מנחה ואחת של מוסף\u0004 — מקדים ו\u0003מתפלל של מנחה ואחר כך מתפלל של מוסף,\u0004 לפי \u0003שזו,\u0004 תפילת מנחה \u0003תדירה, וזו,\u0004 תפילת מוסף \u0003אינה תדירה. ר' יהודה אומר: מתפלל\u0004 בתחילה \u0003של מוסף ואחר כך מתפלל של מנחה, ש\u0004כן \u0003זו,\u0004 תפילת המוסף היא \u0003מצוה עוברת,\u0004 שזמנה עובר קודם (עד שבע שעות, לדעתו), \u0003וזו,\u0004 תפילת מנחה היא \u0003מצוה שאינה עוברת,\u0004 שזמנה ארוך יותר. \u0003אמר ר' יוחנן: הלכה\u0004 היא ש\u0003מתפלל של מנחה ואחר כך מתפלל של מוסף,\u0004 כדעת חכמים.","בנושא זה מובאים מקורות נוספים אגב סיפור: \u0003ר' זירא כי הוה חליש מגירסיה הוה אזיל ויתיב אפתחא דבי\u0004 \u0005[כאשר היה נחלש מ\u0006רוב \u0005לימודו היה הולך ויושב על פתח בית]\u0006 המדרש של \u0003ר' נתן בר טובי. אמר\u0004 בלבו: \u0003כי חלפי רבנן אז איקום מקמייהו ואקבל אגרא\u0004 \u0005[כאשר יעברו חכמים\u0006 בכניסתם ויציאתם מבית ר' נתן \u0005אז אעמוד מפניהם ואקבל שכר\u0006 על המצווה לכבד תלמידי חכמים]. \u0003נפק אתא\u0004 \u0005[יצא ובא]\u0006 \u0003ר' נתן בר טובי\u0004 עצמו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003מאן\u0004 \u0005[מי]\u0006 \u0003אמר הלכה בי מדרשא\u0004 \u0005[בבית המדרש],\u0006 כעת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' נתן בר טובי: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן\u0004 בשעה זו בבית המדרש ש\u0003אין הלכה כר' יהודה\u0004 ש\u0003אמר\u0004 ש\u0003מתפלל\u0004 בתחילה \u0003של מוסף ואחר כך מתפלל של מנחה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא בשאלה: האם אמנם \u0003ר' יוחנן\u0004 עצמו \u0003אמרה\u0004 להלכה זו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' נתן: \u0003אין\u0004 \u0005[כן].\u0006 \u0003תנא מיניה ארבעין זמנין\u0004 \u0005[שנה ממנו ארבעים פעמים]\u0006 אימרה זו וקבעה בזכרונו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' נתן: \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003היא לך\u0004 שלא שמעת דבר הלכה אחר משמו של ר' יוחנן ועל כן היא כה חביבה בעינך, \u0003או חדת\u0004 \u0005[חדשה היא]\u0006 \u0003היא לך,\u0004 שנתחדש לך דבר מה בהלכה זו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003חדת\u0004 \u0005[חדשה]\u0006 \u0003היא לי\u0004 במשהו, \u0003משום דמספקא\u0004 \u0005[שמסופקת]\u0006 היתה \u0003לי\u0004 הלכה זו שעד כה ידעתי שנאמרה משמו של \u0003ר' יהושע בן לוי\u0004 ועתה מתברר לי כי בעל ההלכה הוא ר' יוחנן.","\u0003אמר ר' יהושע בן לוי: כל המתפלל תפלה של מוספין לאחר שבע שעות\u0004 ביום \u0003ל\u0004שיטת \u0003ר' יהודה, עליו הכתוב אומר: \"נוגי ממועד אספתי ממך היו\u0004 משאת עליה חרפה\u0003\"\u0004 (צפניה ג, יח). \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 איך אתה למד מלשון הפסוק \u0003דהאי\u0004 \u0005[שזה]\u0006 לשון \u0003\"נוגי\" לישנא דתברא\u0004 \u0005[לשון שבר]\u0006 \u0003הוא?\u0004 — \u0003כדמתרגם\u0004 \u0005[כפי שפירש]\u0006 \u0003רב יוסף: תברא אתי\u0004 \u0005[שבר בא]\u0006 \u0003על שנאיהון\u0004 \u0005[שונאיהם]\u0006 של \u0003בית ישראל (לשון נקיה עבור ישראל) על דאחרו\u0004 \u0005[שאחרו]\u0006 \u0003זמני מועדיא\u0004 \u0005[המועדים]\u0006 ש\u0003בירושלים.\u0004 ומכאן שהמאחר מצווה ואינו מקיימה בזמנה נאמר עליו פסוק זה של פורענות.","ומעין זה \u0003אמר ר' אלעזר: כל המתפלל תפלה של שחרית לאחר ארבע שעות\u0004 ביום \u0003ל\u0004שיטת \u0003ר' יהודה עליו הכתוב אומר: \"נוגי ממועד אספתי ממך היו\u0004 משאת עליה חרפה \u0003\". מאי משמע\u0004 \u0005[מה המשמעות],\u0006 איך אתה למד מלשון הפסוק \u0003דהאי\u0004 \u0005[שזה]\u0006 לשון \u0003\"נוגי\" לישנא דצערא\u0004 \u0005[לשון צער]\u0006 \u0003הוא?\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"דלפה נפשי מתוגה\"\u0004 (תהלים קיט, כח). \u0003רב נחמן בר יצחק אמר:\u0004 הראיה לכך שמשמעות לשון \"נוגי\" הוא צער \u0003מהכא\u0004 \u0005[מכאן],\u0006 מכתוב אחר, שנאמר: \u0003\"בתולותיה נוגות והיא מר לה\"\u0004 (איכה א, ד)."],["כיון שהוזכר ענין זמן תפילת מוסף ועד מתי מותר לאחרו, מסופר: \u0003רב אויא חלש\u0004 \u0005[חלה]\u0006 \u0003ולא אתא לפרקא\u0004 \u0005[בא לדרשת השבת]\u0006 של \u0003רב יוסף. למחר כי אתא, בעא\u0004 \u0005[כאשר בא\u0006 רב אוויא, \u0005רצה]\u0006 \u0003אביי לאנוחי דעתיה\u0004 \u0005[להניח דעתו]\u0006 של \u0003רב יוסף,\u0004 ולברר בדרך שאלות ותשובות שרב אוויא נמנע מלבוא לדרשה לא מתוך זלזול בכבוד רב יוסף. על כן שאלו: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אתא מר לפרקא\u0004 \u0005[בא אדוני לדרשה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אוויא: \u0003דהוה חליש לבאי\u0004 \u0005[שהיה לבי חלוש]\u0006 \u0003ולא מצינא\u0004 \u0005[יכולתי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אביי: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא טעמת מידי ואתית\u0004 \u0005[דבר ובאת]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אוויא: וכי \u0003לא סבר לה מר להא\u0004 \u0005[אין אדוני סובר,\u0006 מקבל, \u0005את\u0006 ההלכה \u0005הזו]\u0006 שאמר \u0003רב הונא?\u0004 ש\u0003אמר רב הונא: אסור לו לאדם שיטעום כלום קודם שיתפלל תפלת המוספין! אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003איבעי ליה למר לצלויי צלותא\u0004 \u0005[היה לו לאדוני להתפלל תפילת]\u0006 ה\u0003מוספין ביחיד, ולטעום מידי ולמיתי\u0004 \u0005[דבר ולבוא\u0006 לדרשה\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אוויא: \u0003ולא סבר לה מר להא\u0004 \u0005[ו\u0006כי \u0005אין אדוני סובר,\u0006 מקבל, \u0005את\u0006 ההלכה \u0005הזו]\u0006 ש\u0003אמר ר' יוחנן: אסור לו לאדם שיקדים תפלתו לתפלת הצבור? אמר ליה\u0004 \u0005[לו]\u0006 אביי: וכי \u0003לאו אתמר עלה\u0004 \u0005[לא נאמר עליה,\u0006 על הלכה זו] הגבלה זו ש\u0003אמר ר' אבא\u0004 ש\u0003בצבור שנו,\u0004 כלומר, שרק אדם הנמצא עם הציבור אסור לו להקדים להתפלל לפניהם. ואף על פי שלא צדק רב אוויא, מכל מקום הוסבר מתוך דבריו משום מה לא בא.","ומסכמים: \u0003ולית הלכתא\u0004 \u0005[ואין הלכה]\u0006 \u0003לא כרב הונא ולא כר' יהושע בן לוי\u0004 בענין איסור אכילה לפני תפילת מוסף ומנחה. ומפרטים: \u0003כר' הונא\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו,\u0006 בתפילת המוסף\u0005].\u0006 \u0003כר' יהושע בן לוי\u0004 — ש\u0003אמר ר' יהושע בן לוי: כיון שהגיע זמן תפלת מנחה, אסור לו לאדם שיטעום כלום קודם שיתפלל תפלת המנחה,\u0004 ואין הלכה כמותו בענין זה.","בנוסף להלכותיהן של התפילות הקבועות מסופר כי \u0003ר' נחוניא בן הקנה היה מתפלל בכניסתו לבית המדרש וביציאתו\u0004 ממנו \u0003תפלה קצרה. אמרו לו: מה מקום לתפלה זו?\u0004 שהרי אין בית המדרש מקום סכנה שיש להקדים תפילה לפני הכניסה אליו ואחר היציאה ממנו, \u0003אמר להם: בכניסתי אני מתפלל שלא יארע דבר תקלה על ידי\u0004 בהיותי בבית המדרש. \u0003וביציאתי אני נותן הודאה על חלקי\u0004 (גורלי).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא את הנוסח המלא של תפילת ר' נחוניא בן הקנה: \u0003בכניסתו מהו אומר?\u0004 — \u0003\"יהי רצון מלפניך ה' אלהי שלא יארע דבר תקלה\u0004 בפסק הלכה \u0003על ידי, ולא אכשל בדבר הלכה, וישמחו בי חברי\u0004 העוסקים יחד אתי בבירור ההלכה. ופירוט הדברים (מהרש\"א): \u0003ולא אומר על\u0004 דבר \u0003טמא\u0004 שהוא \u0003טהור, ולא על\u0004 דבר \u0003טהור\u0004 שהוא \u0003טמא. ולא יכשלו חברי בדבר הלכה, ואשמח בהם\".\u0004","\u0003ביציאתו מהו אומר?\u0004 — \u0003\"מודה אני לפניך ה' אלהי ששמת חלקי מיושבי בית המדרש ולא שמת חלקי מיושבי קרנות\u0004 (אנשים בטלים היושבים בפינת הרחוב). \u0003שאני משכים, והם משכימים. אני משכים לדברי תורה, והם משכימים לדברים בטלים. אני עמל והם עמלים. אני עמל ומקבל שכר, והם עמלים ואינם מקבלים שכר. אני רץ והם רצים. אני רץ לחיי העולם הבא והם רצים לבאר שחת\".\u0004","אגב דברי ר' נחוניא בהערכת חלקו בין יושבי בית המדרש מובאים עוד סיפורים הנוגעים לנושא זה מצדדים שונים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשחלה ר' אליעזר נכנסו תלמידיו לבקרו. אמרו לו: למדנו אורחות חיים\u0004 (אמור לנו כללים בהנהגת חיינו) כדי ש\u0003נזכה בהן לחיי העולם הבא.\u0004","\u0003אמר להם:\u0004 סיכם להם: \u0003הזהרו בכבוד חבריכם, ומנעו\u0004 את \u0003בניכם מן ההגיון\u0004 במקראות שיש בהם נטיה למינות (גאונים), \u0003והושיבום\u0004 לבניכם \u0003בין ברכי תלמידי חכמים\u0004 עוד בקטנותם, \u0003וכשאתם מתפללים — דעו לפני מי אתם עומדים. ובשביל כך תזכו לחיי העולם הבא. בדומה לזה מסופר על רבו של ר' אליעזר, ר' יוחנן בן זכאי. ש\u0004","\u0003כשחלה ר' יוחנן בן זכאי נכנסו תלמידיו לבקרו. כיון שראה אותם התחיל לבכות. אמרו לו תלמידיו\u0004: אתה שהנך \u0003\"נר ישראל, עמוד הימיני, פטיש החזק\"\u0004 האיש שכל המשך הקיום של העם היהודי נתמך על ידו, \u0003מפני מה אתה בוכה?\u0004 מה הוא המצער אותך בחיים שלמים כשלך?","\u0003אמר להם:\u0004 בוכה אני מפני מורא דין מעלה, שאין דיני בית דין זה דומה לדיני אדם. שכן \u0003אילו לפני מלך בשר ודם היו מוליכין אותי,\u0004 שחייו הם אך חיי שעה \u0003שהיום\u0004 הוא \u0003כאן ומחר\u0004 הוא מת וניתן \u0003בקבר, שאם כועס עלי אין כעסו כעס עולם\u0004, ולפיכך אין ביכולתו לענוש עונשי עולם, \u0003ואם אוסרני\u0004 בבית האסורים — \u0003אין איסורו איסור עולם,\u0004 שיש תקוה לאחריתי שאשתחרר מן המאסר, \u0003ואם ממיתני\u0004 — \u0003אין מיתתו מיתת עולם,\u0004 שיש חיים לאחר המיתה שהוא גוזר, \u0003ו\u0004יותר מכך — \u0003אני יכול לפייסו בדברים ו\u0004אף \u0003לשחדו בממון,\u0004 ו\u0003אף על פי כן הייתי בוכה\u0004 מהתרגשות אחר שעלי לעמוד לפני דין מלכותי, \u0003ועכשיו שמוליכים אותי לפני מלך מלכי המלכים הקדוש ברוך הוא, שהוא חי וקיים לעולם ולעולמי עולמים, שאם כועס עלי\u0004 — \u0003כעסו כעס עולם, ואם אוסרני\u0004 — \u0003איסורו איסור עולם, ואם ממיתני\u0004 — \u0003מיתתו מיתת עולם, ואיני יכול לפייסו בדברים ולא לשחדו בממון. ולא עוד, אלא שיש לפני שני דרכים, אחת של גן עדן ואחת של גיהנם, ואיני יודע באיזו\u0004 דרך \u0003מוליכים אותי, ו\u0004איך אם כן \u0003לא אבכה?!\u0004","\u0003אמרו לו\u0004 תלמידיו: \u0003רבינו, ברכנו. אמר להם: \"יהי רצון שתהא מורא שמים עליכם כמורא בשר ודם\".\u0004 תמהו ו\u0003אמרו לו תלמידיו: עד כאן\u0004 ולא יותר? \u0003אמר להם: ולואי,\u0004 כלומר, אכן אם יגיע אדם לידי יראת שמים כזו — דיו, וראייה לדבר: \u0003תדעו כשאדם עובר עבירה אומר\u0004 הוא בלבו: \u0003\"שלא יראני אדם\",\u0004 ואם יתבייש מהקדוש ברוך הוא כדרך שהוא מתבייש מבני אדם, לא יגיע לידי חטא.","ומסופר: \u0003בשעת פטירתו,\u0004 ממש לפני מיתתו הורה ו\u0003אמר להם\u0004 ר' אליעזר לתלמידיו שני דברים: \u0003פנו כלים\u0004 שבבית והוציאום חוצה לו \u0003מפני הטומאה,\u0004 כדי שלא יטמאו (טומאת אוהל) מגופו המת, \u0003ו\u0004כן \u0003הכינו כסא לחזקיהו מלך יהודה שבא\u0004 מעולם העליון ללוות אותו.","במשנה זו מובאת מחלוקת בדבר צד החיוב בתפילת שמונה עשרה. \u0003רבן גמליאל אומר: בכל יום ויום מתפלל אדם שמנה עשרה. ר' יהושע אומר:\u0004 די לו בתפילה קצרה, ואינו מתפלל אלא \u0003מעין שמונה עשרה. ר' עקיבא אומר\u0004 שיטת ביניים: \u0003אם שגורה תפלתו\u0004 ורגילה \u0003בפיו\u0004 — \u0003מתפלל שמונה עשרה, ואם לאו\u0004 \u0005[לא],\u0006 שאין שגורה תפילתו בפיו — אינו מתפלל אלא \u0003מעין שמונה עשרה.\u0004","\u0003ר' אליעזר אומר: העושה תפלתו קבע\u0004 — \u0003אין תפלתו תחנונים,\u0004 והיא פגומה משום כך. ובגמרא יבואר מהי המסקנה ההלכתית הנובעת מדברים אלה.","\u0003ר' יהושע אומר: ההולך במקום סכנה\u0004 ואינו יכול להתפלל בשל כך תפילה שלמה, הריהו \u0003מתפלל תפלה קצרה, ואומר: \"הושע ה' את עמך את שארית ישראל, בכל פרשת העבור\u0004 (ובגמרא מוצעים פירושים למילים אלה), \u0003יהיו צרכיהם לפניך. ברוך אתה ה' שומע תפלה\".\u0004 בשעת התפילה על המתפלל לפנות לכיוון בית המקדש.","ולפיכך אם \u0003היה רוכב על החמור,\u0004 אם יכול — \u0003ירד\u0004 מעליו \u0003ויתפלל\u0004 במנוחה, \u0003ואם אינו יכול\u0004 לרדת מעליו — \u0003יחזיר\u0004 (יפנה) \u0003את פניו\u0004 לעבר מקום המקדש. \u0003ואם אינו יכול להחזיר את פניו\u0004 — דיו בכך ש\u0003יכוין את לבו כנגד בית קדשי הקדשים.\u0004 וכן הדין אם \u0003היה מהלך בספינה או באסדא\u0004 (רפסודה) שאינו יכול לפנות לעבר ירושלים — \u0003יכוין את לבו כנגד בית קדשי הקדשים.\u0004","מאחר שמשנה זו עוסקת בעצם חיובה של תפילת שמונה עשרה, מבררים בגמרא בעיות יסוד השייכות לתפילה זו. \u0003הני\u0004 \u0005[אותן]\u0006 \u0003שמונה עשרה\u0004 ברכות \u0003כנגד מי\u0004 תקנון? כלומר, על מה בססו בשעה שתיקנו תפילה זו, מספר זה של ברכות?","\u0003אמר ר' הלל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמואל בר נחמני: כנגד שמונה עשרה אזכרות\u0004 (שמות ה') \u0003שאמר דוד\u0004 המלך \u0003ב\u0004מזמור \u0003\"הבו לה' בני אלים\"\u0004 (תהלים כט). \u0003רב יוסף אמר: כנגד שמונה עשרה אזכרות שבקריאת שמע. אמר ר' תנחום אמר ר' יהושע בן לוי:\u0004 הוא \u0003כנגד שמונה עשרה חוליות שבשדרה\u0004 למטה מן הצלעות. מאחר שר' יהושע בן לוי סמך בדרך זו את התפילה לשמונה עשרה החוליות בשדרה, מובא מאמר אחר שלו המקשר את שני אלה.","\u0003אמר ר' תנחום אמר ר' יהושע בן לוי: המתפלל צריך שיכרע\u0004 באותן ברכות שחובה לכרוע בהן \u0003עד שיתפקקו\u0004 (יתבלטו) \u0003כל\u0004 ה\u0003חוליות שבשדרה.\u0004","\u0003עולא\u0004 קבע סימן אחר למידת הכריעה ו\u0003אמר: עד כדי שיראה איסר\u0004 (מטבע קטנה) \u0003כנגד לבו,\u0004 כלומר, שיתכופף עד שיוכל לראות מטבע קטנה של איסר המונחת לפניו (רה\"ג). \u0003ר' חנינא אמר:\u0004 יש להקל ולומר כי \u0003כיון שנענע ראשו\u0004 — \u0003שוב אינו צריך\u0004 להתכופף עוד. ואולם \u0003אמר רבא: והוא\u0004 שדי בכך זהו רק כש\u0003מצער נפשיה\u0004 \u0005[עצמו],\u0006 מתאמץ, \u0003ומחזי כמאן דכרע\u0004 \u0005[ונראה כמי שכורע]\u0006 אבל לכתחילה יש להתכופף יותר.","\u0003ו\u0004עד כאן דובר על שמונה עשרה ברכות, ככינוייה המקובל של התפילה. ואולם תמוה הדבר: וכי \u0003הני תמני סרי\u0004 \u0005[אלה שמונה עשרה]\u0006 ברכות הן?! והלא \u0003תשסרי הוין\u0004 \u0005[תשע עשרה הן]!\u0006","\u0003אמר ר' לוי: ברכת המינים\u0004 (הברכה שכוללת הקללה למלשינים) \u0003ביבנה תקנוה\u0004 ואינה ממנין הברכות המקורי. ואולם מאחר וסמכו את מנין הברכות על רמזים מתחומים שונים, על כן יש לברר ברכה זו, התשע עשרה במספר, \u0003כנגד מי תקנוה.\u0004","\u0003אמר ר' לוי ל\u0004דעת \u0003ר' הלל בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמואל בר נחמני\u0004 הסובר שהברכות הם כנגד שמונה עשרה אזכרות שבמזמור \"הבו לה' בני אלים\", ברכה זו מבוססת \u0003כנגד\u0004 (על) אזכרת ה' שאיננה שם הויה אלא כינוי אחר: \u0003\"אל הכבוד הרעים\"\u0004 (תהלים כט, ג). ו\u0003ל\u0004דעת \u0003רב יוסף\u0004 שסובר שהם כנגד האזכרות שבקריאת שמע, הברכה הנוספת היא \u0003כנגד\u0004 המלה \u0003\"אחד\" שבקריאת שמע\u0004, שאף שאיננה שם הויה, מכל מקום היא מבטאת את תמצית האמונה. ו\u0003ל\u0004דעת \u0003ר' תנחום\u0004 ש\u0003אמר\u0004 בשם \u0003ר' יהושע בן לוי\u0004 שהברכות הם כנגד החוליות שבשדרה, הברכה הנוספת היא \u0003כנגד חוליא קטנה שב\u0004בסוף ה\u0003שדרה. ואגב הזכרת ברכת המינים מסופר כיצד הותקנה ברכה זו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמעון הפקולי הסדיר\u0004 את \u0003שמונה עשרה\u0004 ה\u0003ברכות\u0004 שהיו עוד בזמן הכנסת הגדולה וקבען \u0003לפני רבן גמליאל\u0004 נשיא הסנהדרין של יבנה \u0003על הסדר ביבנה.\u0004 ואולם היה צורך גם לפי מצב הזמנים בהתקנת ברכה חדשה כנגד המינים ועל כן \u0003אמר להם רבן גמליאל לחכמים: כלום יש אדם שיודע לתקן ברכת הצדוקין? עמד שמואל הקטן\u0004 שהיה מגדולי חסידי הדור \u0003ותקנה.\u0004","וספרו ש\u0003בשנה אחרת\u0004 כשעבר שמואל הקטן לפני התיבה \u0003שכחה,\u0004 את הברכה הזו,"],["ועמד \u0003והשקיף\u0004 (התבונן וניסה להזכר) \u0003בה\u0004 במשך \u0003שתים ושלש שעות, ולא העלוהו\u0004 (הפסיקו אותו מלעמוד לפני התיבה).","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא העלוהו? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב:\u0004 שליח ציבור ש\u0003טעה בכל\u0004 אחת מן \u0003הברכות כלן\u0004 — \u0003אין מעלין\u0004 (מפסיקים) \u0003אותו,\u0004 ואולם אם טעה \u0003בברכת הצדוקים\u0004 — \u0003מעלין אותו.\u0004 והטעם: \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא מין הוא\u0004 ואינו רוצה לקלל את עצמו. ואם כן, מדוע לא הפסיקו את שמואל הקטן?","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003שמואל הקטן דאיהו\u0004 \u0005[שהוא]\u0006 \u0003תקנה\u0004 לברכה זו, ואין לחוש לו.","ושואלים עוד: \u0003וניחוש דלמא הדר ביה\u0004 \u0005[ונחשוש שמא חזר בו]\u0006 ואף שהיה צדיק חזר בו והרשיע. על כך \u0003אמר אביי: גמירי, טבא לא הוי בישא\u0004 \u0005[למודים\u0006 אנו, מן המסורת, כי \u0005טוב אינו נעשה רע].\u0006","על כך מקשים: \u0003ולא\u0004 (והאם אין זה כך)?! \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 במפורש: \u0003\"ובשוב צדיק מצדקתו ועשה עול\u0004 ככל התועבות אשר עשה הרשע יעשה וחי, כל צדקותיו אשר עשה לא תזכרנה במעלו אשר מעל ובחטאתו אשר חטא בם ימות\u0003\"\u0004 (יחזקאל יח, כד). על כך משיב אביי: הכתוב \u0003ההוא\u0004 מדבר בצדיק שהיה \u0003רשע מעיקרו\u0004 (מתחילתו) ועשה תשובה ואחר כך שב והרשיע, \u0003אבל צדיק מעיקרו\u0004 — \u0003לא\u0004 יעשה רשע.","ושוב תמהים: \u0003ולא?!\u0004 והאין זה קורה? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אל תאמין בעצמך עד יום מותך, שהרי יוחנן כהן גדול שמש בכהונה גדולה שמנים שנה ולבסוף נעשה צדוקי.\u0004 ואם כן אף אדם גדול בצדקתו עשוי שיהפוך ויהא מין!","על כך \u0003אמר אביי: הוא ינאי, הוא יוחנן.\u0004 כלומר, כל שושלת החשמונאים זהה היתה, מתחילתה, ביחסה החיובי אל הצדוקים, ולא היה הבדל כלל בין יוחנן הורקנוס לבין אלכסנדר ינאי. ואולם \u0003רבא אמר: ינאי לחוד ויוחנן לחוד, ינאי\u0004 — \u0003רשע מעיקרו, ויוחנן\u0004 — \u0003צדיק מעיקרו.\u0004 ואם כן, \u0003הניחא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 \u0003ל\u0004שיטת \u0003אביי, אלא ל\u0004שיטת \u0003רבא קשיא\u0004 \u0005[קשה]\u0006 כיצד להסביר שהצדיק שב והרשיע.","על כך משיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך רבא: צדיק מעיקרו נמי דלמא הדר ביה\u0004 \u0005[גם כן,\u0006 יש לחשוש, \u0005שמא חזר בו]\u0006 כדרך שאירע ליוחנן כהן גדול. ואם כן שבה עתה הקושיה הראשונה: \u0003אי הכי, אמאי\u0004 \u0005[אם כך מדוע]\u0006 \u0003לא אסקוהו\u0004 \u0005[העלוהו,\u0006 הפסיקוהו\u0005]\u0006 את שמואל הקטן?","על כך הוא עונה: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003שמואל הקטן דאתחיל\u0004 \u0005[שהתחיל]\u0006 \u0003בה\u0004 ושכח באמצע את סיומה, ועל כן אין לחשוש שמא גם הוא בין המינים. וכן אמנם \u0003אמר רב יהודה אמר רב, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יהושע בן לוי: לא שנו,\u0004 שהטועה בברכת המינים מפסיקים אותו \u0003אלא\u0004 באופן \u0003ש\u0004עדיין \u0003לא התחיל בה, אבל\u0004 אם כבר \u0003התחיל בה\u0004 — מניחים לו להזכר ול\u0003גומרה.\u0004","עד כאן נאמרו רמזים לשמונה עשרה הברכות של תפילת החול כנגד מה נאמרו. ומעתה שואלים: \u0003הני\u0004 \u0005[אלה]\u0006 \u0003שבע\u0004 הברכות \u0003דשבתא\u0004 \u0005[ש\u0006בתפילה \u0005של שבת]\u0006 \u0003כנגד מי\u0004 תקנון? ומשיבים: \u0003אמר ר' חלפתא בן שאול: כנגד שבעה \"קולות\" שאמר דוד על המים,\u0004 כלומר, כנגד שבע פעמים שנזכר \"קול ה'\" במזמור כט בתהלים שממנו למדו גם תפילת חול.","ומוסיפים לשאול: \u0003הני\u0004 \u0005[אלה]\u0006 \u0003תשע\u0004 הברכות של מוסף \u0003ראש השנה כנגד מי\u0004 תקנון? \u0003אמר ר' יצחק דמן קרטיגנין:\u0004 הוא \u0003כנגד תשעה אזכרות\u0004 של שם ה' \u0003שאמרה חנה בתפלתה\u0004 (שמואל א ב, א–י), והקשר בין תפילת חנה לבין תפילת ראש השנה מובן על פי מה ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בראש השנה נפקדה\u0004 (בבן) \u0003שרה רחל וחנה.\u0004","ומוסיפים לשאול: \u0003הני\u0004 \u0005[אלה]\u0006 \u0003עשרים וארבע\u0004 ברכות \u0003דתעניתא\u0004 \u0005[\u0006הנאמרות \u0005ב\u0006תפילת שמונה עשרה \u0005ש\u0006ביום \u0005התענית]\u0006 \u0003כנגד מי\u0004 תקנון? \u0003אמר ר' חלבו: כנגד עשרים וארבע \"רננות\" שאמר שלמה בשעה שהכניס\u0004 את ה\u0003ארון לבית קדשי הקדשים\u0004 בחנוכת הבית, שמוזכרות שם (מלכים א פרק ח') עשרים וארבע פעמים לשונות רנה תפילה ותחינה. על כך שואלים: \u0003אי הכי,\u0004 ב\u0003כל יומא נמי נמרינהו\u0004 \u0005[אם כך, גם כן נאמרם]\u0006 עשרים וארבע ברכות! ועונים: \u0003אימת אמרינהו\u0004 \u0005[אימתי אמרן]\u0006 \u0003שלמה\u0004 — \u0003ביומא דרחמי\u0004 \u0005[ביום של\u0006 בקשת \u0005רחמים],\u0006 \u0003אנן נמי ביומא דרחמי אמרי להו\u0004 \u0005[אנחנו גם כן ביום של בקשת רחמים אומרים אותן].\u0006","שנינו במשנה ש\u0003ר' יהושע אומר\u0004 שבכל יום ויום מתפלל אדם \u0003מעין שמנה עשרה.\u0004 ונחלקו הדעות \u0003מאי\u0004 \u0005[מה]\u0006 משמעות הביטוי \u0003\"מעין שמונה עשרה\"? רב אמר: מעין כל ברכה וברכה,\u0004 שאפשר לומר את כל הברכות בקיצור ובכל נוסח. \u0003ושמואל אמר:\u0004 הכוונה לברכה מיוחדת הנאמרת במקום שלוש עשרה הברכות האמצעיות בשמונה עשרה, ושיש בה מילים אחדות כנגד כל ברכה. ונוסחה: \u0003\"הביננו ה' אלהינו לדעת דרכיך, ומול את לבבנו ליראתך, ותסלח לנו להיות גאולים, ורחקנו ממכאובינו, ודשננו בנאות ארצך, ונפוצותינו מארבע תקבץ, והתועים על דעתך ישפטו, ועל הרשעים תניף ידיך, וישמחו צדיקים בבנין עירך ובתקון היכלך, ובצמיחת קרן לדוד עבדך ובעריכת נר לבן ישי משיחך, טרם נקרא אתה תענה. ברוך אתה ה' שומע תפלה\". אף על פי שהזכירו חכמים את התפילה הקצרה הזו (\"הביננו\")\u0004","\u0003לייט עלה אביי אמאן דמצלי\u0004 \u0005[היה אביי מקלל את מי שמתפלל]\u0006 \u0003\"הביננו\",\u0004 כי לדעתו מותר להתפלל \"הביננו\" רק בשעת הדחק (ר\"ח, המאירי).","את ההיתר להתפלל תפילה קצרה זו עדיין מגבילים והולכים. \u0003אמר רב נחמן אמר שמואל: כל השנה כולה מתפלל אדם \"הביננו\", חוץ ממוצאי שבת וממוצאי ימים טובים, מפני שצריך לומר הבדלה ב\u0004תוך ברכת \u0003\"חונן הדעת\".\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבה בר שמואל: ונימרה\u0004 \u0005[ונאמר אותה]\u0006 \u0003ברכה רביעית בפני עצמה!\u0004 שאחרי שלוש ברכות הפתיחה יאמרו ברכה רביעית לעצמה להבדלה ואחר כך \"הביננו\". וראייה שיש אפשרות כזו — \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 ש\u0003ר' עקיבא אומר: אומרה\u0004 (את ההבדלה בתפילה) \u0003ברכה רביעית בפני עצמה. ר' אליעזר אומר:\u0004 ההבדלה נאמרת \u0003בהודאה\u0004 (בברכה המתחילה \"מודים\").","ומשיבים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל השנה כולה מי עבדינן\u0004 \u0005[האם עושים אנו]\u0006 בענין זה \u0003כ\u0004שיטת \u0003ר' עקיבא, דהשתא נמי נעביד\u0004 \u0005[שעכשיו גם כן נעשה]\u0006 כן?! הלא \u0003כל השנה כולה מאי טעמא לא עבדינן\u0004 \u0005[מה טעם איננו עושים]\u0006 \u0003כר' עקיבא\u0004 — \u0003כי תמני סרי תקון\u0004 \u0005[שמונה עשרה\u0006 ברכות \u0005תקנו],\u0006 \u0003תשסרי\u0004 \u0005[תשע עשרה]\u0006 \u0003לא תקון\u0004 \u0005[תקנו],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003שבע\u0004 ברכות \u0003תקון\u0004 \u0005[תקנו]\u0006 \u0003תמני\u0004 \u0005[שמונה]\u0006 \u0003לא תקון\u0004 \u0005[תקנו],\u0006 ואין אם כן להוסיף ברכה רביעית להבדלה לעצמה.","על עיקר הדברים \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הלכה זו \u0003מר זוטרא: ונכללה מכלל\u0004 \u0005[ונכלול אותה,\u0006 את הברכה הרביעית\u0005]\u0006 בתוך תפילת \"הביננו\" בנוסח זה: \u0003\"הביננו ה' אלהינו המבדיל בין קדש לחול\"!\u0004 על קושיה זו לא ניתנה תשובה והדבר נשאר \u0003קשיא\u0004 \u0005[קשה].\u0006","הוסיף ו\u0003אמר רב ביבי בר אביי\u0004 הגבלה נוספת בענין תפילת \"הביננו\": \u0003כל השנה כולה מתפלל אדם \"הביננו\", חוץ מימות הגשמים, מפני שצריך לומר שאלה\u0004 (בקשה על הגשם) \u0003בברכת \"השנים\".\u0004 על כך \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הלכה זו \u0003מר זוטרא: ונכללה מכלל\u0004 \u0005[ונכלול אותה,\u0006 את הברכה השביעית\u0005]\u0006 בתוך תפילת \"הביננו\" בנוסח זה: \u0003\"ודשננו בנאות ארצך, ותן טל ומטר\"!\u0004","על כך משיבים: אין זה אפשרי משום \u0003דאתי לאטרודי\u0004 \u0005[יבוא להתבלבל]\u0006 כשיוסיף בברכת \"הביננו\" דבר שהוא שינוי מנוסח הברכה הרגיל. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 משום מה לא נאמר תירוץ זה גם לבעיה הקודמת בענין \u0003הבדלה\u0004 ששנינו שאינו כוללה בנוסח \"הביננו\" ואומרה \u0003ב\"חונן הדעת\",\u0004 והלא יכול לתרץ ולהסביר כי אינו כוללה מאותה סיבה שיש לחשוש כי \u0003נמי אתי לאטרודי\u0004 \u0005[גם כן יבוא להתבלבל]!\u0006","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך כי יש הבדל בין המקרים: \u0003התם\u0004 \u0005[שם]\u0006 בענין הבדלה ב\"חונן הדעת\" \u0003כיון דאתיא\u0004 \u0005[שבאה]\u0006 ההוספה \u0003בתחלת צלותא\u0004 \u0005[התפילה,\u0006 הברכה\u0005]\u0006 — \u0003לא מטריד\u0004 \u0005[אינו מתבלבל],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 בענין שאלת גשמים \u0003כיון דאתיא\u0004 \u0005[ש\u0006היא \u0005באה]\u0006 \u0003באמצע צלותא\u0004 \u0005[התפילה]\u0006 — \u0003מטריד\u0004 \u0005[מתבלבל].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הלכה זו \u0003רב אשי:\u0004 אם כן \u0003ונימרה\u0004 \u0005[ונאמר אותה]\u0006 את שאלת המטר \u0003ב\u0004ברכת \u0003\"שומע תפלה\",\u0004 ש\u0003אמר ר' תנחום אמר רב אסי:\u0004 אם \u0003טעה\u0004 המתפלל \u0003ולא הזכיר גבורות גשמים ב\u0004ברכת \u0003\"תחיית המתים\"\u0004 — \u0003מחזירין אותו\u0004 לתחילת התפילה. אך אם לא הזכיר \u0003שאלה\u0004 של גשמים \u0003בברכת השנים\u0004 — \u0003אין מחזירין אותו, מפני שיכול לאומרה ב\"שומע תפלה\"\u0004 עם שאר בקשות. \u0003ו\u0004כן השוכח לומר \u0003הבדלה ב\u0004ברכת \u0003\"חונן הדעת\"\u0004 — \u0003אין מחזירין אותו, מפני שיכול לאומרה על הכוס.\u0004 ומכאן שאפשר לשאול גשמים ב\"שומע תפילה\" ולפיכך במקביל אפשר לומר זאת בסוף \"הביננו\" בלא להתבלבל. על כך משיבים: \u0003טעה שאני\u0004 \u0005[שונה]\u0006 ואין למדים מדינו של טועה לעשות כן לכתחילה.","קודם נמסרו דברי ר' תנחום בשם ר' אסי אגב הדיון. מעתה באים אנו לדון ל\u0003גופא\u0004 \u0005[גוף]\u0006 הענין, \u0003אמר ר' תנחום אמר רב אסי: טעה ולא הזכיר גבורות גשמים ב\u0004ברכת \u0003\"תחיית המתים\"\u0004 — \u0003מחזירין אותו.\u0004 טעה ולא הזכיר \u0003שאלה\u0004 של גשמים \u0003בברכת \"השנים\"\u0004 — \u0003אין מחזירין אותו, מפני שיכול לאומרה ב\u0004ברכת \u0003\"שומע תפלה\". ו\u0004אם טעה ולא הזכיר \u0003הבדלה ב\"חונן הדעת\"\u0004 — \u0003אין מחזירין אותו, מפני שיכול לאומרה על הכוס.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך] ממה ששנינו בתוספתא: \u0003טעה ולא הזכיר גבורות גשמים ב\u0004ברכת \u0003\"תחיית המתים\"\u0004 — \u0003מחזירין אותו.\u0004 טעה ולא הזכיר \u0003שאלה\u0004 של גשמים \u0003בברכת \"השנים\"\u0004 — \u0003מחזירין אותו, ו\u0004אם טעה ולא הזכיר \u0003הבדלה ב\"חונן הדעת\"\u0004 — \u0003אין מחזירין אותו, מפני שיכול לאומרה על הכוס.\u0004 ואם כן ההלכות השנויות, זו שבתוספתא וזו של רב תנחום, בענין טעה ולא הזכיר שאלה בברכת השנים סותרות זו את זו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמחזירים אותו הרי זה מדובר במתפלל \u0003ביחיד, הא\u0004 \u0005[זה]\u0006 ששנינו שאין מחזירים אותו הרי זה במתפלל \u0003בצבור.\u0004","על כך מקשים: \u0003בצבור מאי טעמא\u0004 \u0005[מה טעם]\u0006 הוא \u0003לא\u0004 צריך לחזור —— \u0003משום\u0004 שכבר \u0003שמעה משליח צבור\u0004 בחזרת התפילה, והוא מוציאו ידי חובה, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שזהו טעמו של דבר, סגנון הדברים אינו מדוייק, שכן \u0003האי\u0004 \u0005[\u0006לשון \u0005זו]\u0006 \u0003\"מפני שיכול לאומרה בשומע תפילה\"\u0004 אינה מדוייקת, ו\u0003\"מפני ששומע משליח ציבור\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 והרי זו הוכחה שהטעם שונה מזה שאמרנו.","\u0003אלא אידי ואידי\u0004 \u0005[זה וזה,\u0006 דברי ר' תנחום והתוספתא\u0005],\u0006 \u0003ביחיד, ולא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאין מחזירים אותו, הרי זה באופן \u0003דאדכר\u0004 \u0005[שנזכר]\u0006 בטעותו \u0003קודם\u0004 ברכת \u0003\"שומע תפלה\",\u0004 ויכול עדיין לשאול על הגשמים בברכת \"שומע תפילה\"."],["\u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמחזירים אותו, הרי זה באופן \u0003דאדכר\u0004 \u0005[שנזכר]\u0006 בטעותו \u0003בתר\u0004 \u0005[לאחר]\u0006 \u0003\"שומע תפלה\",\u0004 ושוב אינו יכול לשאול על הגשמים ולכן צריך לחזור לראש התפילה.","מתוך הקשר הדברים ובגלל שם החכם המוסר אותם, מזכירים עוד מה ש\u0003אמר ר' תנחום אמר רב אסי אמר ר' יהושע בן לוי: טעה ולא הזכיר\u0004 בתפילת ראש חודש את ההוספה המיוחדת \u0003של ראש חדש\u0004 (\"יעלה ויבוא\") \u0003ב\u0004ברכת ה\u0003\"עבודה\"\u0004 שבתפילת שמונה עשרה — \u0003חוזר ל\"עבודה\".\u0004 וכן אם \u0003נזכר ב\u0004ברכת \u0003\"הודאה\"\u0004 שהיא הברכה שלאחריה — \u0003חוזר ל\"עבודה\".\u0004 נזכר \u0003ב\u0004ברכת \u0003\"שים שלום\"\u0004 — \u0003חוזר ל\"עבודה\". ואם\u0004 נזכר רק לאחר ש\u0003סיים\u0004 את תפילת שמונה עשרה כולה — \u0003חוזר לראש\u0004 התפילה.","\u0003אמר רב פפא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אחא בר אדא: הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 שאם כבר \u0003סיים\u0004 תפילתו — \u0003חוזר לראש, לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 במקרה \u0003ש\u0004כבר \u0003עקר רגליו\u0004 מן המקום שבו עמד בתפילתו, \u0003אבל\u0004 אם עדיין \u0003לא עקר רגליו\u0004 — \u0003חוזר ל\u0004ברכת ה\u0003עבודה,\u0004 ואומר בתוכה \"יעלה ויבוא\".","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 בני הישיבה: \u0003מנא לך הא\u0004 \u0005[מנין לך\u0006 הלכה \u0005זו?]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאבא מרי שמיע לי\u0004 \u0005[מאבי מורי,\u0006 רב אחא בר אדא \u0005שמעתי]\u0006 זאת, \u0003ואבא מרי\u0004 \u0005[ואבי מורי]\u0006 שמע זאת \u0003מרב.\u0004","מעין זה \u0003אמר רב נחמן בר יצחק: הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 שאם כבר \u0003עקר רגליו חוזר לראש\u0004 התפילה \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 באופן \u0003שאינו רגיל לומר תחנונים\u0004 נוספים \u0003אחר תפלתו, אבל\u0004 אם \u0003רגיל לומר תחנונים אחר תפלתו\u0004 ובתוך כך נזכר שהחסיר מתפילתו — \u0003חוזר ל\u0004ברכת ה\u0003עבודה\u0004 ומשלים את החסר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך \u0003אמר רב נחמן בר יצחק: הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 \u0003כי\u0004 \u0005[\u0006ש\u0005כאשר]\u0006 עדיין \u0003לא עקר רגליו חוזר ל\u0004ברכת ה\u0003עבודה לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 באופן \u0003שרגיל לומר תחנונים\u0004 נוספים \u0003אחר תפלתו, אבל אם אינו רגיל לומר תחנונים אחר תפלתו\u0004 — הרי זה נחשב כאילו כבר סיים תפילתו ו\u0003חוזר לראש\u0004 התפילה.","שנינו במשנה ש\u0003ר' אליעזר אומר\u0004 ש\u0003כל העושה תפלתו קבע\u0004 אין תפילתו תחנונים. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 המלה \u0003\"קבע\"\u0004 בהקשר זה? \u0003אמר ר' יעקב בר אידי אמר רבי אושעיא:\u0004 הרי זה \u0003כל שתפלתו דומה עליו כמשוי\u0004 \u0005[כמשא]\u0006 שהוא ממהר להפטר ממנו. \u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים]\u0006 שהכוונה היא ל\u0003כל מי שאינו אומרה\u0004 לתפילה \u0003בלשון תחנונים,\u0004 אלא כדרך אמירת קבע ללא הבעת רגש. \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 העושה תפילתו קבע הוא \u0003כל\u0004 מי \u0003שאינו יכול לחדש בה\u0004 בתפילתו, \u0003דבר\u0004 מצרכיו שלו, ואומר רק את הנוסח הקבוע.","על כך \u0003אמר ר' זירא: אנא יכילנא לחדושי\u0004 \u0005[אני יכול לחדש]\u0006 \u0003בה מילתא\u0004 \u0005[דבר]\u0006 בכל תפילה, \u0003ומסתפינא דלמא מטרידנא\u0004 \u0005[ו\u0006אולם \u0005אני חושש שמא אתבלבל],\u0006 ולפי זה אין לחייב אם כן את הרבים לחדש בתפילה.","האחים \u0003אביי בר אבין ור' חנינא בר אבין דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 העושה תפילתו קבע הוא \u0003כל\u0004 מי \u0003שאין מתפלל עם דמדומי חמה,\u0004 שהיא שעת רצון לתפילה והוא אינו טורח למצוא שעה כזו. ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מצוה להתפלל עם דמדומי חמה. ואמר ר' זירא: מאי קראה\u0004 \u0005[מהו הפסוק]\u0006 בו נרמז הדבר — מה שנאמר: \u0003\"ייראוך עם שמש ולפני ירח דור דורים\"\u0004 (תהלים עב, ה), כלומר, ביטוי יראת ה', התפילה, צריכה להיות עם שמש, קרוב לזריחתה או לשקיעתה של השמש. אף על פי כן \u0003לייטי עלה במערבא אמאן דמצלי\u0004 \u0005[מקללים היו בארץ ישראל את מי שמתפלל]\u0006 \u0003עם דמדומי חמה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003דלמא מיטרפא ליה שעתא\u0004 \u0005[שמא תיטרף לו השעה]\u0006 ולא יספיק להתפלל בזמן.","שנינו במשנה ש\u0003ר' יהושע אומר\u0004 ש\u0003המהלך במקום סכנה מתפלל תפלה קצרה,\u0004 שהיא: \u0003\"בכל פרשת העבור\u0004 יהיו צרכיהם לפניך \u0003\",\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פרשת העבור\"? אמר רב חסדא אמר מר עוקבא:\u0004 יש לפרש זאת בדרך המדגישה את המלה \"עיבור\" בשתי משמעויות: \u0003אפילו בשעה שאתה מתמלא עליהם עברה\u0004 (כעס) \u0003כאשה עוברה\u0004 (הרה) — \u0003יהיו כל צרכיהם לפניך. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רב חסדא אמר מר עוקבא\u0004 בגירסה אחרת: \u0003אפילו בשעה שהם עוברים על דברי תורה\u0004 (ומשמעות \"עיבור\" — עבירה) \u0003יהיו כל צרכיהם לפניך.\u0004 במשנה הובאה רק נוסחה אחת של תפילה לשעת הסכנה, ואולם בתוספתא מובאות נוסחאות אחרות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המהלך במקום גדודי חיה ולסטים\u0004 (שודדים) \u0003מתפלל תפלה קצרה, ואיזה היא תפלה קצרה\u0004 — \u0003ר' אליעזר אומר:\u0004 מתפלל \u0003\"עשה רצונך בשמים ממעל, ותן נחת רוח ליראיך מתחת, והטוב בעיניך עשה, ברוך אתה ה' שומע תפלה\".\u0004","\u0003ר' יהושע אומר:\u0004 מתפלל \u0003\"שמע שועת עמך ישראל, ועשה מהרה בקשתם, ברוך אתה ה' שומע תפלה\".\u0004","\u0003ר' אלעזר בר' צדוק אומר:\u0004 מתפלל \u0003\"שמע צעקת עמך ישראל, ועשה מהרה בקשתם, ברוך אתה ה' שומע תפלה\".\u0004","\u0003אחרים אומרים:\u0004 מתפלל \u0003\"צרכי עמך ישראל מרובין ודעתם קצרה\u0004 ולכן אינם יכולים לפרש תפילתם כראוי (מהרש\"א). על כן \u0003יהי רצון מלפניך ה' אלהינו שתתן לכל אחד ואחד כדי פרנסתו, ולכל גויה\u0004 (גוף) \u0003וגויה די מחסורה, ברוך אתה ה' שומע תפלה\".\u0004","\u0003אמר רב הונא: הלכה כ\u0004שיטת \u0003אחרים\u0004 בנוסח התפלה במקום סכנה.","בקשר לתפילות הנאמרות בדרכים ובשעת סכנה מובאים גם דברים ביחס לתפילת הדרך. תחילת הדבר בדברים \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אליהו\u0004 כשנגלה לו \u0003לרב יהודה אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב סלא חסידא\u0004 \u0005[החסיד]:\u0006 \u0003לא תרתח\u0004 \u0005[אל תכעס]\u0006 \u0003ולא תחטי\u0004 \u0005[תחטא].\u0006 \u0003לא תרוי\u0004 \u0005[אל תשתכר]\u0006 \u0003ולא תחטי\u0004 \u0005[תחטא].\u0006 \u0003וכשאתה יוצא לדרך, המלך בקונך\u0004 (שאל עצה, בקש רשות, מה'), \u0003וצא. מאי\u0004 \u0005[מה]\u0006 \u0003המלך בקונך וצא? אמר ר' יעקב אמר רב חסדא: זו\u0004 היא \u0003תפלת הדרך. ו\u0004עוד \u0003אמר ר' יעקב אמר רב חסדא:\u0004 אין זו עצה טובה בלבד אלא הלכה פסוקה היא ש\u0003כל היוצא לדרך צריך להתפלל תפלת הדרך\u0004 לפני היציאה לדרך.","ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003תפלת הדרך?\u0004 מה נוסחה של תפלה זו? ומשיבים: \u0003\"יהי רצון מלפניך ה' אלהי, שתוליכני לשלום, ותצעידני לשלום, ותסמכני לשלום, ותצילני מכף כל אויב ואורב בדרך, ותשלח ברכה במעשי ידי, ותתנני לחן לחסד ולרחמים בעיניך ובעיני כל רואי, ברוך אתה ה' שומע תפלה\".\u0004","\u0003אמר אביי: לעולם\u0004"],["\u0003לישתף אינש נפשיה בהדי צבורא\u0004 \u0005[ישתף אדם עצמו עם הציבור]\u0006 וראוי שלא יתפלל על עצמו בלבד. \u0003היכי נימר\u0004 \u0005[כיצד יאמר]?\u0006 — \u0003\"יהי רצון מלפניך ה' אלהינו שתוליכנו לשלום\" וכו'\u0004 בלשון רבים. ומעתה באים לברר פרטים בדיני תפילה זו.","\u0003אימת מצלי\u0004 \u0005[מתי מתפלל]?\u0006 \u0003אמר ר' יעקב אמר רב חסדא: משעה שמהלך בדרך\u0004 ולא קודם. ו\u0003עד כמה?\u0004 כלומר, על איזו דרך ראוי לו להתפלל? (בה\"ג). \u0003אמר ר' יעקב אמר רב חסדא: עד פרסה. והיכי מצלי לה\u0004 \u0005[כיצד מתפלל אותה]?\u0006 \u0003רב חסדא אמר:\u0004 דווקא כשהוא \u0003מעומד. ואילו רב ששת אמר: אפילו\u0004 כשהוא \u0003מהלך\u0004 או יושב.","ומסופר: \u0003רב חסדא ורב ששת הוו קאזלי באורחא\u0004 \u0005[היו הולכים בדרך],\u0006 \u0003קם\u0004 \u0005[עמד]\u0006 \u0003רב חסדא וקא מצלי\u0004 \u0005[והתפלל]\u0006 תפילת הדרך. מאחר שהיה רב ששת עוור ולא ראה את חבירו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003מאי קא עביד\u0004 \u0005[מה עושה]\u0006 \u0003רב חסדא\u0004 כעת? אמר לו: \u0003קאי ומצלי\u0004 \u0005[עומד ומתפלל].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת לשמשו: \u0003אוקמן נמי לדידי ואצלי\u0004 \u0005[העמד גם כן אותי ואתפלל],\u0006 כי אף שלדעתו אין צורך לעמוד בשעת תפילה זו, בכל אופן \u0003\"מהיות טוב אל תקרא רע\",\u0004 כלומר, אם יכול אדם להיות טוב, בלי להפסיד בשל כך דבר (שהרי רב חסדא עומד בין כה וכה) מדוע להיות רע ולא לעמוד.","דובר על התפילה הקצרה הנאמרת בעת הסכנה וכן על התפילה הקצרה \"הביננו\". ושואלים: \u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל הלכה למעשה \u0005יש]\u0006 \u0003בין \"הביננו\" לתפלה קצרה?\u0004 ומשיבים: מי שמתפלל \u0003\"הביננו\" בעי לצלויי תלת קמייתא ותלת בתרייתא\u0004 \u0005[צריך להתפלל\u0006 לפניה \u0005שלוש\u0006 ברכות \u0005ראשונות\u0006 ואחריה \u0005שלוש אחרונות],\u0006 \u0003וכי מטי לביתיה לא בעי למהדר לצלויי\u0004 \u0005[וכאשר\u0006 הוא \u0005מגיע לביתו אינו צריך לחזור ולהתפלל],\u0006 ואילו \u0003בתפלה קצרה, לא בעי לצלויי\u0004 \u0005[אינו צריך להתפלל]\u0006 \u0003לא תלת קמייתא\u0004 \u0005[שלוש ראשונות]\u0006 \u0003ולא תלת בתרייתא\u0004 \u0005[שלוש אחרונות],\u0006 \u0003וכי מטי לביתיה בעי למהדר לצלויי\u0004 \u0005[וכאשר\u0006 הוא \u0005מגיע לביתו\u0006 הוא \u0005צריך לחזור להתפלל],\u0006 ש\"הביננו\" דינה כתפילת שמונה עשרה, על אף קיצורה. ואילו התפילה הקצרה נאמרת רק כתחליף לשעת הדחק לתפילה ממש.","\u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003\"הביננו\"\u0004 כיון שכאמור חשובה היא כתפילת שמונה עשרה, צריך לאומרה כשהוא \u0003מעומד,\u0004 אילו \u0003תפלה קצרה\u0004 כיון שנופלת היא בחשיבותה, לכן יכול לאומרה \u0003בין מעומד בין מהלך.\u0004","שנינו במשנה שאם \u0003היה רוכב על החמור\u0004 והגיע זמן התפילה — ירד מעל החמור ויתפלל, ורק בשעת הדחק יכול הוא להתפלל כשהוא רכוב, ויכוין לבו לעבר ירושלים והמקדש. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003היה רוכב על החמור והגיע זמן תפלה, אם יש לו מי שיאחז את חמורו\u0004 — \u0003ירד למטה ויתפלל, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003ישב במקומו ויתפלל. רבי אומר: בין כך ובין כך,\u0004 בין אם יש מי שיכול להחזיק בחמור בזמן שיתפלל ובין אם אין, \u0003ישב במקומו ויתפלל, לפי שאין דעתו מיושבת עליו,\u0004 שהוא ממהר לדרכו וירידה מעל החמור ועמידה לתפלה ורכיבה מחדש על החמור עשויה לגרום לעיכוב אשר עלול להפריע לו בהתרכזותו בתפילה.","\u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יהושע בן לוי: הלכה\u0004 בענין זה \u0003כרבי.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003סומא\u0004 \u0005[עוור]\u0006 \u0003ו\u0004כן כל \u0003מי שאינו יכול לכוין את הרוחות\u0004 (כיוונים), ובשל כך אינו יודע היכן ירושלים כדי שיתפלל לעברה — דיו ש\u0003יכוין לבו כנגד אביו שבשמים, שנאמר: \"והתפללו אל ה'\"\u0004 (מלכים א ח, מד).","והיכול לכוון את מקומו, אם \u0003היה עומד בתפלה בחוץ לארץ\u0004 — \u0003יכוין את לבו כנגד ארץ ישראל, שנאמר: \"והתפללו אליך דרך ארצם\u0004 אשר נתת לאבותם\u0003\"\u0004 (שם, מח). \u0003היה עומד בארץ ישראל\u0004 — \u0003יכוין לבו כנגד ירושלים, שנאמר: \"והתפללו אל ה' דרך העיר אשר בחרת\u0004 בה\u0003\"\u0004 (שם, מד). \u0003היה עומד בירושלים\u0004 — \u0003יכוין את לבו כנגד בית המקדש, שנאמר: \"\u0004ובאו \u0003והתפללו אל הבית הזה\"\u0004 (דברי הימים ב ו, לב). \u0003היה עומד בבית המקדש\u0004 — \u0003יכוין את לבו כנגד בית קדשי הקדשים, שנאמר: \"והתפללו אל המקום הזה\"\u0004 (מלכים א ח, לה). \u0003היה עומד בבית קדשי הקדשים\u0004 — \u0003יכוין את לבו כנגד בית הכפורת\u0004 שעל הארון שהיא משכן כבוד ה'. \u0003היה עומד אחורי בית הכפורת\u0004 — \u0003יראה עצמו כאילו לפני הכפורת\u0004 ויפנה אליה. ו\u0003נמצא\u0004 שה\u0003עומד\u0004 בתפילה \u0003במזרח מחזיר פניו למערב.\u0004 והעומד \u0003במערב — מחזיר פניו למזרח. בדרום\u0004 — \u0003מחזיר פניו לצפון. בצפון\u0004 — \u0003מחזיר פניו לדרום.\u0004 ובכך \u0003נמצאו כל ישראל מכוונין את לבם למקום אחד,\u0004 בית קדשי הקדשים שבמקדש.","ורמז לדבר \u0003אמר ר' אבין, ואיתימא\u0004 \u0005[ויש שאומרים]\u0006 שאמר זאת \u0003ר' אבינא: מאי קראה\u0004 \u0005[מהו הפסוק]\u0006 המרמז על כך — \u0003\"כמגדל דויד צוארך בנוי לתלפיות\u0004 אלף המגן תלוי עליו כל שלטי הגבורים\" (שיר השירים ד, ד), והוא דורש \"תלפיות\" — \u0003תל שכל פיות פונים בו\u0004 (אליו).","בענין התפילה בדרך מסופר כי \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל ולוי, כי הוו בעו למיפק לאורחא\u0004 \u0005[כאשר היו רוצים,\u0006 צריכים, \u0005לצאת לדרך]\u0006 בבוקר, \u0003הוו מקדמי ומצלי\u0004 \u0005[היו מקדימים לפני\u0006 הזריחה \u0005ומתפללים],\u0006 \u0003וכי הוה מטי\u0004 \u0005[וכאשר היה מגיע]\u0006 \u0003זמן קריאת שמע\u0004 בתוך הדרך \u0003קרו\u0004 \u0005[היו קוראים].\u0006","ועל כך אומרים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 היו עושים זאת — \u0003כי האי תנא [כ\u0004דעת \u0005תנא זה]\u0006 ששנינו דבריו בתוספתא. \u0003דתניא\u0004 \u0005[ששנינו\u0006 בתוספתא\u0005]:\u0006 \u0003השכים לצאת לדרך\u0004 עוד לפני זמן קריאת שמע לאחר עלות השחר, \u0003מביאין לו שופר ותוקע\u0004 בו (אם היה הדבר בראש השנה), \u0003לולב ומנענע\u0004 בסוכות, \u0003מגילה\u0004 (מגילת אסתר) \u0003וקורא בה\u0004 בפורים, \u0003וכשיגיע זמן קריאת שמע\u0004 — \u0003קורא.\u0004 וכן אם \u0003השכים לישב בקרון או בספינה\u0004 כדי לנסוע לדרכו — \u0003מתפלל, וכשיגיע זמן קריאת שמע\u0004 — \u0003קורא.\u0004","\u0003ר' שמעון בן אלעזר אומר: בין כך ובין כך,\u0004 בכל מקרה מוטב שיהא \u0003קורא קריאת שמע ומתפלל\u0004 (בקרון) \u0003כדי שיסמוך גאולה לתפלה.\u0004","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חולקים],\u0006 מה יסוד מחלוקתם? ומשיבים: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 התנא הראשון \u0005סבור]\u0006 כי \u0003תפלה מעומד עדיף\u0004 \u0005[עדיפה],\u0006 ומוטב אם כן שיקדים ויתפלל בביתו מעומד, \u0003ומר סבר\u0004 \u0005[חכם זה,\u0006 ר' שמעון בן אלעזר \u0005סבור]\u0006 כי \u0003מסמך\u0004 \u0005[לסמוך]\u0006 \u0003גאולה לתפלה עדיף,\u0004 אף אם כתוצאה מכך על המתפלל לוותר על העמידה בשעת התפילה.","מעין דברים אלו על צורות שונות של תפילה שהיו חכמים מחוייבים לעשות שלא כרגיל, מסופר כי \u0003מרימר ומר זוטרא הוו מכנפי בי עשרה בשבתא דרגלא ומצלו, והדר נפקי לפרקא\u0004 \u0005[היו אוספים עשרה\u0006 אנשים \u0005בשבת שבחג ומתפללים, ואחר כך יוצאים לדרשה],\u0006 שבגלל רוב הנאספים לשמוע את דרשתם של חכמים אלה בחג לא יכלו להתפלל בזמן הראוי, ולכן הקדימו.","\u0003רב אשי\u0004 במקרה כעין זה \u0003מצלי בהדי צבורא\u0004 \u0005[היה מתפלל עם הציבור]\u0006 \u0003ביחיד,\u0004 ו\u0003מיושב,\u0004 כדי שלא יבחינו שהוא מתפלל. ואחר כך \u0003כי הוה אתי לביתיה, הדר ומצלי\u0004 \u0005[כאשר היה בא לביתו, חזר והתפלל]\u0006 \u0003מעומד,\u0004 כדי להתפלל בישוב הדעת. \u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]:\u0006 \u0003ולעביד מר\u0004 \u0005[ושיעשה אדוני]\u0006 \u0003כמרימר ומר זוטרא,\u0004 שיאסוף מנין ויתפלל לפני הדרשה! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003טריחא לי מלתא\u0004 \u0005[טורח עבורי הדבר]\u0006 לאחר כל כך את הדרשה. \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 חכמים: \u0003ולעביד מר כאבוה\u0004 \u0005[ושיעשה אדוני כאביהם]\u0006 של \u0003שמואל ולוי\u0004 שהקדימו להתפלל עוד לפני הזריחה! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא חזינא להו לרבנן קשישי מינן דעבדי הכי\u0004 \u0005[ראיתי אותם\u0006 את ה\u0005חכמים\u0006 ה\u0005קשישים מאתנו העושים כן],\u0006 ונראה שאין זו דרך שנתקבלה בהלכה.","\u0003ר' אלעזר בן עזריה אומר: אין תפלת המוספין אלא בחבר עיר,\u0004 כלומר, כשיש בעיר ציבור של עשרה מתפללים. \u0003וחכמים אומרים:\u0004 ניתן להתפלל תפילת המוספים בין \u0003בחבר עיר ו\u0004בין \u0003שלא בחבר עיר. ר' יהודה אומר משמו\u0004 של ר' אלעזר בן עזריה גירסה אחרת: \u0003כל מקום שיש שם חבר עיר\u0004 — \u0003יחיד פטור\u0004 בכלל \u0003מתפלת המוספין.\u0004","לכאורה נראה שאין הבדל בין דברי ר' אלעזר בן עזריה לבין דבריו המובאים בשמו על ידי ר' יהודה, ולכן שאלו: השיטה שהביא \u0003ר' יהודה היינו תנא קמא\u0004 \u0005[זוהי\u0006 בדיוק שיטת \u0005התנא הראשון]\u0006 בדברי ר' אלעזר בן עזריה! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם,\u0006 מחלוקת\u0005]\u0006 בדבר \u0003יחיד שלא בחבר עיר,\u0004 שאין באותה עיר ציבור של עשרה מתפללים, שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 ששיטת ר' אלעזר בן עזריה בכגון זה שה\u0003יחיד פטור\u0004 בכלל מתפילת המוספים, כיון שלא תקנוה אלא בעשרה. \u0003ו\u0004אילו \u0003ר' יהודה סבר\u0004 \u0005[סבור]\u0006 ששיטת ר' אלעזר בן עזריה בכגון זה ש\u0003חייב\u0004 היחיד להתפלל מוסף, שלדעתו אין היחיד נפטר אלא בעשרה, ששליח הציבור פוטרו.","\u0003אמר רב הונא בר חיננא אמר ר' חייא בר רב: הלכה כ\u0004שיטה שהביא \u0003ר' יהודה שאמר משום\u0004 (בשם) רבו \u0003ר' אלעזר בן עזריה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חייא בר אבין\u0004 לר' יהודה לסייעו: \u0003שפיר קאמרת\u0004 \u0005[יפה אמרת],\u0006 וראייה לדבר, ממה ש\u0003אמר שמואל: מימי לא מצלינא צלותא\u0004 \u0005[התפללתי תפילת]\u0006 ה\u0003מוספין ביחיד\u0004"],["\u0003בנהרדעא\u0004 שיש בה חבר עיר, \u0003לבר מההוא יומא דאתא פולמוסא דמלכא למתא\u0004 \u0005[חוץ מאותו יום שבא גייס של המלך לעיר],\u0006 \u0003ואטרידו רבנן\u0004 \u0005[ונטרדו חכמים]\u0006 \u0003ולא צלו\u0004 \u0005[התפללו]\u0006 בציבור, \u0003וצלי לי\u0004 \u0005[והתפללתי]\u0006 \u0003ביחיד, והואי\u0004 \u0005[והייתי]\u0006 \u0003יחיד שלא בחבר עיר.\u0004 הרי שנהג כר' יהודה בענין זה.","ואולם לא הכל קבלו דעה זו, ומסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' חנינא קרא\u0004 \u0005[בעל המקרא]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ינאי, ויתיב וקאמר\u0004 \u0005[וישב ואמר]:\u0006 \u0003הלכה כר' יהודה שאמר משום\u0004 (בשם) \u0003ר' אלעזר בן עזריה. אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי: \u0003פוק קרא קראיך לברא\u0004 \u0005[צא קרא מקראותיך בחוץ],\u0006 כלומר, הלכה זו אינה מקובלת על חכמי בית המדרש ואין מקומה אלא בחוץ, ש\u0003אין הלכה כר' יהודה שאמר משום ר' אלעזר בן עזריה.\u0004","ולא רק בבית המדרש, אלא אף \u0003אמר ר' יוחנן: אני ראיתי את ר' ינאי דצלי והדר צלי\u0004 \u0005[שהתפלל וחזר והתפלל],\u0006 ומן הסתם תפילה ראשונה היתה תפילת שחרית והשניה תפילת מוסף, אם כן, הרי שהוא סובר שלא כדעת ר' אלעזר בן עזריה, ודעתו שאף שלא ב\"חבר עיר\" צריך להתפלל מוסף. כאשר סופר דבר זה לאחר זמן בבית המדרש \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא\u0004 רבו: ומה מוכיח שאכן התפלל בפעם השניה תפילת מוספים, \u0003ודילמא מעיקרא\u0004 \u0005[ושמא מתחילה]\u0006 \u0003לא כוון דעתיה\u0004 \u0005[דעתו,\u0006 לבו\u0005]\u0006 \u0003ולבסוף כוון דעתיה\u0004 \u0005[כיון ליבו],\u0006 וחזר והתפלל כדי להתפלל תפילה שניה בכוונה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003חזי מאן גברא רבא דקמסהיד עליה\u0004 \u0005[ראה מיהו האיש הגדול המעיד עליו],\u0006 שוודאי התבונן ר' יוחנן יפה כשהעיד דבר זה.","אגב המסופר על תפילות חכמים, מספרים עוד כי \u0003ר' אמי ור' אסי אף על גב דהוו להו תליסר בי כנישתא בטבריא\u0004 \u0005[אף על פי שהיו להם שלושה עשר בתי כנסת בטבריה]\u0006 \u0003לא הוו מצלו\u0004 \u0005[היו מתפללים]\u0006 \u0003אלא ביני עמודי, היכא דהוו גרסי\u0004 \u0005[בין העמודים במקום שהיו לומדים],\u0006 שחביבה היא התפילה במקום תורה דווקא.","\u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003רב יצחק בר אבדימי משום\u0004 (בשם) \u0003רבינו\u0004 (הוא רב) \u0003אמר: הלכה כ\u0004שיטת \u0003ר' יהודה שאמר משום ר' אלעזר בן עזריה.\u0004 מסופר ש\u0003ר' חייא בר אבא צלי והדר צלי\u0004 \u0005[התפלל וחזר והתפלל].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא: מאי טעמא עביד מר הכי\u0004 \u0005[מה טעם עושה אדוני כך]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שאדוני עושה כך \u0003משום\u0004 ש\u0003לא כוון מר דעתיה\u0004 \u0005[אדוני דעתו]\u0006 בפעם הראשונה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אליעזר: לעולם ימוד\u0004 (ימדוד, יעריך) \u0003אדם את עצמו\u0004 (לשער כפי יכולתו), \u0003אם יכול\u0004 הוא \u0003לכוין את לבו\u0004 לתפילה — \u0003יתפלל, ואם לאו\u0004 \u0005[לא]\u0006 שאינו יכול — \u0003אל יתפלל.\u0004 אם כן לא משום כך התפלל פעמיים, \u0003אלא\u0004 משום \u0003שלא אדכר מר דריש ירחא\u0004 \u0005[הזכיר אדוני\u0006 את \u0005של ראש החודש]\u0006 ולכן חזר והתפלל.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שאם \u0003טעה ולא הזכיר\u0004 בתפילתו בראש חודש את התוספת המיוחדת \u0003של ראש חודש,\u0004 אם היה זה \u0003בערבית\u0004 — \u0003אין מחזירין אותו\u0004 כלל. וטעמו של דבר — \u0003מפני שיכול לאומרה בשחרית.\u0004 טעה ושכח \u0003בשחרית\u0004 — \u0003אין מחזירין אותו, מפני שיכול לאומרה במוספין\u0004 (מוסף). \u0003במוספין\u0004 — \u0003אין מחזירין אותו מפני שיכול לאומרה במנחה.\u0004 והרי שזו אינה סיבה לחזור ולהתפלל, ובוודאי שלא משום כך חזר ר' חייא בר אבא על תפילתו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא בר אבא: \u0003לאו איתמר עלה\u0004 \u0005[האם לא נאמר עליה,\u0006 על ברייתא זו\u0005]\u0006 ש\u0003אמר ר' יוחנן\u0004 שכל האמור בה דווקא \u0003בצבור שנו,\u0004 אבל יחיד שלא הזכיר ראש חודש — חוזר ומתפלל, ואכן כן עשה.","מאחר שדובר עד כאן בתפילה שחוזר אדם ומתפלל, מכל טעם שהוא, שואלים כעת: \u0003כמה ישהה בין תפלה לתפלה,\u0004 להראות שאינו עושה מצוות חבילות חבילות? ובכך הסכימו \u0003רב הונא ורב חסדא\u0004 בעיקר דברים, אלא שנחלקו בלשון שבה אמרו אותם (רש\"י). \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שצריך לשהות \u0003כדי שתתחונן דעתו עליו,\u0004 שיוכל לומר בלשון תחנונים, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 עד \u0003שתתחולל דעתו עליו\u0004 ותתחזק שיוכל להתפלל בענין. ומעירים ששניהם סמכו את הדברים על לשונות תפילה שנאמרו אצל משה.","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 בלשון \u0003\"כדי שתתחונן דעתו עליו\",\u0004 הרי זה כעין \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואתחנן אל ה'\"\u0004 (דברים ג, כג). \u0003ומאן דאמר\u0004 \u0005[מי שאומר]\u0006 בלשון \u0003\"כדי שתתחולל דעתו עליו\",\u0004 הרי זה כעין \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויחל משה\u0004 את פני ה'\u0003\"\u0004(שמות לב, יא), על מנת שהתפילה השניה גם היא תהיה בדרך תחנונים.","מאחר שדובר קודם בדבר מי שטעה ולא הזכיר את ראש החודש בתפילתו מביאים את מה ש\u0003אמר רב ענן אמר רב: טעה ולא הזכיר של ראש חדש בערבית\u0004 — \u0003אין מחזירין אותו\u0004 כלל. וטעמו של דבר — \u0003לפי שאין בית דין מקדשין את החדש אלא ביום,\u0004 ותפילת ראש חודש שהיא מעין קידוש ראש החודש על ידי בית דין מעיקרה שייכת איפוא רק ליום בלבד.","\u0003אמר אמימר:\u0004 יש להגביל את הדברים ולומר כי \u0003מסתברא מילתא\u0004 \u0005[מסתברים דברי]\u0006 \u0003רב בחדש מלא,\u0004 שמאחר שיש אז שני ימים אפשריים של ראש חודש (יום ל' של החודש הקודם או א' של הבא) הרי קידוש החודש תלוי אך בבית דין בלבד. \u0003אבל בחדש חסר,\u0004 שיש בו רק יום אחד ודאי של ראש חודש — \u0003מחזירין אותו\u0004 אף בערב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: מכדי\u0004 \u0005[הרי]\u0006 \u0003רב טעמא קאמר\u0004 \u0005[טעם,\u0006 נימוק \u0005אמר],\u0006 ואם כן \u0003מה לי\u0004 הבדל אם החודש \u0003חסר, ומה לי\u0004 אם הוא \u0003מלא, אלא, לא שנא\u0004 \u0005[אינו שונה,\u0006 אין הבדל\u0005]\u0006 כי הדבר מבוסס על ההשוואה בין קידוש החודש לתפילת ראש חודש — וקידוש החודש לעולם אינו שייך בלילה.","\u0003הדרן עלך תפלת השחר\u0004","\u0003אין\u0004 ראוי שיהיו המתפללים \u0003עומדין\u0004 לתפילה \u0003אלא מתוך כובד ראש\u0004 (רצינות והכנעה). ומסורת בידינו כי ה\u0003חסידים הראשונים היו שוהין\u0004 (ממתינים) לפני תפילתם \u0003שעה אחת,\u0004 כדי להגיע לכלל כובד הראש הראוי לתפילה, \u0003ו\u0004רק אחר כך היו \u0003מתפללין,\u0004 וכל זה \u0003כדי שיכוונו לבם\u0004 כראוי \u0003ל\u0004פני \u0003אביהם שבשמים.\u0004 העמידה בתפילה משמעה עמידה לפני ה', ועל כן בשעת התפילה \u0003אפילו המלך שואל בשלומו\u0004 — \u0003לא ישיבנו, ואפילו נחש כרוך על עקבו\u0004 — \u0003לא יפסיק,\u0004 אלא ימשיך בתפילתו.","שנינו במשנתנו שראויה התפילה שתהיה בכובד ראש, ובענין זה שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה,\u0006 מהיכן אנו לומדים אותם\u0005]?\u0006 \u0003אמר ר' אלעזר:\u0004 למדים זאת מן המקראות המספרים על תפילת חנה אם שמואל, שכך \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והיא מרת נפש\u0004 ותתפלל על ה' ובכה תבכה\u0003\"\u0004(שמואל א א, יא).","ראיה זו דוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מדוע ראיה היא זו\u0005]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003חנה שאני\u0004 \u0005[שונה]\u0006 היא, משום \u0003דהות מרירא לבא טובא\u0004 \u0005[שהיתה מרת לב ביותר]\u0006 ולכן אף תפילתה הייתה במרירות, ואין זה מוכיח שהכל חייבים להתפלל כך.","\u0003אלא אמר ר' יוסי בר' חנינא:\u0004 יש להביא ראיה לכך \u0003מהכא\u0004 \u0005[מכאן],\u0006 מכתוב זה שאמרו דוד: \u0003\"ואני ברב חסדך אבוא ביתך אשתחוה אל היכל קדשך ביראתך\"\u0004 (תהלים ה, ח), הרי שהכניסה אל התפילה בדומה לכניסה לבית המקדש צריכה להיעשות ביראה.","ושוב דוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מדוע ראיה היא זו\u0005]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003דוד שאני\u0004 \u0005[שונה]\u0006 הוא, משום \u0003דהוה\u0004 \u0005[שהיה]\u0006 \u0003מצער נפשיה ברחמי טובא\u0004 \u0005[עצמו ברחמים,\u0006 בתפילה, \u0005הרבה]\u0006 כדי לכפר על חטא בת שבע, ואין להביא ממנו ראיה לכל אדם. \u0003אלא אמר ר' יהושע בן לוי:\u0004 יש להביא ראיה לכך \u0003מהכא\u0004 \u0005[מכאן],\u0006 מכתוב זה שאמרו דוד כלפי הכל, ולא כלפי עצמו בלבד: \u0003\"\u0004הבו לה' כבוד שמו \u0003השתחוו לה' בהדרת קדש\"\u0004 (שם כט, ב), ואמרו חכמים: \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"בהדרת\u0004 קודש \u0003\"אלא \"בחרדת\u0004 קודש","\u0003\",\u0004 ומשמעו, שכך יבוא האדם להתפלל מתוך כובד ראש מרובה של קדושה. ושוב דוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מדוע ראיה היא זו\u0005]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 בכתוב זה, שיש לקרוא בו \u0003\"הדרת\u0004 קודש \u0003\"ממש\u0004 וכפי שאכן כתוב בו. ואין צורך לשנות את קריאתו, ומשמעות הדבר שיש להתפלל מתוך לבוש הדור, \u0003כי הא\u0004 \u0005[כמו זה]\u0006 המסופר ב\u0003רב יהודה דהוה מציין נפשיה, והדר מצלי\u0004 \u0005[שהיה מקשט עצמו, ואחר כן מתפלל].\u0006 שלדעתו הבא לפני המלך צריך ללבוש את היפים בבגדיו. ועדיין אין אנו יודעים מה המקור שראויה התפילה שתהיה בכובד ראש. \u0003אלא אמר רב נחמן בר יצחק\u0004 ראיה לדבר \u0003מהכא\u0004 \u0005[מכאן],\u0006 מכתוב זה: \u0003\"עבדו את ה' ביראה וגילו ברעדה\"\u0004 (שם ב, יא).","מאחר שהובא כתוב זה, שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירושן\u0005]\u0006 של המילים \u0003\"וגילו ברעדה\"? אמר רב אדא בר מתנא\u0004 שכך \u0003אמר רבה\u0004 בפירוש הכתוב: אף \u0003במקום גילה שם תהא רעדה,\u0004 ולא יגיע אדם לשמחה לא מרוסנת.","ומעין זה מסופר ש\u0003אביי הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רבה\u0004 רבו. \u0003חזייה\u0004 \u0005[ראהו]\u0006 רבה \u0003דהוה קא בדח טובא\u0004 \u0005[שהיה מבודח ביותר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 והרי \u0003\"וגילו ברעדה\" כתיב\u0004 \u0005[נאמר],\u0006 וראוי איפוא שלא תהיה השמחה רבה מדי!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: מותר אני בכך משום ש\u0003אנא\u0004 \u0005[אני]\u0006 \u0003תפילין מנחנא\u0004 \u0005[מניח אני]\u0006 כעת, ומורא שמים עלי מכוחם.","ומעין זה מסופר כי \u0003ר' ירמיה הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003ר' זירא. חזייה\u0004 \u0005[ראהו]\u0006 ר' זירא \u0003דהוה קא בדח טובא\u0004 \u0005[שהיה מבודח ביותר]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 והרי \u0003\"בכל עצב יהיה מותר\"\u0004 (משלי יד, כג) \u0003כתיב\u0004 \u0005[נאמר]?\u0006 וראוי הוא איפוא העצב ולא השמחה היתירה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה בתשובה: מותר אני בכך משום ש\u0003אנא\u0004 \u0005[אני]\u0006 \u0003תפילין מנחנא\u0004 \u0005[מניח אני]\u0006 כעת.","מעין דברים אלה מסופר: \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא עבד הילולא לבריה, חזנהו לרבנן דהוו קבדחי טובא\u0004 \u0005[עשה\u0006 סעודת \u0005חתונה לבנו, ראה אותם את החכמים שהיו מבודחים ביותר].\u0006"],["\u0003אייתי כסא דמוקרא בת ארבע מאה זוזי, ותבר קמיהו, ואעציבו\u0004 \u0005[הביא כוס יקרה השווה ארבע מאות זוז, ושבר לפניהם, והתעצבו].\u0006","וכן מסופר ש\u0003רב אשי עבד הילולא לבריה\u0004 \u0005[עשה חתונה לבנו],\u0006 \u0003חזנהו לרבנן דהוו קא בדחי טובא\u0004 \u0005[ראה אותם, את החכמים שהיו מבודחים ביותר].\u0006 \u0003אייתי כסא דזוגיתא חיורתא, ותבר קמיהו, ואעציבו\u0004 \u0005[הביא כוס של זכוכית לבנה,\u0006 שהיתה יקרה ביותר, \u0005ושבר לפניהם, ונתעצבו].\u0006","בדומה לכך מסופר ש\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003לרב המנונא זוטי\u0004 \u0005[הקטן]\u0006 \u0003בהלולא\u0004 \u0005[ב\u0006סעודת \u0005חתונה]\u0006 של \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא: לישרי לן מר\u0004 \u0005[ישיר לנו אדוני].\u0006 ומאחר שסבר שרבתה מדי השמחה ובדיחות הדעת, \u0003אמר להו\u0004 \u0005[להם]\u0006 בדרך השיר: \u0003וי לן, דמיתנן, וי לן, דמיתנן\u0004 \u0005[אוי לנו, שנמות. אוי לנו, שנמות].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003אנן\u0004 \u0005[אנחנו]\u0006 \u0003מה נעני בתרך\u0004 \u0005[נענה אחריך,\u0006 כחרוז חוזר בשיר זה \u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 כך תענו, \u0003הי\u0004 \u0005[היכן]\u0006 ה\u0003תורה, והי\u0004 \u0005[היכן]\u0006 ה\u0003מצוה דמגנו עלן\u0004 \u0005[שיגנו עלינו].\u0006","ומעין דברים אלה \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחאי: אסור לאדם שימלא שחוק פיו בעולם הזה,\u0004 בעת הגלות (גאונים), \u0003ש\u0004כן \u0003נאמר:\u0004 \"בשוב ה' את שיבת ציון היינו כחולמים\" (תהלים קכו, א). ורק \u0003\"אז ימלא שחוק פינו ולשוננו רנה\"\u0004 (שם, ב). שכן \u0003אימתי\u0004 הוא זמן השמחה, \u0003בזמן ש\"יאמרו בגוים הגדיל ה' לעשות עם אלה\"\u0004 (שם). ונמסר ש\u0003אמרו עליו על ריש לקיש שמימיו לא מלא שחוק פיו בעולם הזה, מכי\u0004 \u0005[מאז]\u0006 ש\u0003שמעה\u0004 לאמירה זו \u0003מ\u0004פי \u0003ר' יוחנן רביה\u0004 \u0005[רבו].\u0006","שנינו במשנה שראוי לעמוד ולהתפלל מתוך כובד ראש, ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין עומדין להתפלל לא מתוך\u0004 העיסוק ב\u0003דין, ולא מתוך דבר הלכה,\u0004 לפי שהמחשבה על מסקנת הדין וההלכה תטריד אותו בתוך תפילתו, \u0003אלא\u0004 ראוי להתפלל \u0003מתוך\u0004 (לאחר ששנה) \u0003הלכה פסוקה\u0004 המקובלת על הכל, ואין בה מקום למחלוקת או להרהורים נוספים.","\u0003ו\u0004שואלים: \u0003היכי דמי\u0004 \u0005[כיצד דומה,\u0006 מהי בדיוק\u0005]\u0006 \u0003הלכה פסוקה?\u0004 ומובאות דוגמאות שונות.","\u0003אמר אביי: כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 של \u0003ר' זירא,\u0004 שכך \u0003אמר ר' זירא: בנות ישראל החמירו על עצמן, שאפילו רואות טיפת דם כחרדל יושבת עליה שבעה נקיים.\u0004 שכן לפי דין תורה אשה הרואה דם בתוך אחד עשר יום לאחר תקופת וסתה הקבועה אין דינה כנידה, אלא היא טובלת ונטהרת למחרת (\"שומרת יום כנגד יום\"). אולם בנות ישראל החמירו על עצמן, שגם אם רואות הן דם כלשהו הרי הן נוהגות כאילו היה זה דם זיבה, המחייב להפסיק אחריו ולמנות שבעה ימים טהורים (נקיים) עד שתיטהר (עיין ויקרא טו, כה).","\u0003רבא אמר\u0004 דוגמא אחרת של הלכה פסוקה, \u0003כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 של \u0003רב הושעיא\u0004 שכך \u0003אמר רב הושעיא: מערים אדם על תבואתו ומכניסה\u0004 לחצר בעודה \u0003במוץ שלה, כדי ש\u0004בכך \u0003תהא בהמתו אוכלת\u0004 ממנה, \u0003ופטורה\u0004 היא התבואה עדיין \u0003מן\u0004 חובת הפרשת \u0003המעשר\u0004 ממנה. שכן הלכה היא כי תבואה שנידושה והועמדה בכרי חייבת בהפרשת מעשר, ללא הפרש מה הוא הצורך שלמענו נלקחת תבואה זו. ואולם תבואה המעורבת עדיין במוץ אינה חייבת מן התורה עדיין בהפרשת מעשר, ורק חכמים הם שאסרו לאכול מתבואה זו אכילת קבע, ואכילת בהמה אינה נחשבת אכילת קבע, ולכן מותר להאכילה לבהמה מבלי לעשרה קודם לכן.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 דוגמא נוספת להלכה פסוקה שעומדים מתוכה לתפילה, \u0003כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 של \u0003רב הונא,\u0004 שכך \u0003אמר רב הונא,\u0004 שכך \u0003אמר ר' זעירא: המקיז דם בבהמת קדשים\u0004 שהוקדשה לקרבן, אמנם דם הקרבנות הנזרק על המזבח אינו נחשב לרכוש הקודש אשר כל הנהנה ממנו נחשב למועל בקודש, מכל מקום \u0003אסור\u0004 הדם \u0003בהנאה\u0004 לזרים, \u0003ומועלין בו.\u0004 ככל הנהנה מרכוש המקדש האסור לזרים, ואם עשה זאת בשוגג חייב להביא קרבן על מעילתו.","ומסופר ש\u0003רבנן עבדי כמתניתין\u0004 \u0005[חכמים עשו,\u0006 נהגו, \u0005כמשנתנו]\u0006 והתפללו מתוך כובד ראש, ואילו \u0003רב אשי עביד\u0004 \u0005[עשה]\u0006 \u0003כברייתא\u0004 והקדים לתפילתו הלכה פסוקה.","ועוד בעניין ההכנה הראויה לתפילה \u0003תנו רבנן\u0004 \u0005[שנו חכמים ]:\u0006 \u0003אין עומדין להתפלל לא מתוך עצבות, ולא מתוך עצלות. ו\u0004אף \u0003לא מתוך שחוק, ולא מתוך שיחה, ולא מתוך קלות ראש, ולא מתוך דברים בטלים\u0004 (שיחה חסרת משמעות), \u0003אלא מתוך שמחה של מצוה.\u0004","\u0003וכן\u0004 הראוי הוא ש\u0003לא יפטר\u0004 (יפרד) \u0003אדם מחברו לא מתוך שיחה, ולא מתוך שחוק, ולא מתוך קלות ראש, ולא מתוך דברים בטלים, אלא מתוך דבר הלכה.\u0004 וראיה לדבר ששמחה של מצוה חביבה היא, \u0003שכן מצינו\u0004 (מצאנו) \u0003בנביאים הראשונים\u0004 (כלומר, בספרי הנביאים במקרא) \u0003שסיימו דבריהם בדברי שבח ותנחומים.\u0004","\u0003וכן תנא\u0004 \u0005[שנה]\u0006 ברייתא \u0003מרי בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' ירמיה בר אבא: אל יפטר אדם מחבירו אלא מתוך דבר הלכה, שמתוך כך זוכרהו,\u0004 שתמיד כשהוא נזכר בחבריו זוכר הוא אותו לטובה על הלכה זו שחידש לו (אל\"ז).","ודוגמא לדבר, \u0003כי הא\u0004 \u0005[כגון זה]\u0006 המסופר ש\u0003רב כהנא אלוייה\u0004 \u0005[ליווהו]\u0006 את \u0003רב שימי בר אשי מ\u0004היישוב \u0003פום נהרא עד בי צניתא\u0004 \u0005[מקום הדקלים]\u0006 שב\u0003בבל. כי מטא להתם\u0004 \u0005[כאשר הגיע לשם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא לרב שימי בר אשי: \u0003מר, ודאי דאמרי אינשי\u0004 \u0005[אדון, מהו שאומרים אנשים]:\u0006 \u0003הני צניתא\u0004 \u0005[דקלים אלה]\u0006 של \u0003בבל איתנהו\u0004 \u0005[ישנם]\u0006 במקום זה \u0003מ\u0004זמנו של \u0003אדם הראשון ועד השתא\u0004 \u0005[עכשיו]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שימי בר אשי: \u0003אדכרתן מילתא\u0004 \u0005[הזכרתני דבר]\u0006 שאמר \u0003ר' יוסי בר' חנינא,\u0004 שכך \u0003אמר ר' יוסי בר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"בארץ אשר לא עבר בה איש ולא ישב אדם שם\"\u0004 (ירמיהו ב, ו) שיש לדקדק בלשון הפסוק: \u0003וכי מאחר\u0004 שהיא ארץ ש\u0003לא עבר\u0004 בה אדם מעולם, \u0003היאך\u0004 (איך) יכול להיות ש\u0003ישב\u0004 בה אדם בקביעות? ולא היה הכתוב צריך להמשיך ולומר ש\"לא ישב אדם שם\"! \u0003אלא\u0004 בא כתוב זה \u0003לומר לך\u0004 (ללמדך) ש\u0003כל ארץ ש\u0004עבר בה אדם הראשון ו\u0003גזר עליה אדם הראשון לישוב,\u0004 שיהא בה מקום ישוב בני אדם — היא \u0003נתישבה. וכל ארץ שלא גזר עליה אדם הראשון לישוב\u0004 — \u0003לא נתישבה.\u0004 ונכון אם כן מה שאומרים האנשים על קדמותם של דקלי בבל שהם מימי אדם הראשון, והכוונה היא שמזמנו ארץ זו מוכשרת לגדל ולהצמיח דקלים (מאירי). והובאה איפוא דוגמה כיצד הנפרד מחבירו בדבר תורה מתחדשים לו דברים.","ומשהוזכר ענין מצוות ליווי של תלמיד את רבו רב שימי בר אשי מסופר כי \u0003רב מרדכי אלוייה\u0004 \u0005[ליווהו]\u0006 את \u0003רב שימי בר אשי\u0004 רבו \u0003מ\u0004העיר \u0003הגרוניא,\u0004 מרחק רב \u0003ועד בי כיפי. ואמרי לה\u0004 \u0005[ו\u0006יש ה\u0005אומרים\u0006 בגירסת \u0005אותה\u0006 שמועה\u0005]\u0006 כי היה ליווי זה מהגרוניא \u0003עד בי דורא.\u0004","ועוד בענין ההכנה לתפילה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003המתפלל צריך שיכוין את לבו לשמים. אבא שאול אומר: סימן\u0004 (ראיה) \u0003לדבר\u0004 זה עד כמה חשוב הוא, שכך נאמר בפסוק \u0003\"\u0004תאות ענוים שמעת ה' \u0003תכין לבם תקשיב אזנך\"\u0004 (תהלים י, יז), כלומר, אם המתפלל מכוון לבו בתפילתו (\"תכין לבם\") — אזי תפילתו מתקבלת (\"תקשיב אזנך\").","ובענין הכוונה בתפילה \u0003תניא\u0004 \u0005[שנינו\u0006 בבריתא\u0005]\u0006 שכך \u0003אמר ר' יהודה: כך היה מנהגו של ר' עקיבא, כשהיה מתפלל עם הציבור\u0004 — \u0003היה מקצר ועולה, מפני טורח ציבור,\u0004 שלא יחכו הכל עד שיסיים תפילתו. \u0003ו\u0004אולם \u0003כשהיה מתפלל בינו לבין עצמו\u0004 — היה מאריך בתפילה, עד ש\u0003אדם\u0004 היה \u0003מניחו\u0004 (משאירו לבדו) בעת התפילה כשר' עקיבא היה \u0003בזוית זו\u0004 של בית המדרש, \u0003ומוצאו\u0004 לאחר מכן ממשיך להתפלל כשהוא \u0003בזוית אחרת. וכל כך למה? מפני כריעות והשתחויות,\u0004 שהיה ר' עקיבא מתלהב בתפילתו, ובתוך כריעותיו והשתחויותיו היה זז מפינה לפינה ולא היה שם לב (רה\"ג).","הלכות רבות נלמדו מתוך הזכרת ענייני תפילותיהם של הראשונים. \u0003אמר ר' חייא בר אבא: לעולם יתפלל אדם בבית שיש בו חלונות, ש\u0004כך \u0003נאמר\u0004 בדניאל: \"ודניאל כדי ידע די רשים כתבא על לביתה וכוין פתיחן לה בעליתה נגד ירושלם, וזמנין תלתא ביומא הוא ברך על ברכוהי ומצלא ומודא קדם אלהה כל קבל די הוא עבד מן קדמת דנא\" (דניאל ו, יא), והרי שמסופר במנהגיו \u0003\"וכוין פתיחן ליה\"\u0004 \u0005[וחלונות פתוחים לו\u0006 בעלייתו]. בתוספתא הוסיפו ללמוד מדניאל כמה דברים בתפילה.","\u0003יכול יתפלל אדם כל היום כולו\u0004 כמה תפילות שירצה (צל\"ח) — הרי דבר זה \u0003כבר מפורש על ידי דניאל,\u0004 שכך נאמר בו: \u0003\"וזמנין תלתא\u0004 ביומא הוא ברך על ברכוהי ומצלא\u0003\"\u0004\u0005[\"שלש פעמים ביום הוא כורע על ברכיו ומתפלל\"]\u0006 ללמדנו שיש קביעות בתפילות.","ואם תאמר: \u0003יכול משבא לגולה הוחלה,\u0004 שמנהג התפילה הקבועה החל רק עם גלות בבל — \u0003כבר נאמר \"\u0004כל קבל \u0003די הוא עבד מן קדמת דנא\"\u0004 \u0005[כפי שהיה עושה מלפנים].\u0006","ועוד, \u0003יכול יתפלל אדם לכל רוח\u0004 (כיוון) \u0003שירצה\u0004 — \u0003תלמוד לומר\u0004 (מלמדנו) כתוב זה שכיוונה של התפילה הריהו \u0003\"לקבל\u0004 \u0005[כנגד]\u0006 \u0003ירושלם\".\u0004","אולם בדברי דניאל לא נאמר כיצד מחולקות שלוש תפילות אלה, ו\u0003יכול\u0004 לעלות על הדעת לומר ש\u0003יהא אדם כוללן בבת אחת\u0004 — לכך \u0003כבר מפורש על ידי דוד\u0004 שאין לעשות כן, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 על ידו: \u0003\"ערב ובקר וצהרים\u0004 אשיחה ואהמה וישמע קולי\u0003\"\u0004(תהלים נה, ד).","ועוד, \u0003יכול ישמיע\u0004 אדם \u0003קולו בתפלתו\u0004 (שמונה עשרה) — \u0003כבר מפורש על ידי חנה\u0004 בתפילתה \u0003ש\u0004כן \u0003נאמר\u0004 בה: \u0003\"\u0004וחנה היא מדברת על לבה רק שפתיה נעות \u0003וקולה לא ישמע\"\u0004 (שמואל א, א, יג).","ועוד בסדר התפילה הנלמד מתפילת ראשונים, \u0003יכול ישאל\u0004 (יבקש) \u0003אדם צרכיו\u0004 מה' \u0003ואחר כך יתפלל\u0004 בדברי תודה ותהילה — \u0003כבר מפורש על ידי שלמה\u0004 שאין לעשות כן, \u0003ש\u0004כך \u0003נאמר\u0004 בתפילת שלמה בחנוכת בית המקדש: \u0003\"לשמע אל הרנה ואל התפלה\u0004 אשר עבדך מתפלל לפניך היום\" (מלכים א ח, כח). ובפירוש הדברים, \u0003\"רנה\"\u0004 — \u0003זו תפלה\u0004 (דברי השבח וההודאה), ורק אחרי כן באה \u0003\"תפלה\" — זו בקשה\u0004 של צרכי האדם. ועל כן \u0003אין\u0004 המתפלל \u0003אומר דבר בקשה אחר\u0004 שאמר כבר \u0003\"אמת ויציב\",\u0004 ולפני תפילת שמונה עשרה, שהיא עיקר התפילה. אלא מתחילים בדברי שבח בשלוש הברכות הראשונות בשמונה עשרה, ורק אחריהן מוסיפים דברי בקשה. \u0003אבל אחר התפלה\u0004 אין כל הגבלה, אם רוצה אדם להאריך \u0003אפילו כסדר\u0004 ה\u0003ודוי תפילה של יום הכפורים\u0004 — \u0003אומר,\u0004 רשאי הוא לומר.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן\u0006 אותו דבר על ידי אמורא\u0005],\u0006 שכך \u0003אמר רב חייא בר אשי\u0004 שכך \u0003אמר רב: אף על פי שאמרו\u0004 חכמים ש\u0003שואל אדם צרכיו ב\"שומע תפלה\",\u0004 הרי זה רק להתיר ולהוסיף את דברי תפילתו הפרטית באמצע שמונה עשרה. ואולם \u0003אם בא\u0004 (ברצונו) להוסיף ו\u0003לומר אחר תפלתו\u0004 — \u0003אפילו\u0004 ארוכה היא בקשת צרכים זו \u0003כסדר\u0004 התפילה \u0003של יום הכפורים אומר\u0004 (רשאי הוא לומר).","\u0003אמר רב המנונא: כמה הלכתא גברוותא איכא למשמע מהני קראי\u0004 \u0005[הלכות גדולות יש לשמוע,\u0006 ללמוד \u0005מאותם המקראות]\u0006 של תפילת \u0003חנה.\u0004 שכך נאמר בה: \"וחנה היא מדברת על לבה רק שפתיה נעות וקולה לא ישמע ויחשבה עלי לשיכורה\" (שמואל א, א, יג). ומפרטים: מן האמור \u0003\"וחנה היא מדברת על לבה\"\u0004 — \u0003מכאן\u0004 הוראה \u0003למתפלל\u0004 ש\u0003צריך שיכוין לבו\u0004 בתפילתו. ומן האמור \u0003\"רק שפתיה נעות\"\u0004 — \u0003מכאן\u0004 הוראה \u0003למתפלל\u0004 שצריך \u0003שיחתוך בשפתיו,\u0004 כלומר, יבטא בשפתיו ולא רק בלבו את דברי התפילה. ומן הכתוב \u0003\"וקולה לא ישמע\"\u0004 — \u0003מכאן\u0004 למתפלל \u0003שאסור להגביה קולו בתפלתו,\u0004 אלא התפילה צריכה להיות בלחש. מהמשך הדברים \u0003\"ויחשבה עלי לשכרה\"\u0004 — יש ללמוד \u0003מכאן ששכור אסור להתפלל,\u0004 ולכן גער בה.","ועוד בענין זה של גערת עלי בחנה, כאמור \u0003\"ויאמר אליה עלי עד מתי תשתכרין\u0004 הסירי את יינך מעליך\u0003\"\u0004 (שם, שם, יד), \u0003אמר ר' אלעזר: מכאן, לרואה בחברו\u0004"],["\u0003דבר שאינו הגון\u0004 לפי דעתו, \u0003צריך להוכיחו\u0004 על כך. \u0003\"ותען חנה ותאמר לא אדוני\u0004 אשה קשת רוח אנוכי ויין ושכר לא שתיתי ואשפוך את נפשי לפני ה'\u0003\"\u0004 (שם, שם, טו). על המילים \"לא אדוני\" \u0003אמר עולא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוסי בר' חנינא שכך אמרה ליה\u0004 \u0005[לו]\u0006 ברמז: \u0003לא אדון אתה בדבר זה, ולא רוח הקודש שורה עליך\u0004 בדבר, \u0003ש\u0004כן \u0003אתה חושדני בדבר זה\u0004 שאין בי.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים,\u0006 גירסה אחרת\u0005],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 בדרך שאלה: וכי \u0003לא אדון אתה, לאו איכא\u0004 \u0005[האם אין]\u0006 \u0003שכינה ורוח הקודש גבך\u0004 \u0005[אצלך]?\u0006 \u0003שדנתני לכף חובה, ולא דנתני לכף זכות. מי לא ידעת\u0004 \u0005[האם אינך יודע]\u0006 ש\u0003אשה קשת רוח אנוכי.\u0004","מדברי ההתנצלות של חנה המודיעה \u0003\"ויין ושכר לא שתיתי\" אמר ר' אלעזר: מכאן לנחשד בדבר שאין בו, שצריך להודיעו\u0004 לחושדו שנקי הוא מאשמה, ולא להסתפק בכך שהוא עצמו יודע זאת.","\u0003\"אל תתן את אמתך לפני בת בליעל\u0004 כי מרוב שיחי וכעסי דברתי עד הנה\u0003\"\u0004 (שם, טז). מן הביטוי הקשה \"בת בליעל\" \u0003אמר ר' אלעזר: מכאן לשכור שמתפלל, כאילו עובד עבודה זרה.\u0004 שהרי \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בדברי חנה הנחשדת בתפילה מתוך שיכרות \u0003\"\u0004אל תתן את אמתך \u0003לפני בת בליעל\"\u0004 שהצטדקה חנה שאין היא בכלל \"בת בליעל\", \u0003וכתיב התם\u0004 \u0005[ונאמר שם],\u0006 בעיר הנידחת לעבודה זרה: \"יצאו אנשים בני בליעל מקרבך וידיחו את יושבי עירם לאמור נלכה ונעבדה אלוהים אחרים אשר לא ידעתם\u0003\"\u0004 (דברים יג, יד), ומהשוואת הכתובים יש ללמוד: \u0003מה להלן\u0004 \u0005[הלאה,\u0006 שם, במקרא בעיר הנידחת\u0005]\u0006 \"בליעל\" משמעו עובד \u0003עבודה זרה, אף כאן\u0004 (בתפילת שיכור) משמעו של ביטוי זה הריהו עובד \u0003עבודה זרה. מהמשך הדברים שנאמר\u0004","\u0003\"ויען עלי ויאמר לכי לשלום\"\u0004 (שם, יז), \u0003אמר ר' אלעזר: מכאן לחושד את חברו בדבר שאין בו, שצריך לפייסו. ולא עוד, אלא שצריך\u0004 הוא אף \u0003לברכו. ש\u0004כן \u0003נאמר\u0004 בהמשך דברי עלי לחנה: \u0003\"ואלהי ישראל יתן את שלתך\u0004 אשר שאלת מעמו\u0003\"\u0004 (שם), שהוסיף ובירכה.","ואגב הלימוד מתפילת חנה מבררים דברים אחרים בנושא זה. בדברי תפילתה נאמר \u0003\"ותדר נדר ותאמר ה' צבאות\u0004 אם ראה תראה בעני אמתך וזכרתני ולא תשכח את אמתך ונתת לאמתך זרע ונתתיו לה' כל ימי חייו ומורא לא יעלה על ראשו\u0003\"\u0004 (שם, יא). על כך \u0003אמר ר' אלעזר: מיום שברא הקדוש ברוך הוא את עולמו, לא היה אדם שקראו להקדוש ברוך הוא \"צבאות\", עד שבאתה חנה וקראתו \"צבאות\",\u0004 שכן זוהי הפעם הראשונה במקרא שמכנים את הקדוש ברוך הוא כך.","והסביר שכך \u0003אמרה חנה לפני הקדוש ברוך הוא: רבונו של עולם,\u0004 הלא אתה אדון הצבאות, ו\u0003מכל צבאי צבאות\u0004 ברואים \u0003שבראת בעולמך קשה בעיניך שתתן לי בן אחד?\u0004","\u0003משל למה הדבר דומה\u0004 — \u0003למלך בשר ודם שעשה סעודה לעבדיו. בא עני אחד ועמד על הפתח, אמר להם: תנו לי פרוסה אחת! ולא השגיחו עליו. דחק ונכנס אצל המלך. אמר לו: אדוני המלך, מכל סעודה שעשית קשה בעיניך ליתן לי פרוסה אחת?!\u0004","על כפילות המלים \u0003\"אם ראה תראה\" אמר ר' אלעזר\u0004 שכך \u0003אמרה חנה ל פני הקדוש ברוך הוא: רבונו של עולם, אם \"ראה\"\u0004 עכשיו — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — בכל אופן \u0003\"תראה\",\u0004 כיצד?","— ש\u0003אלך ואסתתר בפני אלקנה בעלי\u0004 עם גבר, \u0003וכיון דמסתתרנא\u0004 \u0005[שאסתתר]\u0006 \u0003משקו לי\u0004 \u0005[ישקו אותי]\u0006 \u0003מי סוטה,\u0004 לבודקני אם זניתי, ומאחר שאהיה נקיה מעוון, \u0003ו\u0004הרי \u0003אי\u0004 (אין) \u0003אתה עושה\u0004 את \u0003תורתך פלסתר\u0004 \u0005[שקר, זיוף],\u0006 \u0003ש\u0004כך \u0003נאמר\u0004 בתורה בהאשה הנחשדת לחינם בזנות ושתתה את מי הסוטה \u0003\"\u0004ואם לא נטמאה האשה וטהורה היא \u0003ונקתה ונזרעה זרע\"\u0004 (במדבר ה, כח), ועל ידי כך בהכרח שיהיו לה בנים. ואולם דברים אלה שאמר ר' אלעזר קשורים במחלוקת תנאים בפירושו של פסוק זה בהלכות סוטה.","\u0003הניחא למאן דאמר\u0004 \u0005[זה נוח, ל\u0006שיטת \u0005מי שאומר]\u0006 שפירוש הפסוק הוא: \u0003אם היתה עקרה\u0004 — \u0003נפקדת\u0004 בבנים \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[\u0006לשיטת \u0005מי שאומר]\u0006 שפירוש הפסוק הוא רק הבטחה לאשה שנחשדה לחינם שלידתה תהיה קלה ומוצלחת יותר, כגון ש\u0003אם היתה יולדת בצער\u0004 תהא מעכשיו \u0003יולדת בריוח\u0004 (בקלות), או אם עד אז היתה יולדת \u0003נקבות\u0004 (בנות) תהא מעתה \u0003יולדת זכרים\u0004 (בנים) או אם ילדה ילדים \u0003שחורים\u0004 (הנחשבים ללא יפים) תהא מעכשיו \u0003יולדת לבנים, או אם ילדה עד אז ילדים קצרים\u0004 (נמוכים וחלשים) תהא מעכשיו \u0003יולדת ארוכים\u0004 (גבוהים וחזקים), \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 שנחלקו תנאים בפירושו של האמור בסוטה: \u0003\"ונקתה ונזרעה זרע\"\u0004 — \u0003מלמד, שאם היתה עקרה\u0004 — \u0003נפקדת,\u0004 אלו \u0003דברי ר' ישמעאל. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' עקיבא: אם כן, ילכו כל העקרות כולן ויסתתרו\u0004 עם גבר זר, \u0003וזו\u0004 האשה \u0003שלא קלקלה\u0004 בזנות — \u0003נפקדת\u0004 בבנים. \u0003אלא מלמד\u0004 שאין זו אלא הבטחה על הקלת הלידה, וכגון \u0003שאם היתה יולדת בצער\u0004 — \u0003יולדת בריוח, קצרים\u0004 — \u0003יולדת ארוכים, שחורים\u0004 — \u0003יולדת לבנים, אחד\u0004 — \u0003יולדת שנים. \u0004","ולשיטה זו של ר' עקיבא, \u0003מאי\u0004 \u0005[מה]\u0006 טעם לכפילות הלשון שאמרה חנה בתפילתה \u0003\"ראה תראה\"\u0004 — \u0003דברה תורה כלשון בני אדם,\u0004 שאין זה בא ללמד דבר, אלא שכך הוא דרך לשון הכתובים.","בתוך דברי התפילה—הנדר אומרת חנה שלוש פעמים לשון \"אמתך\": \u0003\"בעני אמתך... אל תשכח את אמתך... ונתתה לאמתך\"\u0004 (שמואל א א, יא).","ועל כך \u0003אמר ר' יוסי בר' חנינא: שלש אמתות הללו למה\u0004 הם באים? — ללמד שכך \u0003אמרה חנה לפני הקדוש ברוך הוא: רבונו של עולם, שלשה בדקי מיתה\u0004 (מקומות מסוכנים, רופפים, העלולים לגרום למיתה) \u0003בראת באשה, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005האומרים אותה]\u0006 שמועה בגירסה אחרת: \u0003שלשה דבקי מיתה\u0004 (דברים המקרבים את המיתה. \u0005תרי\"ח\u0006), שהן מצוות שבדרך כלל שייכות לנשים, \u0003ואלו הן:\u0004 שמירה על דיני \u0003נדה, ו\u0004הפרשת \u0003חלה\u0004 מן העיסה, \u0003והדלקת הנר\u0004 של שבת. ואני \u0003כלום עברתי על אחת מהן?!\u0004 וחנה מעידה על היותה אמה לה' בשלושת הדברים הללו, הגורמים למיתה, עם שיש בדברים התייחסות לזיקת המלים \"אמתך\" — מיתה.","ועוד בהמשך תפילתה אומרת חנה: \u0003\"ונתת לאמתך זרע אנשים\".\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש ביטוי זה \u0003\"זרע אנשים\"? אמר רב: גברא בגוברין\u0004 \u0005[גבר בגברים],\u0006 שהתפללה חנה לבן שיהיה בולט ומיוחד. \u0003ו\u0004אילו \u0003שמואל אמר\u0004 בפירוש ביטוי זה: \u0003זרע שמושח\u0004 למלוכה \u0003שני אנשים, ומאן אינון\u0004 \u0005[ומי הם\u0006 שני אלה\u0005]\u0006 — \u0003שאול ודוד. ור' יוחנן אמר\u0004 בפירוש הביטוי, שביקשה חנה \u0003זרע\u0004 שיוולד לה בן \u0003ש\u0004יהיה \u0003שקול כשני אנשים,\u0004 גדולי עולם, \u0003ומאן אינון\u0004 \u0005[ומי הם\u0006 שני אלה\u0005]\u0006 — \u0003משה ואהרן. ש\u0004כן \u0003נאמר: \"משה ואהרן בכהניו ושמואל בקוראי שמו\"\u0004 (תהלים צט, ו), הרי ששקל הכתוב את שמואל בן חנה כמשה ואהרן. \u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים]\u0006 אומרים בפירושו של ביטוי זה \u0003\"זרע אנשים\"\u0004 — שכך ביקשה חנה, שיהיה לה \u0003זרע שמובלע בין אנשים,\u0004 שאינו יוצא דופן בדבר מן הדברים, ואינו מתבלט בהיותו בין הבריות.","ומוסרים, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, אמר בפירוש הדברים, שכך אמרה חנה בתפילתה שלא יהיה ניכר בנה בהיותו בין האנשים, וכיצד? שיהיה \u0003לא ארוך\u0004 מדי \u0003ולא גוץ\u0004 (נמוך), \u0003ולא קטן ולא אלם\u0004 (גדול ומגושם), ו\u0003לא צחור\u0004 (לבן ביותר) \u0003ולא גיחור\u0004 (אדום ביותר), \u0003ו\u0004אף \u0003לא חכם\u0004 ביותר \u0003ולא טפש\u0004 ביותר.","כשבאה חנה עם בנה שמואל למקדש שילה מודיעה היא לעלי: \u0003\"ותאמר בי אדוני חי נפשך אדוני, אני האשה הנצבת עמכה בזה להתפלל אל ה'\"\u0004 (שמואל א, א, כו). ועל כך \u0003אמר ר' יהושע בן לוי: מכאן\u0004 יש ללמוד לענין תפילה, \u0003שאסור לישב\u0004 (לשבת) \u0003בתוך ארבע אמות של תפלה\u0004 של המתפלל. שכן \"הנצבת עמך\" משמעו שאף עלי היה כמוה בעמידה, משום שהיא התפללה אז.","ועוד בענין חנה, ההדגשה שבדברי חנה אל עלי \u0003\"אל הנער הזה התפללתי\"\u0004 (שם, כז) מורה שבאה לגונן עליו מפני סכנה. שכך \u0003אמר ר' אלעזר: שמואל מורה הלכה לפני רבו היה,\u0004 ורצתה חנה לבקש שלא ייענש בידי שמים על עבירה זו. \u0003ש\u0004כן \u0003נאמר: \"וישחטו את הפר ויביאו את הנער אל עלי\"\u0004 (שם, כה). וסגנון הדברים בפסוק תמוה, וכי \u0003משום\u0004 ש\u0003\"וישחטו את הפר\"\u0004 לכן \u0003הביאו הנער אל עלי,\u0004 שהרי מה הקשר בין שחיטת הפר להבאת הנער לעלי?","\u0003אלא\u0004 כך היה מעשה, ש\u0003אמר להן עלי\u0004 למביאי הקרבן: \u0003קראו כהן, ליתי ולשחוט\u0004 \u0005[יבוא וישחוט,\u0006 את הקרבן\u0005].\u0006 \u0003חזנהו\u0004 \u0005[ראה אותם]\u0006 \u0003שמואל דהוו מהדרי בתר\u0004 \u0005[שהיו מחזרים אחר]\u0006 \u0003כהן למישחט\u0004 \u0005[שישחוט],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003למה לכו לאהדורי בתר\u0004 \u0005[לכם לחזר אחר]\u0006 \u0003כהן למישחט\u0004 \u0005[לשחוט]?\u0006 והרי \u0003שחיטה\u0004 אף של קרבן, שנעשתה \u0003בזר\u0004 (על ידי מי שאינו כהן) הריהי \u0003כשרה!\u0004 ועל כן \u0003אייתוהו לקמיה\u0004 \u0005[הביאוהו לפני]\u0006 \u0003עלי\u0004 לבירורם של דברים אלה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 עלי: \u0003מנא\u0004 \u0005[מנין]\u0006 \u0003לך הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 בתורה \u0003\"ושחט הכהן\",\u0004 ללמדנו שאף השחיטה צריכה להיעשות רק על ידי הכהן?! והלא \u0003\"והקריבו הכהנים\" כתיב\u0004 \u0005[נאמר],\u0006 הרי שבסדר הקרבת הקרבנות רק \u0003מ\u0004שלב ה\u0003קבלה\u0004 של דם השחיטה במזרקים, \u0003ואילך\u0004 (והלאה) בעבודות השונות של הקרבן הרי זו \u0003מצות כהונה\u0004 בלבד, \u0003מכאן\u0004 הלכה \u0003לשחיטה שכשרה בזר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 עלי לשמואל: \u0003מימר שפיר קא אמרת\u0004 \u0005[\u0006מה ש\u0005נאמר, יפה אמרת],\u0006 ודבריך נכונים מצד עצמם, אולם \u0003מיהו\u0004 \u0005[בכל זאת]\u0006 \u0003מורה הלכה בפני רבך את, וכל המורה הלכה בפני רבו\u0004 (אף אם הורה כדין) הריהו \u0003חייב\u0004 על כך \u0003מיתה\u0004 בידי שמים כמזלזל בכבוד רבו. ואז \u0003אתיא\u0004 \u0005[באה]\u0006 \u0003חנה וקא צווחה קמיה\u0004 \u0005[וצווחה לפניו]:\u0006 \u0003\"אני האשה הנצבת עמכה בזה\u0004 להתפלל אל ה' \u0003\".\u0004 ואל תעניש את הילד שנולד על ידי תפילתי. \u0003אמר לה: שבקי\u0004 \u0005[הניחי]\u0006 \u0003לי דאענשיה\u0004 \u0005[שאענישנו],\u0006 \u0003ובעינא רחמי\u0004 \u0005[ואבקש רחמים,\u0006 אתפלל\u0005]\u0006 עליך, \u0003ויהיב\u0004 \u0005[ויתן]\u0006 \u0003לך\u0004 הקדוש ברוך הוא בן שהוא \u0003רבא מיניה\u0004 \u0005[גדול ממנו].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003\"אל הנער הזה התפללתי\"\u0004 ואיני רוצה אחר.","ועוד עוסקים בתפילת חנה. נאמר \u0003\"וחנה היא מדברת על לבה\".\u0004 ובפירוש ביטוי זה, במקום \"אל לבה\" (מהרש\"א) נאמרו פירושים שונים: \u0003אמר ר' אלעזר משום\u0004 (בשם) \u0003ר' יוסי בן זמרא\u0004 שדברה—התפללה חנה לפני ה' \u0003על עסקי לבה.\u0004 שכך \u0003אמרה לפניו: רבונו של עולם,\u0004 הרי ב\u0003כל מה שבראת ב\u0004איבריה של ה\u0003אשה, לא בראת דבר אחד\u0004 מהם \u0003לבטלה,\u0004 וכל איבר ואיבר ממלא את תפקידו. וכגון: \u0003עינים לראות, ואזנים לשמוע, חוטם להריח, פה לדבר, ידים לעשות בהם מלאכה, רגלים להלך בהן, דדים\u0004 (שדיים) להניק בהן. ואם כן \u0003דדים הללו שנתת על לבי, למה\u0004 (לשם מה)? האם \u0003לא\u0004 על מנת \u0003להניק בהן?! תן לי בן, ואניק בהן.\u0004 ובדרך אגב מביאים עוד מה ש\u0003אמר\u0004","\u0003ר' אלעזר משום ר' יוסי בן זמרא: כל היושב\u0004 (כל שנותיו) \u0003בתענית בשבת\u0004 גדולה זכותו ו\u0003קורעים לו גזר דינו של שבעים שנה,\u0004 שקשה התענית בשבת כשהכל מתענגים בה, והכל מוכן לסעודה, יותר מבכל יום אחר. \u0003ואף על פי כן חוזרין ונפרעין\u0004 מן הצם \u0003דין עונג שבת\u0004 שלא קיים.","על כך שאלו: \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 אם צם? על כך ענו: \u0003אמר רב נחמן בר יצחק, ליתיב תעניתא לתעניתא\u0004 \u0005[ישב בתענית על תעניתו]\u0006 ויצום באחד מימי השבוע לכפרה על שלא עינג את השבת כראוי.","\u0003ו\u0004מכיון שהוסבר כאן הביטוי הנדיר \"על לבה\" מובא עוד מה ש\u0003אמר ר' אלעזר\u0004 בעניינה של חנה: \u0003חנה הטיחה דברים כלפי מעלה,\u0004 כלומר, זרקה דברים, בתקיפות, כלפי ה'. \u0003ש\u0004כן \u0003נאמר: \"ותתפלל על ה'\"\u0004 — \u0003מלמד, שהטיחה דברים כלפי מעלה. ו\u0004בענין זה של הטחת דברים כלפי מעלה,","\u0003אמר ר' אלעזר\u0004 שאף \u0003אליהו הטיח דברים כלפי מעלה\u0004 בתפילתו, בהר הכרמל, \u0003ש\u0004כן \u0003נאמר: \"\u0004ענני ה' ענני וידעו העם הזה כי אתה ה' האלוהים \u0003ואתה הסבת את לבם אחרנית\"\u0004 (מלכים א יח, לז), כטוען כי ה' הוא שגרם לישראל לחטוא. ועל כך \u0003אמר ר' שמואל בר ר' יצחק: מנין שחזר הקדוש ברוך הוא והודה לו לאליהו\u0004 שהוא צודק,"],["\u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 בנבואה לעתיד: \u0003\"\u0004ביום ההוא נאם ה' אוספה הצולעה והנדחה אקבצה \u0003ואשר הרעתי\"\u0004 (מיכה ד, ו), שה' אומר שהוא גרם לישראל שירעו מעשיהם.","ומעין זה \u0003אמר ר' חמא בר' חנינא: אלמלא שלש מקראות הללו\u0004 (הבאים) \u0003נתמוטטו רגליהם של שונאי ישראל\u0004 (כינוי בלשון נקיה לעם ישראל), שלולא הכתוב בהם לא יכלו ישראל לעמוד בדינו של ה'.","\u0003חד\u0004 \u0005[האחד]\u0006 הוא פסוק זה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו \u0003\"ואשר הרעתי\", וחד\u0004 \u0005[ואחד]\u0006 נוסף הוא פסוק זה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"הנה כחמר ביד היוצר כן אתם בידי בית ישראל\"\u0004 (ירמיהו יח, ו), \u0003וחד\u0004 \u0005[ו\u0006עוד \u0005אחד]\u0006 הוא זה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \"ונתתי לכם לב חדש ורוח חדשה אתן בקרבכם \u0003והסרתי את לב האבן מבשרכם ונתתי לכם לב בשר\"\u0004 (יחזקאל לו, כו). שמשלושת המקראות הללו אנו למדים שביכולת ה' להשפיע גם על בחירתו של האדם, ולכן אין לו אחריות גמורה למעשיו.","\u0003רב פפא אמר\u0004 שיש ראיה ברורה יותר, \u0003מהכא\u0004 \u0005[מכאן ]\u0006 מן הפסוק \u0003\"ואת רוחי אתן בקרבכם ועשיתי את אשר בחקי תלכו\u0004 ומשפטי תשמרו ועשיתם\u0003\"\u0004 (שם, כז).","\u0003ו\u0004המשיך ו\u0003אמר ר' אלעזר:\u0004 אף \u0003משה הטיח דברים כלפי מעלה. ש\u0004כן \u0003נאמר\u0004 בכתוב בעקבות חטא המתאוננים במדבר: \u0003\"ויתפלל משה אל ה'\u0004 ותשקע האש\u0003\"\u0004 (במדבר יא, ב). ומדרש כתוב זה: \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 בו \u0003\"אל ה'\"\u0004 אלא \u0003\"על ה'\"\u0004 והרי זו לשון של הטחת דברים.","ומסבירים מה טעם לחילוף זה של האותיות א' וע' שביסוד דרשה זו: \u0003שכן\u0004 במדרשי הלכה רבים היו החכמים \u0003דבי\u0004 \u0005[של בית\u0006 המדרש] של \u0003ר' אליעזר בן יעקב קורין\u0004 (קוראים) בחילוף \u0003לאלפי\"ן עייני\"ן, ולעייני\"ן אלפי\"ן.\u0004","ואילו החכמים \u0003דבי\u0004 \u0005[של בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ינאי אמרי\u0004 \u0005[היו אומרים ,\u0006 מביאים ראיה מהכתוב שהטיח משה דברים \u0003מהכא\u0004 \u0005[מכאן],\u0006 מהאמור בתוכחתו של משה בתחילת ספר דברים: \u0003\"ודי זהב\"\u0004 (דברים א, א), ומכיון שאין מקום הידוע בשם זה, אין זה אלא כרומז לדבר אחר, ויש לברר:","\u0003מאי\u0004 \u0005[מה]\u0006 עניינו של כתוב זה \u0003\"ודי זהב\"?\u0004 ובפירוש זה \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי, ש\u0004כך \u0003אמר משה לפני הקדוש ברוך הוא\u0004 לאחר חטא העגל, בתפילתו לכפרת עוונו זה של עם ישראל: \u0003רבונו של עולם, בשביל כסף וזהב שהשפעת להם לישראל\u0004 ביציאת מצרים ובביזת ים סוף, שכה רב היה \u0003עד שאמרו \"די\"\u0004 — עושר זה \u0003הוא\u0004 ש\u0003גרם\u0004 להם \u0003שעשו את העגל\u0004 (שעשוי היה מזהב).","וכן כהוראה מוסרית כוללת \u0003אמרי דבי\u0004 \u0005[אומרים\u0006 החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: אין ארי נוהם מתוך קופה\u0004 (סל) \u0003של תבן\u0004 שאינו יכול להנות ממנה \u0003אלא מתוך קופה של בשר,\u0004 שלאחר ששבע יכול הוא לנהום.","וכן \u0003אמר ר' אושעיא: משל לאדם שהיתה לו פרה כחושה ובעלת אברים\u0004 (גדולה), לאחר זמן \u0003האכילה כרשינין\u0004 (שהם מאכל מובחר) \u0003והיתה\u0004 הפרה \u0003מבעטת בו. אמר לה: מי גרם ליך\u0004 \u0005[לך]\u0006 \u0003שתהא מבעטת בי\u0004 — \u0003אלא כרשינין שהאכלתיך.\u0004 ואף כאן הגורם לחטא היה רוב טובה.","ומשל אחר לענין זה \u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: משל לאדם שהיה לו בן. הרחיצו וסכו, והאכילו והשקהו, ותלה לו כיס\u0004 (ארנק ובו כסף) \u0003על צוארו. ו\u0004לאחר כל זאת, עוד \u0003הושיבו על פתח של\u0004 בית שמצויות בו \u0003זונות. מה יעשה\u0004 (כיצד יימנע) \u0003אותו הבן שלא יחטא?!\u0004","ובאותו ענין \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא\u0004 שכך \u0003אמר רב ששת: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים בני אדם,\u0006 כפיתגם עממי\u0005]:\u0006 \u0003מלי כרסיה זני בישי\u0004 \u0005[מילוי כרסו\u0006 הוא \u0005ממיני החטא].\u0006 \u0003ש\u0004כן \u0003נאמר\u0004 בלשון הכתובים: \u0003\"כמרעיתם וישבעו שבעו וירם לבם על כן שכחוני\"\u0004 (הושע יג, ו). \u0003רב נחמן אמר: מהכא\u0004 \u0005[מכאן,\u0006 מכתוב זה\u0005]\u0006 נלמד הדבר: \u0003\"ורם לבבך ושכחת את ה'\"\u0004 (דברים ח, יד). \u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים],\u0006 \u0003מהכא\u0004 \u0005[מכאן,\u0006 מכתוב זה\u0005]\u0006 נלמד הדבר: \u0003\"ואכל ושבע ודשן ופנה\u0004 אל אלהים אחרים\u0003\"\u0004(שם לא, כ).","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי נלמד רעיון זה \u0003מהכא\u0004 \u0005[מכאן,\u0006 מכתוב זה\u0005]:\u0006 \u0003\"וישמן ישורון ויבעט\"\u0004 (שם לב, טו). \u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: מנין\u0004 למדים אנו בכתובים שאף \u0003חזר הקדוש ברוך הוא והודה לו למשה\u0004 שאכן סיבתו של חטא העגל היא שפע הטובה לעם ישראל, \u0003ש\u0004כן \u0003נאמר: \"וכסף הרביתי להם וזהב עשו לבעל\"\u0004 (הושע ב, י).","ומשום הזכרת חטא העגל באים לברר דברים נוספים בנושא זה. נאמר \u0003\"וידבר ה' אל משה לך רד\u0004 כי שחת עמך אשר העלית מארץ מצרים\u0003\"\u0004 (שמות לב, ז). \u0003מאי\u0004 \u0005[מה\u0006 פירושו] של \u0003\"לך רד\"? אמר ר' אלעזר:\u0004 כוונת הדברים היא, שכך \u0003אמר לו הקדוש ברוך הוא למשה: משה, רד מגדולתך! כלום נתתי לך גדולה אלא בשביל ישראל,\u0004 שגדולת משה ניתנה לו לשמש שליח לישראל. \u0003ועכשיו\u0004 ש\u0003ישראל חטאו\u0004 — \u0003אתה למה לי?\u0004 שאם חטא העם, אין משמעות עוד לשליחותו. \u0003מיד תשש כוחו של משה, ולא היה לו כח לדבר\u0004 להצדיק את ישראל. \u0003ו\u0004אולם \u0003כיון שאמר\u0004 לו הקדוש ברוך הוא למשה לאחר מכן \u0003\"הרף ממני ואשמידם\"\u0004 (דברים ט, יד), \u0003אמר משה\u0004 לעצמו: אם הקדוש ברוך הוא מבקש ממני שארפה ממנו, הרי ש\u0003דבר זה תלוי בי! מיד עמד ונתחזק בתפלה, ובקש רחמים\u0004 על עם ישראל לסליחה על עוונם.","ומשלו משל בדבר זה: \u0003משל למלך שכעס על בנו\u0004 בשל חטא שחטא הבן כלפיו, \u0003והיה מכהו מכה גדולה. והיה אוהבו\u0004 (ידידו) של המלך \u0003יושב לפניו\u0004 באותה עת, ורואה את הדברים הללו, \u0003ו\u0004אולם \u0003מתירא\u0004 היה ידידו של המלך \u0003לומר לו דבר\u0004 על המכה היתירה שהוא מכה את בנו. ותוך כדי כך \u0003אמר המלך\u0004 לבנו: \u0003אלמלא אוהבי זה שיושב לפני\u0004 — \u0003הרגתיך.\u0004 מיד כששמע כן, \u0003אמר\u0004 ידיד המלך לעצמו: אין זה אלא רמז ש\u0003דבר זה\u0004 (הצלת הבן מידי אביו) \u0003תלוי בי. מיד עמד והצילו.\u0004","ומענין זה, עוד נאמר בעקבות חטא העגל, שכך אמר הקדוש ברוך הוא למשה: \u0003\"ועתה הניחה לי ויחר אפי בהם ואכלם ואעשה אותך לגוי גדול\" וגו'\u0004 (שמות לב, י). ובפירושו של מקרא זה, \u0003אמר ר' אבהו: אלמלא מקרא כתוב\u0004 כך, \u0003אי אפשר לאומרו\u0004 מפני כבוד ה'. שכן הביטוי \"הניחה לי\" \u0003מלמד שתפסו משה להקדוש ברוך הוא, כאדם שהוא תופס את חבירו בבגדו, ואמר לפניו: רבונו של עולם, אין אני מניחך עד שתמחול ותסלח להם.\u0004 ועוד באותו כתוב.","הבטחה היא שהבטיח הקדוש ברוך הוא למשה \u0003\"ואעשה אותך לגוי גדול\" וגו'.\u0004 ומה היתה תשובתו של משה על כך? \u0003אמר ר' אלעזר: אמר משה לפני הקדוש ברוך הוא: רבונו של עולם, ומה כסא של שלש רגלים\u0004 (כלומר, זכות שלושת האבות) \u0003אינו יכול לעמוד לפניך בשעת כעסך. כסא של רגל אחת\u0004 (כלומר, שיעמוד רק בזכותי בלבד) — \u0003על אחת כמה וכמה\u0004 שלא יוכל לעמוד כשיהיה עליו חרון אף!","\u0003ולא עוד אלא שיש בי בושת פנים מאבותי\u0004 (שלושת האבות), \u0003עכשיו יאמרו: ראו פרנס\u0004 זה \u0003שהעמיד עליהם\u0004 (על עם ישראל). \u0003בקש גדולה לעצמו, ולא בקש עליהם רחמים\u0004 בשעת צרתם, מפני שרצה את גדולת הבחירה לעצמו ולצאצאיו.","עוד נאמר \u0003\"ויחל משה את פני ה'\"\u0004 (שם לב, יא). על ביטוי זה, שאינו מצוי, \"ויחל\" נאמרו פירושים רבים (מהרש\"א): \u0003אמר ר' אלעזר\u0004 שהדבר \u0003מלמד שעמד משה בתפלה לפני הקדוש ברוך הוא, עד שהחלהו,\u0004 שחלה מרוב מאמץ. \u0003ורבא אמר:\u0004 עמד משה בתפילה \u0003עד שהפר לו נדרו,\u0004 ש\"ויחל\" רומז להפרת נדר. שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן,\u0006 בתפילת משה\u0005]:\u0006 \u0003\"ויחל\", וכתיב התם\u0004 \u0005[ונאמר שם,\u0006 בדין הנדרים\u0005]:\u0006 \u0003\"לא יחל דברו\"\u0004 (במדבר ל, ג), \u0003ואמר מר\u0004 \u0005[החכם]\u0006 בדין זה שבנדרים: \u0003הוא\u0004 הנודר עצמו \u0003אינו מיחל\u0004 את נדרו, \u0003אבל אחרים\u0004 (בית דין) \u0003מחלין לו,\u0004 מותר להם להפר את נדרו. וכאן כאילו הפר משה להקדוש ברוך הוא את נדרו להשמיד את ישראל.","\u0003ושמואל אמר\u0004 בפירוש לשון \"ויחל\": \u0003מלמד שמסר\u0004 משה את \u0003עצמו למיתה\u0004 (להיות חלל) \u0003עליהם\u0004 (על בני ישראל). \u0003ש\u0004כן \u0003נאמר: \"ואם אין מחני נא מספרך\"\u0004 (שמות לב, לב).","ועוד בפירוש מקרא זה \u0003אמר רבא\u0004 שכך \u0003אמר רב יצחק: מלמד\u0004 כתוב זה \"ויחל\" \u0003שהחלה\u0004 (שתחול) \u0003עליהם מדת\u0004 ה\u0003רחמים.\u0004","\u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים]\u0006 בפירוש הלשון \"ויחל\", שהוא תמצית נימוקו של משה: \u0003מלמד ש\u0004כך \u0003אמר משה לפני הקדוש ברוך הוא: רבונו של עולם\u0004!\u0003 חולין\u0004 (חילול שמך) \u0003הוא לך מעשות כדבר הזה.\u0004","ועוד בפירוש מקרא זה \u0003\"ויחל משה את פני ה'\" תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר: מלמד\u0004 ביטוי זה \u0003שעמד משה בתפלה לפני הקדוש ברוך הוא עד שאחזתו אחילו.\u0004 על כך שואלים: \u0003מאי\u0004 \u0005[מהו,\u0006 פירוש\u0005]\u0006 \u0003אחילו?\u0004 כי מלה זו נשתכח פירושה אף מפי החכמים. \u0003אמר ר' אלעזר\u0004 מאמוראי ארץ ישראל שהכוונה היא ל\u0003אש של עצמות.\u0004 ואולם ביטוי זה, שמובן היה בארץ ישראל, לא היה מובן בבבל. ולכן שאלו: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אש עצמות? אמר אביי\u0004 שהכוונה היא למחלה הנקראת בבבל \u0003אשתא דגרמי,\u0004 כלומר, קדחת.","בהמשך תפלת משה אומר הוא: \u0003\"זכר לאברהם ליצחק ולישראל עבדיך אשר נשבעת להם בך\"\u0004 (שמות לב, יג). \u0003מאי\u0004 \u0005[מה]\u0006 \u0003\"בך\"? אמר ר' אלעזר,\u0004 כך \u0003אמר משה לפני הקדוש ברוך הוא: רבונו של עולם, אלמלא נשבעת להם בשמים ובארץ, הייתי אומר: כשם ששמים וארץ בטלים\u0004 — \u0003כך שבועתך בטלה. ועכשו שנשבעת להם בשמך הגדול, מה שמך הגדול חי וקיים לעולם ולעולמי עולמים\u0004 — \u0003כך שבועתך קיימת לעולם ולעולמי עולמים.\u0004 והרי זו שבועה שאין לה ביטול.","בפסוק זה ממשיך משה ואומר: \u0003\"ותדבר אליהם ארבה את זרעכם ככוכבי השמים וכל הארץ הזאת אשר אמרתי\u0004 אתן לזרעכם ונחלו לעולם \u0003\".\u0004 בפסוק מבחינים בביטוי תמוה, \u0003האי\u0004 \u0005[ביטוי זה]\u0006 \u0003\"אשר אמרתי\"\u0004 למה נאמר, והלא \u0003\"אשר אמרת\" מיבעי ליה\u0004 \u0005[צריך היה לו,\u0006 לומר\u0005]!\u0006 שהרי משה מדבר בפסוק זה על הבטחת ה' לאבות.","\u0003אמר ר' אלעזר: עד כאן\u0004 בפסוק \u0003הוא דברי תלמיד\u0004 (כינוי למשה), \u0003מכאן ואילך,\u0004 מ\"וכל הארץ אשר אמרתי\" — \u0003דברי הרב\u0004 (כינוי לקב\"ה). \u0003ו\u0004אילו \u0003ר' שמואל בר נחמני אמר\u0004 כי \u0003אלו ואלו דברי תלמיד,\u0004 שכל הפסוק הוא מדברי משה, \u0003אלא כך אמר משה לפני הקדוש ברוך הוא: רבונו של עולם, דברים שאמרת לי \"לך אמור להם לישראל\" בשמי, הלכתי ואמרתי להם בשמך,\u0004 שכוונתו כך: את דברי הבטחת ה' לאבות כבר אמרתי אני לישראל. \u0003עכשו מה אני אומר להם?\u0004 מדברי תפילה אלה של משה באים לדון גם דבר בתפילותיו האחרות.","משה אומר שאם לא יביא ה' את ישראל לארץ יאמרו אומות העולם: \u0003\"מבלתי יכלת ה'\u0004 להביא את העם הזה אל הארץ אשר נשבע להם וישחטם במדבר\" (במדבר יד, טז). ויש לדייק בכתוב: לא היה צריך הכתוב לומר \"יכולת\" כשם עצם מופשט, כי אם כפועל \u0003\"\u0004מבלתי \u0003יכול ה'\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 ובלשון זכר ושלא בלשון נקיבה.","אלא \u0003אמר ר' אלעזר:\u0004 שכך \u0003אמר משה לפני הקדוש ברוך הוא: רבונו של עולם, עכשיו יאמרו אומות העולם\u0004 על הקדוש ברוך הוא ש\u0003תשש כחו כנקבה, ואינו יכול להציל\u0004 את עם ישראל, ולכן נאמר בלשון נקיבה. על כך \u0003אמר הקדוש ברוך הוא למשה: והלא כבר ראו\u0004 אומות העולם \u0003נסים וגבורות שעשיתי להם\u0004 לבני ישראל \u0003על הים\u0004 (בקריעת ים סוף). \u0003אמר לפניו: רבונו של עולם, עדיין יש להם לומר: למלך אחד\u0004 כגון פרעה מלך מצרים \u0003יכול\u0004 ה' \u0003לעמוד\u0004 ולנצחו, ואילו \u0003לשלשים ואחד מלכים\u0004 שבארץ כנען \u0003אינו יכול לעמוד.\u0004","\u0003אמר ר' יוחנן: מנין ש\u0004אמנם \u0003חזר הקדוש ברוך הוא והודה לו למשה, ש\u0004כן \u0003נאמר: \"ויאמר ה' סלחתי כדבריך\"\u0004 (שם, כ). ובפירוש המלה \"כדבריך\" \u0003תני\u0004 \u0005[שנו]\u0006 החכמים \u0003דבי\u0004 \u0005[של בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל: כדבריך\u0004 כן הוא, שבאמת \u0003עתידים\u0004 היו \u0003אומות העולם לומר כן.\u0004","ומסכמים: \u0003אשרי תלמיד שרבו מודה לו\u0004 כמו שהודה ה' לטענת משה.","ובפירוש המשך הדברים \u0003\"ואולם חי אני\u0004 וימלא כבוד ה' את כל הארץ\u0003\"\u0004 (שם, כא), \u0003אמר רבא\u0004 שכך \u0003אמר רב יצחק: מלמד\u0004 מקרא זה \u0003שאמר לו הקדוש ברוך הוא למשה: משה, החייתני בדבריך,\u0004 כלומר, שמח אני שעל ידי נימוקיך אני סולח לישראל.","ומתפילות משה \u0003דרש ר' שמלאי: לעולם יסדר אדם שבחו של הקדוש ברוך הוא, ואחר כך יתפלל\u0004 ויבקש את הצריך לו. \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך יש לנהוג? — \u0003ממשה, דכתיב\u0004 \u0005[שנאמר]\u0006 בתפילתו: \u0003\"ואתחנן אל ה' בעת ההיא\"\u0004 (דברים ג, כג). \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך בתפילתו זו: \u0003\"ה' אלהים אתה החלת להראות את עבדך את גדלך ואת ידך החזקה אשר מי אל בשמים ובארץ אשר יעשה כמעשיך וכגבורותיך\"\u0004 (שם כד), הרי שפתח תחילה בשבחו של מקום. \u0003וכתיב בתריה\u0004 \u0005[ו\u0006רק בפסוק \u0005אחריו נאמר]\u0006 \u0003\"אעברה נא ואראה את הארץ הטובה\u0004 אשר בעבר הירדן ההר הטוב הזה והלבנון\u0003\"\u0004 (שם, כה), שלא התפלל על רצונו קודם שסידר לפני כן שבח המקום.","\u0003סימן: מעשי\"ם, צדק\"ה, קרב\"ן, כה\"ן, תעני\"ת, מנע\"ל, ברז\"ל.\u0004"],["\u0003אמר ר' אלעזר:\u0004 מכאן למדים אנו ש\u0003גדולה תפלה יותר ממעשים טובים\u0004 בלא תפילה (תוספות), \u0003ש\u0004הרי \u0003אין לך גדול במעשים טובים יותר ממשה רבינו\u0004 שודאי אין גדול ממנו במעשיו הטובים שעשה, ו\u0003אף על פי כן לא נענה\u0004 הקדוש ברוך הוא לבקשתו להיכנס לארץ, אף במקצת, \u0003אלא בתפלה,\u0004 ואז הורשה לפחות לעלות לראש הפסגה ולראות את הארץ. \u0003ש\u0004כן \u0003נאמר\u0004 בתחילה \u0003\"אל תוסף דבר אלי\" וסמיך ליה\u0004 \u0005[וסמוך לו,\u0006 לפסוק זה\u0005]\u0006 נאמר: \u0003\"עלה ראש הפסגה\". ו\u0004מתוך השוואת התפילה למעשים טובים, עוד השוואה ש","\u0003אמר ר' אלעזר: גדולה\u0004 מעלת ה\u0003תענית יותר מן הצדקה. מאי טעמא\u0004 \u0005[ מה הטעם\u0006 לדבר\u0005]\u0006 — ש\u0003זה\u0004 (בתענית) הריהי מצוה הנעשית \u0003בגופו\u0004 של האדם המסתגף, \u0003ו\u0004אילו \u0003זה\u0004 (בצדקה) הריהי נעשית רק \u0003בממונו. \u0004","ועוד השוואה ש\u0003אמר ר' אלעזר: גדולה תפלה יותר מן הקרבנות, ש\u0004כן \u0003נאמר\u0004 לישראל: \u0003\"למה לי רב זבחיכם\u0004 יאמר ה' שבעתי עולות אילים וחלב מריאים ודם פרים וכבשים ועתודים לא חפצתי\u0003\"\u0004 (ישעיהו א, יא), \u0003ו\u0004בנוסף לזה \u0003כתיב\u0004 \u0005[נאמר]\u0006 אחר כך: \u0003\"ובפרשכם כפיכם\u0004 אעלים עיני מכם גם כי תרבו תפילה אינני שומע, ידיכם דמים מלאו\u0003\"\u0004(שם טו), שאף תפילתם שגדולה מעלתה משל הקרבנות אינה מתקבלת.","ואגב הזכרת מקרא זה מובא מה ש\u0003אמר ר' יוחנן: כל כהן שהרג את הנפש\u0004 — \u0003לא ישא את כפיו\u0004 בברכת כהנים, \u0003ש\u0004כן \u0003נאמר\u0004 במקרא זה: \"ובפרשכם כפיכם אעלים עיני... \u0003ידיכם דמים מלאו\",\u0004 הרי שברכת כהנים (הנעשית בפרישת כפים) אינה מתקבלת כאשר ידי הכהנים \"דמים מלאו\".","\u0003ו\u0004עוד \u0003אמר ר' אלעזר\u0004 בענין התפילה: \u0003מיום שחרב בית המקדש ננעלו שערי תפלה\u0004 ואינה מתקבלת כמקודם, \u0003ש\u0004כן \u0003נאמר\u0004 בדברי הקינה על החורבן: \u0003\"גם כי אזעק ואשוע שתם תפלתי\"\u0004 (איכה ג, ח). \u0003ו\u0004אולם \u0003אף על פי ששערי תפילה ננעלו\u0004 עם החורבן, \u0003שערי דמעה לא ננעלו,\u0004 והבוכה לפני ה' מובטח לו שתשמע תפילתו, \u0003ש\u0004כן \u0003נאמר: \"שמעה תפלתי ה' ושועתי האזינה אל דמעתי אל תחרש\"\u0004 (תהלים לט,יג), שמכיון שאין התפילה אלא שישים ה' לב אל דמעת המתפלל נראה שודאי הוא לו שעל כל פנים שערי דמעותיו לא ננעלו.","ובענין נעילת שערי תפילה, מסופר כי \u0003רבא לא גזר תעניתא ביומא דעיבא\u0004 \u0005[תענית ביום מעונן],\u0006 \u0003משום שנאמר \"סכתה בענן לך מעבור תפלה\"\u0004 (איכה ג, מד), הרי שקבע הכתוב דבר זה כסימן רע של הסתרת פנים (רה\"ג).","\u0003ו\u0004עוד \u0003אמר ר' אלעזר: מיום שחרב בית המקדש נפסקה\u0004 (חוצצת) \u0003חומת ברזל בין ישראל לאביהם שבשמים, ש\u0004כן \u0003נאמר\u0004 לנביא יחזקאל לעשות מעשה כסמל לדבר זה: \u0003\"ואתה קח לך מחבת ברזל ונתת אותה קיר ברזל בינך ובין העיר...\u0004 אות היא לבית ישראל\u0003\"\u0004 (יחזקאל ד, ג).","דברים אחרים בשבח התפילה \u0003אמר ר' חנין\u0004 שכך \u0003אמר ר' חנינא: כל המאריך בתפלתו,\u0004 מובטח לו ש\u0003אין תפלתו חוזרת ריקם\u0004 (ללא מענה), שוודאי שתתקבל. \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 דבר זה — \u0003ממשה רבינו, ש\u0004כן \u0003נאמר\u0004 שאמר משה: \u0003\"ואתפלל אל ה'\"\u0004 (דברים ט, כו), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחר כך]:\u0006 \u0003\"וישמע ה' אלי גם בפעם ההיא\u0004 לא אבה ה' השחיתך\u0003\"\u0004 (שם, י, יא).","על כך מקשים: \u0003איני\u0004 \u0005[כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: כל המאריך בתפילתו ומעיין בה\u0004 (מצפה שתתקבל) בשל ההארכה — \u0003סוף בא לידי כאב לב\u0004 כשאינו נענה, \u0003ש\u0004כן \u0003נאמר: \"תוחלת ממושכה מחלה לב\"\u0004 (משלי יג, יב). ו\u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 של החולה בחולי זה — \u0003יעסוק בתורה, ש\u0004כן \u0003נאמר: \"ועץ חיים תאוה באה\"\u0004 (שם), \u0003ואין\u0004 משמעות \u0003\"עץ חיים\" אלא תורה, ש\u0004כן \u0003נאמר: \"עץ חיים היא למחזיקים בה\u0004 ותומכיה מאושר\u0003\"\u0004 (שם ג, יח). את הסתירה מתרצים: \u0003הא\u0004 \u0005[זה]\u0006 שנאמר שבא לו כאב לב, מדובר במי ש\u0003מאריך ומעיין בה.\u0004 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' חנין בשבחו של המאריך בתפילתו הרי זה במי ש\u0003מאריך ולא מעיין בה.\u0004","ומעין זה \u0003אמר ר' חמא בר' חנינא: אם ראה אדם שהתפלל, ולא נענה\u0004 — ראוי ש\u0003יחזור ויתפלל.\u0004 וראיה לדבר, \u0003ש\u0004כן \u0003נאמר: \"קוה אל ה' חזק ויאמץ לבך וקוה אל ה'\"\u0004 (תהלים כז, יד), שיש לו לאדם לפנות אל ה' בתקוה, ולחזור ולפנות.","מתוך הדגשת הנחיצות להתחזק בתפילה, מובא עוד מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003ארבעה\u0004 דברים \u0003צריכין\u0004 תמיד \u0003חזוק,\u0004 שיתמיד בהם האדם ברוב כוח, \u0003ואלו הן: תורה, ומעשים טובים, תפלה, ודרך ארץ\u0004 (העבודה היום יומית). ולכל דבר ראיה מן הכתוב.","\u0003תורה ומעשים טובים, מנין?\u0004 — \u0003ש\u0004כן \u0003נאמר\u0004 בהוראה ליהושע: \u0003\"רק חזק ואמץ מאד לשמר ולעשות ככל התורה\u0004 אשר צווך משה עבדי אל תסור ממנו ימין ושמאל למען תשכיל בכל אשר תלך\u0003\"\u0004 (יהושע א, ז). \"לשמור\" — הוא לימוד התורה, \"לעשות\" - מעשים טובים (מהרש\"א), ועל כן הכפילות. ולמדים: \u0003\"חזק\"\u0004 — \u0003בתורה, \"ואמץ\"\u0004 — \u0003במעשים טובים.\u0004","שיש להתחזק ב\u0003תפלה מנין\u0004 — \u0003ש\u0004כן \u0003נאמר \"קוה אל ה' חזק ויאמץ לבך וקוה אל ה'\".\u0004","שיש להתחזק ב\u0003דרך ארץ מנין\u0004 — \u0003ש\u0004כן \u0003נאמר \"חזק ונתחזק בעד עמנו\u0004 ובעד ערי אלהינו\" (שמואל ב' י, יב), הרי שבכל עבודתו של אדם צריך הוא להתחזקות.","בהקשר למעשה העגל ותחינת משה למחילה שמסביב לו מובא עוד מדרש על הפסוק \u0003\"ותאמר ציון עזבני ה' וה' שכחני.\u0004 התשכח אשה עולה מרחם בן בטנה גם אלה תשכחנה ואנוכי לא אשכחך\u0003\"\u0004 (ישעיהו מט, יד–טו). ויש לברר: \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003עזובה, היינו\u0004 \u0005[זהו]\u0006 \u0003שכוחה,\u0004 שהרי לשתי המילים הללו משמעות זהה, ומה טעם לכפילות הלשון \"עזבני\", \"שכחני\" שבכתוב? \u0003אמר ריש לקיש:\u0004 כך \u0003אמרה כנסת ישראל לפני הקדוש ברוך הוא: רבונו של עולם,\u0004 אף כאשר \u0003אדם\u0004 עומד ו\u0003נושא אשה\u0004 אחרת \u0003על אשתו ראשונה,\u0004 הריהו עדיין \u0003זוכר\u0004 את \u0003מעשה\u0004 האשה \u0003הראשונה. ו\u0004אילו \u0003אתה\u0004 לא רק \u0003עזבתני\u0004 כי אם גם \u0003שכחתני.\u0004","ועל כך \u0003אמר לה הקדוש ברוך הוא: בתי, שנים עשר מזלות בראתי ברקיע, ועל כל מזל ומזל בראתי לו שלשים חיל, ועל כל חיל וחיל בראתי לו שלשים לגיון, ועל כל לגיון ולגיון בראתי לו שלשים רהטון, ועל כל רהטון ורהטון בראתי לו שלשים קרטון, ועל כל קרטון וקרטון בראתי לו שלשים גסטרא, ועל כל גסטרא וגסטרא תליתי בו שלש מאות וששים וחמשה אלפי רבוא כוכבים כנגד ימות החמה. וכולן לא בראתי אלא בשבילך, ואת אמרת \"עזבתני\" ו\"שכחתני\"?!\u0004","ובהמשך הדברים בכתוב נאמר: \u0003\"התשכח אשה עולה\u0004 מרחם פרי בטנה \u0003\",\u0004 ומשמעות הכתוב, שכך \u0003אמר הקדוש ברוך הוא\u0004 לכנסת ישראל: \u0003כלום אשכח עולות אילים ופטרי רחמים\u0004 (הבכורות) \u0003שהקרבת לפני במדבר?!\u0004 על כך \u0003אמרה לפניו\u0004 כנסת ישראל: \u0003רבונו של עולם, הואיל ואין שכחה לפני כסא כבודך\u0004 מאחר שאין שכחה לפניך, \u0003שמא לא תשכח לי\u0004 לנצח את \u0003מעשה העגל? אמר לה\u0004 הקדוש ברוך הוא: \u0003\"גם אלה תשכחנה\"\u0004 — אף מעשה העגל (המכונה \"אלה\", שכן אמרו בו בני ישראל \"אלה אלהיך ישראל\") יישכח.","חזרה כנסת ישראל ו\u0003אמרה לפניו: רבונו של עולם, הואיל ויש שכחה לפני כסא כבודך, שמא תשכח לי\u0004 גם את \u0003מעשה סיני\u0004 (קבלת תורה)? \u0003אמר לה\u0004 הקדוש ברוך הוא בתשובה לכך: \u0003\"ואנכי לא אשכחך\",\u0004 שלא אשכח את מתן תורה (שנאמר בו בראשיתו \"אנכי ה' אלהיך\")","\u0003ו\u0004מעירים: \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003אמר ר' אלעזר\u0004 שכך \u0003אמר רב אושעיא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"גם אלה תשכחנה\"\u0004 — \u0003זה מעשה העגל, \"ואנכי לא אשכחך\"\u0004 — \u0003זה מעשה סיני.\u0004","שנינו במשנה כי \u0003חסידים הראשונים היו שוהין שעה אחת\u0004 קודם תפילתם, ושואלים:","\u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' יהושע בן לוי:\u0004 רמז לכך, שכך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"אשרי יושבי ביתך\"\u0004 (תהלים פד, ה) ואחר כך \"עוד יהללוך סלה\" (שם).","\u0003ו\u0004עוד \u0003אמר ר' יהושע בן לוי: המתפלל צריך לשהות שעה אחת\u0004 גם \u0003אחר תפלתו, ש\u0004כך \u0003נאמר: \"אך צדיקים יודו לשמך ישבו ישרים את פניך\"\u0004 (תהלים קמ, יד). שלאחר ההודאה לה' בתפילה יש עוד לשבת לפניו בשהיית זמן.","וכדברים אלה \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003המתפלל צריך שישהא שעה אחת קודם תפלתו, ושעה אחת אחר תפלתו. קודם תפלתו, מנין? שנאמר: \"אשרי יושבי ביתך\". לאחר תפלתו מנין?\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"אך צדיקים יודו לשמך ישבו ישרים את פניך\".\u0004","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003חסידים הראשונים היו שוהין שעה אחת, ומתפללין שעה אחת, וחוזרין ושוהין שעה אחת.\u0004 ומעתה יש לשאול: \u0003וכי מאחר ששוהין תשע שעות ביום בתפלה\u0004 ובהכנות הסמוכות לה (שלוש שעות לכל אחת משלוש התפילות), \u0003תורתם היאך משתמרת\u0004 אם אין להם זמן לחזור עליה, \u0003ומלאכתם היאך נעשית?\u0004","ומשיבים: \u0003אלא מתוך שחסידים הם\u0004 — זוכים הם שתהא \u0003תורתם משתמרת, ומלאכתן מתברכת.\u0004","עוד שנינו במשנה ש\u0003אפילו המלך שואל בשלומו לא ישיבנו,\u0004 שאסור לאדם להפסיק מתפילתו.","ועל כך \u0003אמר רב יוסף\u0004 כי יש לסייג כלל זה, שכן \u0003לא שנו\u0004 דברים אלו במשנתנו \u0003אלא למלכי ישראל\u0004 בלבד, שיבינו משום מה אותו אדם איננו פונה לכבדם, \u0003אבל למלכי אומות העולם\u0004 — \u0003פוסק\u0004 מתפילתו מחמת הסכנה.","על דברי רב יוסף אלה \u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 והרי שנינו כי \u0003המתפלל וראה אנס\u0004 (אדם קשה שהכל מפחדים מפניו) \u0003בא כנגדו,\u0004 או \u0003קרון בא כנגדו,\u0004 והוא בדרכו — \u0003לא יהא מפסיק\u0004 את תפילתו, \u0003אלא\u0004 הריהו \u0003מקצר ועולה\u0004 בה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שאין מכאן סתירה, אלא \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שלא יפסיק אלא יקצר, מדובר \u0003במקום שאפשר לקצר\u0004 ולסיים קודם — אזי אכן \u0003יקצר. ואם לאו\u0004 \u0005[לא],\u0006 שהוא במקום שבו אינו יכול לקצר בתפילתו — \u0003פוסק.\u0004","ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בחסיד אחד שהיה מתפלל בדרך. בא הגמון אחד ונתן לו שלום,\u0004 ולא הפסיק אותו חסיד מתפילתו \u0003ולא החזיר לו שלום. המתין לו\u0004 אותו הגמון לחסיד זה \u0003עד שסיים תפלתו. לאחר שסיים תפלתו, אמר לו\u0004 אותו הגמון: \u0003ריקא\u0004 \u0005[ריק,\u0006 קל דעת\u0005],\u0006 שנהגת כך, שהרי יכולתי להמיתך על כך, וסיכנת עצמך, \u0003והלא כתוב בתורתכם \"רק השמר לך ושמר נפשך\", וכתיב\u0004 \u0005[ונאמר]\u0006 עוד בתורה \u0003\"ונשמרתם מאד לנפשתיכם\".\u0004 ומשום מה לא חששת מן הסכנה, ש\u0003כשנתתי לך שלום למה לא החזרת לי שלום? אם הייתי חותך ראשך בסייף, מי היה תובע את דמך מידי?!\u0004","\u0003אמר לו\u0004 אותו חסיד: \u0003המתן לי עד שאפייסך בדברים. אמר לו: אילו היית עומד לפני מלך בשר ודם, ובא חברך ונתן לך שלום\u0004 — האם \u0003היית\u0004"],["\u0003מחזיר לו\u0004 שלום?! \u0003אמר לו\u0004 ההגמון: \u0003לאו\u0004 \u0005[לא].\u0006 חזר ושאל אותו חסיד: \u0003ואם היית מחזיר לו\u0004 שלום, \u0003מה היו עושים לך? אמר לו\u0004 ההגמון: \u0003היו חותכים את ראשי בסייף. אמר לו: והלא דברים קל וחומר, ומה אתה שהיית עומד לפני מלך בשר ודם,\u0004 שאין יראתו מרובה, \u0003ש\u0004הרי \u0003היום\u0004 הוא \u0003כאן ומחר\u0004 הוא \u0003בקבר\u0004 — בכל זאת, מפני יראתו \u0003כך\u0004 היית נוהג. \u0003אני שהייתי עומד\u0004 בעת תפילתי \u0003לפני מלך מלכי המלכים הקדוש ברוך הוא, שהוא חי וקיים לעד ולעולמי עולמים\u0004 — \u0003על אחת כמה וכמה\u0004 שאין להפסיק ולהשיב שלום לאדם באותה עת.","כיון ששמע כן, \u0003מיד נתפייס אותו הגמון, ונפטר אותו חסיד לביתו בשלום.\u0004","שנינו במשנה שהמתפלל, \u0003אפילו נחש כרוך על עקבו, לא יפסיק.\u0004 על כך \u0003אמר רב ששת\u0004 בהגדרת הדברים: \u0003לא שנו\u0004 במשנתנו שאין להפסיק את תפילתו \u0003אלא\u0004 ב\u0003נחש,\u0004 שאם אין האדם מתגרה בו אין הוא נושכו. \u0003אבל עקרב\u0004 הבא לקראתו בעת תפילתו — \u0003פוסק,\u0004 שהעקרב עשוי לעקוץ, אף אם לא יעשה כל תנועה להרגיזו.","על כך \u0003מיתיבי\u0004 \u0005[מקשים ]\u0006 על כך ממה ששנינו בתוספתא: אם ראו אנשים אדם ש\u0003נפל לגוב אריות\u0004 ולא ראו מה נעשה בו אחר כך — \u0003אין\u0004 הרואים \u0003מעידין עליו שמת,\u0004 שאין עדותם מתקבלת בבית דין כראיה שמת, שכן יתכן שהאריות לא אכלוהו. ואולם מי שראוהו ש\u0003נפל לחפירה\u0004 (בור) \u0003מלאה נחשים ועקרבים\u0004 — \u0003מעידין עליו שמת,\u0004 שודאי נשכוהו הנחשים!","ומשיבים: אין זו קושיה כי \u0003שאני התם דאגב איצצא מזקי\u0004 \u0005[שונה שם,\u0006 בנופל לבור הנחשים, \u0005שאגב הדוחק\u0006 של נפילתו עליהם, \u0005מזיקים],\u0006 אבל נחש שלא נגעו בו לרעה לא יכיש.","וכמשמעות הלכה זו שמסכנה הקרובה לודאי יפסיק בתפילתו, \u0003אמר ר' יצחק:\u0004 אם \u0003ראה שוורים\u0004 הבאים לקראתו — \u0003פוסק\u0004 מתפילתו. שכך \u0003תני\u0004 \u0005[שנה ]\u0006 \u0003רב הושעיה:\u0004 מתוך זהירות \u0003מרחיקין\u0004 מ\u0003שור תם\u0004 שלא נודע שנגח — \u0003חמשים אמה, ומשור מועד\u0004 שיודעים בו שדרכו לנגוח — מרחיק \u0003כמלוא עיניו\u0004 (עד כמה שיראהו).","ועוד \u0003תנא משמיה\u0004 \u0005[שנה\u0006 החכם \u0005משמו]\u0006 של \u0003ר' מאיר: ריש תורא בדקולא\u0004 — \u0003סליק לאגרא, ושדי דרגא מתותך\u0004 \u0005[\u0006בעוד \u0005ראש השור בסל,\u0006 שהוא אוכל ממנו, \u0005עלה לגג וזרוק\u0006 את \u0005הסולם מתחתיך].\u0006 \u0003אמר שמואל:\u0004 יש להגדיר את הדברים ולומר כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאמרנו בענין הסכנה היתירה בשור אמורים דווקא \u0003בשור שחור וביומי\u0004 \u0005[ובימי]\u0006 \u0003ניסן, מפני ש\u0004בגזע מסוכן זה של שוורים ובעונת שנה זו \u0003השטן מרקד לו בין קרניו.\u0004","ומענין שבח המתפלל שאין לו להרתע אף מפני הנחש \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה במקום אחד שהיה ערוד, והיה מזיק את הבריות. באו והודיעו לו לר' חנינא בן דוסא\u0004 ובקשו את עזרתו. \u0003אמר להם: הראו לי את חורו! הראוהו את חורו. נתן עקבו על פי החור, יצא\u0004 הערוד \u0003ונשכו\u0004 — \u0003ומת אותו ערוד.\u0004","\u0003נטלו\u0004 ר' חנינא בן דוסא לאותו ערוד \u0003על כתפו והביאו לבית המדרש. אמר להם\u0004 ליושבי בית המדרש: \u0003ראו בני,\u0004 ש\u0003אין\u0004 ה\u0003ערוד\u0004 הוא ה\u0003ממית\u0004 את האדם, \u0003אלא החטא\u0004 הוא ה\u0003ממית.\u0004 ומי שאין בו חטא, אין הערוד שולט בו.","\u0003באותה שעה אמרו\u0004 החכמים: \u0003אוי לו לאדם שפגע בו ערוד, ואוי לו לערוד שפגע בו ר' חנינא בן דוסא.\u0004","במשנה זו מדובר בדברים שמוסיפים לנוסח תפילת העמידה הרגיל בעתים מזומנות, ובאלו ברכות מוסיפים אותם. \u0003מזכירין גבורות גשמים\u0004 באמירת \"משיב הרוח ומוריד הגשם\" \u0003ב\u0004ברכה השניה שיש בה מענין \u0003תחיית המתים. ו\u0004אילו את ה\u0003שאלה\u0004 (הבקשה על הגשמים, \"ותן טל ומטר לברכה\") אומרים בברכה העוסקת \u0003בברכת השנים. ו\u0004את ה\u0003הבדלה\u0004 בין הקודש והחול שאומרים במוצאי שבת ויום טוב מוסיפים \u0003ב\u0004ברכה הרביעית, היא ברכת \u0003\"חונן הדעת\". ר' עקיבא אומר\u0004 כי \u0003אומרה\u0004 להבדלה כ\u0003ברכה רביעית\u0004 העומדת \u0003בפני עצמה.\u0004 ואילו \u0003ר' אליעזר אומר\u0004 שמצרפים אותה \u0003ב\u0004ברכת ה\u0003הודאה\u0004 (\"מודים\").","שנינו במשנה כי \u0003מזכירין גבורות גשמים\u0004 בברכה השניה בתפילת העמידה, שיש בה מענין תחית המתים, ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 גבורות הגשמים נזכרות דווקא בברכה שיש בה מענין תחיית המתים?","\u0003אמר רב יוסף: מתוך ששקולה\u0004 ירידת הגשמים \u0003כתחיית המתים לפיכך קבעוה בתחיית המתים,\u0004 שאף עימה מתעוררים חיים חדשים בעולם הצומח (ירושלמי).","\u0003ו\u0004עוד שנינו במשנה כי את ה\u0003שאלה\u0004 על הגשמים קבעו \u0003בברכת השנים,\u0004 ואף כאן שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 שואלים גשמים דווקא בברכה זו?","\u0003אמר רב יוסף: מתוך שהיא\u0004 (ירידת הגשמים) יש בה מתן \u0003פרנסה, לפיכך קבעוה בברכת פרנסה.\u0004 והבקשה על הגשם היא חלק מן המשאלה לפרנסה בשפע.","\u0003ו\u0004עוד שנינו במשנה כי את ה\u0003הבדלה\u0004 בין הקודש לבין ימות החול קבעו חכמים לומר \u0003ב\u0004ברכת \u0003\"חונן הדעת\"\u0004 ואף כאן שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מבדילים דווקא בברכה זו?","\u0003אמר רב יוסף: מתוך שהיא\u0004 (ההבדלה) הריהי \u0003חכמה, קבעוה בברכת חכמה. ו\u0004אילו \u0003רבנן אמרי\u0004 \u0005[חכמים אומרים]\u0006 טעם אחר לקביעה זו: \u0003מתוך שהיא\u0004 (ההבדלה) עיקרה ההבחנה בין הקודש ל\u0003חול,\u0004 ולאחר אמירתה מותרת עשיית המלאכות כבימי החול, \u0003לפיכך קבעוה\u0004 חכמים שתיאמר \u0003בברכת\u0004 ה\u0003חול,\u0004 שהרי שלוש הברכות הראשונות שבתפילה נאמרות גם בשבת וביום טוב, בעוד שברכת \"חונן הדעת\" פותחת את הברכות הנאמרות רק בימי החול.","ומאחר שדובר בברכת הדעת הביאו עוד מה ש\u0003אמר רב אמי\u0004 בענין זה של הדעת: \u0003גדולה\u0004 היא ה\u0003דעה, ש\u0004כן \u0003נתנה בתחלת ברכה של\u0004 ימי ה\u0003חול,\u0004 והרי זה סימן להבלטת חשיבותה של הדעת.","\u0003ו\u0004עוד \u0003אמר רב אמי\u0004 בשבח הדעת: \u0003גדולה\u0004 היא ה\u0003דעה, ש\u0004כן \u0003נתנה בין שתי אותיות\u0004 (שני שמות של הקדוש ברוך הוא), \u0003ש\u0004כן \u0003נאמר \"כי אל דעות ה'\"\u0004 (שמואל א' ב, ג). \u0003ו\u0004משום שכה גדולה היא מעלת הדעת, \u0003כל מי שאין בו דעה\u0004 — \u0003אסור לרחם עליו,\u0004 וראיה לדבר, \u0003ש\u0004כן \u0003נאמר \"כי לא עם בינות הוא על כן לא ירחמנו עושהו\u0004 ויוצרו לא יחוננו\" (ישעיהו כז, יא). ואם הקדוש ברוך הוא אינו חס על מי שאין בו בינה, בני אדם לא כל שכן?","ובדומה לדברים אלה \u0003אמר ר' אלעזר: גדול\u0004 בית \u0003המקדש ש\u0004אף הוא \u0003נתן בין שתי אותיות, ש\u0004כן \u0003נאמר:\u0004 \"מכון לשבתך \u0003פעלת ה' מקדש ה'\u0004 כוננו ידיך\" (שמות טו, יז).","והוסיף \u0003ואמר ר' אלעזר\u0004 וצרף את שני הרעיונות: \u0003כל אדם שיש בו דעה\u0004 הרי זה \u0003כאילו נבנה בית המקדש בימיו.\u0004 שהרי במקרא ישנה הקבלה בין שניהם, שכן גם \u0003דעה נתנה בין שתי אותיות,\u0004 וגם \u0003מקדש נתן בין שתי אותיות,\u0004 הרי איפוא שהדעת והמקדש עומדים בדרגה אחת.","על דרך ההוכחה הזאת ממציאותו של דבר בין שני שמות ה' \u0003מתקיף לה רב אחא קרחינאה: אלא מעתה\u0004 אם כן הוא, נאמר גם כן ש\u0003גדולה\u0004 היא ה\u0003נקמה, ש\u0004הרי גם היא \u0003נתנה בין שתי אותיות, ש\u0004כן \u0003נאמר \"אל נקמות ה'\u0004 אל נקמות הופיע\u0003\"\u0004 (תהלים צד, א)!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[\u0006אכן \u0005כן],\u0006 \u0003במילתה מיהא [בעניינה לפחות] גדולה היא\u0004 הנקמה, שלעתים נחוצה היא, \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר עולא\u0004 שמקרא זה בו נזכרות \u0003שתי נקמות הללו\u0004 שנאמרו במקרא (\"אל נקמות ה' אל נקמות הופיע\") למה נאמרו? ללמדנו שנקמה \u0003אחת\u0004 היא \u0003לטובה, ואחת לרעה.\u0004 וכוונת הדברים, נקמה \u0003לטובה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כך \u0005נאמר]:\u0006 \u0003\"הופיע מהר פארן\"\u0004 (דברים לג, ב) שהוא נקמת ה' ברשעים, והנקמה \u0003לרעה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כך \u0005נאמר]:\u0006 \u0003\"אל נקמות ה' אל נקמות הופיע\"\u0004 בפורענותם של ישראל.","במשנה הובאה מחלוקת תנאים היכן נאמרת ההבדלה בתפילה, ש\u0003ר' עקיבא אומר\u0004 ש\u0003אומרה ברכה רביעית\u0004 בפני עצמה, ור' אליעזר אומר שנאמרת בברכת ההודאה, ולדעת תנא קמא הריהי נאמרת ב\"חונן הדעת\".","ועל כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמן\u0004 (שמעון) \u0003בר אבא לר' יוחנן\u0004 בשאלה: \u0003מכדי\u0004 \u0005[הרי]\u0006 את תפילת שמונה עשרה ושאר נוסחאות \u0003אנשי כנסת הגדולה\u0004 הם ש\u0003תקנו להם לישראל,\u0004 כשאר כל \u0003ברכות ותפלות קדושות והבדלות,\u0004 אם כן מה מקום יש למחלוקת בהלכה שכבר נקבעה? \u0003נחזי\u0004 \u0005[נראה]\u0006 \u0003היכן,\u0004 באיזו ברכה, \u0003תקון\u0004 \u0005[תקנו]\u0006 אנשי הכנסת הגדולה לומר את ההבדלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן שאי אפשר לעשות זאת, משום שנוהג ההבדלה עבר שלבים שונים: \u0003בתחילה,\u0004 בשנים הראשונות והקשות של ימי הבית השני \u0003קבעוה\u0004 את ההבדלה כחלק הנאמר \u0003בתפלה\u0004 בלבד. אחר כך כאשר \u0003העשירו\u0004 בני העם בהמשך הדורות — \u0003קבעוה\u0004 שתיאמר \u0003על הכוס\u0004 של יין במוצאי שבת ויום טוב. ואולם כאשר שוב \u0003הענו\u0004 — \u0003חזרו וקבעוה בתפלה. והם אמרו: המבדיל בתפלה\u0004 אם יכול הוא (ש\"מ, מאירי) \u0003צריך שיבדיל\u0004 גם \u0003על הכוס,\u0004 ובשל השינויים הללו לא היה ברור עוד היכן בדיוק נאמרת ההבדלה.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]:\u0006 \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: אנשי כנסת הגדולה תקנו להם לישראל ברכות ותפלות, קדושות והבדלות. בתחלה קבעוה\u0004 להבדלה שתיאמר \u0003בתפלה, העשירו\u0004 העם — \u0003קבעוה על הכוס, חזרו והענו\u0004 — \u0003קבעוה בתפלה, והם אמרו: המבדיל בתפלה\u0004 — \u0003צריך שיבדיל על הכוס.\u0004","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]:\u0006 \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003המבדיל בתפלה\u0004 — \u0003צריך שיבדיל על הכוס.\u0004","על דבר זה \u0003אמר רבא: ומותבינן אשמעתין\u0004 \u0005[ומקשים אנו על שמועתנו,\u0006 על הלכה זו\u0005]\u0006 ממה ששנינו בתוספתא: מי ש\u0003טעה ולא הזכיר גבורות גשמים בתחיית המתים,\u0004 או \u0003שאלה בברכת השנים\u0004 — \u0003מחזירין אותו\u0004 שיתפלל שנית, \u0003והבדלה ב\"חונן הדעת\"\u0004 — \u0003אין מחזירין אותו\u0004 שיתפלל שנית, \u0003מפני שיכול לאומרה על הכוס.\u0004 ואם כן, נראה מכאן שההבדלה על הכוס היא אפשרות בלבד ולא חובה.","ומתרצים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 כלשון השנויה בתוספתא \u0003\"מפני שיכול לאומרה על הכוס\", אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003\"מפני שאומרה\u0004 בודאי \u0003על הכוס\".\u0004","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כראיה נוספת שיש להבדיל גם על הכוס, \u0003אמר ר' בנימין בר יפת: שאל ר' יוסי את ר' יוחנן בצידן, ואמרי לה\u0004 \u0005[ויש האומרים אותה\u0006 שאלה\u0005]\u0006 שהיה זה \u0003ר' שמעון בן יעקב\u0004 ש\u0003מן\u0004 העיר \u0003צור\u0004 ששאל אותה \u0003את ר' יוחנן, ואנא שמעית\u0004 \u0005[ואני,\u0006 בנימין בן יפת, \u0005שמעתי]:\u0006 אדם \u0003המבדיל\u0004 כבר \u0003בתפלה,\u0004 האם \u0003צריך ש\u0004יחזור ו\u0003יבדיל על הכוס, או לא? ואמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן בתשובה לכך: \u0003צריך שיבדיל על הכוס.\u0004","השאלה אם המבדיל בתפילה צריך גם להבדיל על הכוס נתבררה כבר, ואולם עדיין \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: אדם \u0003המבדיל\u0004 כבר \u0003על הכוס, מהו\u0004 דינו לענין זה \u0003ש\u0004יחזור ו\u0003יבדיל\u0004 גם \u0003בתפלה?\u0004","\u0003אמר רב נחמן בר יצחק:\u0004 אפשר ללמוד זאת ב\u0003קל וחומר מתפלה,\u0004 מן ההלכה שנקבעה בענין הבדלה בתפילה. ובאופן זה: \u0003ומה תפלה\u0004 ש\u0003עיקר תקנתא\u0004 \u0005[התקנה]\u0006 \u0003היא\u0004 להבדיל בתפילה, ובכל זאת \u0003אמרי\u0004 \u0005[אמרו]\u0006 חכמים כי לא די בכך, אלא \u0003המבדיל בתפלה\u0004 — \u0003צריך שיבדיל על הכוס, המבדיל על הכוס, דלאו\u0004 \u0005[שלא]\u0006 \u0003עיקר תקנתא\u0004 \u0005[התקנה]\u0006 \u0003היא,\u0004 אלא נוספה אחר כך — \u0003לא כל שכן\u0004 שלא יצא ידי חובתו.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' אחא אריכא\u0004 \u0005[הארוך,\u0006 הגבוה] ברייתא \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חיננא: המבדיל בתפלה\u0004 הריהו \u0003משובח יותר ממי שיבדיל על הכוס, ואם הבדיל בזו ובזו\u0004 — \u0003ינוחו לו ברכות על ראשו.\u0004","משלומדים ברייתא זו רואים לכאורה כי \u0003הא גופא קשיא\u0004 \u0005[זו עצמה,\u0006 מתוכה, \u0005קשה],\u0006 שכן מצד אחד \u0003אמרת\u0004 כי \u0003המבדיל בתפלה\u0004 הריהו \u0003משובח יותר ממי שיבדיל על הכוס, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003תפלה לחודה סגי\u0004 \u0005[לעצמה מספיקה]\u0006 ואין צורך להבדיל על הכוס, \u0003והדר תני\u0004 \u0005[חזר ושנה]\u0006 ש\u0003אם הבדיל בזו ובזו\u0004 — \u0003ינוחו לו ברכות על ראשו, ו\u0004אולם \u0003כיון דנפק ליה בחדא\u0004 \u0005[שיצא לו\u0006 ידי חובת הבדלה \u0005באחת]\u0006 — כבר \u0003איפטר\u0004 \u0005[נפטר],\u0006 \u0003ו\u0004מעתה \u0003הויא\u0004 \u0005[נהיית]\u0006 זו הברכה הנוספת בהבדלה על הכוס \u0003ברכה שאינה צריכה, ו\u0004כבר \u0003אמר רב ואיתימא ריש לקיש, ו\u0004יש ש\u0003אמרי לה\u0004 \u0005[אמרוה]\u0006 לשמועה כי \u0003ר' יוחנן וריש לקיש\u0004 הם \u0003דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כי \u0003כל המברך ברכה שאינה צריכה\u0004 — \u0003עובר משום \"לא תשא\u0004 את שם אלהיך לשוא\u0003\"\u0004 (שמות כ, ז)!","\u0003אלא\u0004 יש לתקן, ו\u0003אימא הכי\u0004 \u0005[אמור כך]:\u0006 \u0003אם הבדיל בזו ולא בזו\u0004 — \u0003ינוחו לו ברכות על ראשו.\u0004","בענין זה \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב חסדא מרב ששת:\u0004 אם \u0003טעה בזו ובזו,\u0004 בהבדלה שבתפילה ובהבדלה שעל הכוס, \u0003מהו\u0004 דינו? \u0003אמר ליה\u0004 \u0005[לן]:\u0006 \u0003טעה בזו ובזו\u0004 — \u0003חוזר לראש\u0004 התפילה ולראש ההבדלה על הכוס."],["נמצא שבענין הבדלה על הכוס לאחר ההבדלה בתפילה הדעות חלוקות. לדעה אחת ראוי להבדיל פעם שניה, ולדעה אחרת יש בכך משום איסור. על כן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא\u0004 בשאלה: \u0003הלכתא מאי?\u0004 \u0005[מהי ההלכה?]\u0006 \u0003אמר ליה\u0004 \u0005[לו] :\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 \u0003קידוש\u0004 יהא דין ההבדלה, \u0003מה קידוש אף על גב\u0004 ש\u0003מקדש בצלותא\u0004 \u0005[בתפילה]\u0006 הריהו חוזר ו\u0003מקדש אכסא\u0004 \u0005[על הכוס],\u0006 \u0003אף הבדלה נמי\u0004 \u0005[גם כן],\u0006 \u0003אף על גב\u0004 ש\u0003מבדיל בצלותא\u0004 \u0005בתפילה]\u0006 הריהו חוזר ו\u0003מבדיל אכסא\u0004 \u0005[על הכוס].\u0006","במשנה נאמר כי \u0003ר' אליעזר\u0004 סבור שאת ההבדלה \u0003אומר ב\u0004ברכת ה\u0003\"הודאה\".\u0004","בנושא זה מובאת מסקנת ההלכה בדרך סיפור: \u0003ר' זירא הוה רכיב חמרא, הוה קא שקיל ואזיל\u0004 \u0005[היה רכוב על חמור, והיה נוהג והולך]\u0006 \u0003ר' חייא בר אבין בתריה\u0004 \u0005[אחריו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ודאי דאמריתו משמיה\u0004 \u0005[האם נכון הוא\u0006 \u0003שאמרת משמו]\u0004 של \u0003ר' יוחנן\u0004 ש\u0003הלכה כר' אליעזר ביום טוב שחל להיות אחר השבת?\u0004 שמכיון שאי אפשר לומר הבדלה ב\"חונן הדעת\" (שכן אין ברכה זו כלולה בתפילת יום טוב) בעל כרחנו עושים אנו כר' אליעזר. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","על כך תוהים בגמרא: \u0003הלכה\u0004 — \u0003מכלל דפליגי,\u0004 אם צריך לומר שהלכה כדברי ר' אליעזר במקרה זה, מכאן שחבריו חלוקים עליו, והיכן מצאנום חולקים בכך?","את התמיהה הזו דוחים: \u0003ולא פליגי\u0004 \u0005[וכי אינם חלוקים]?\u0006 \u0003והא פליגי רבנן\u0004 \u0005[והרי חלוקים חכמים]\u0006 שלדעתם ברכת ההבדלה אינה נאמרת ב\"חונן הדעת\".","על כך עונים: \u0003אימר דפליגי רבנן\u0004 \u0005[אמור שחלוקים חכמים]\u0006 על ר' אליעזר \u0003בשאר ימות השנה,\u0004 כשיש אפשרות להבדיל ב\"חונן הדעת\", אולם \u0003ביום טוב שחל להיות אחר השבת מי פליגי\u0004 \u0005[האם חולקים],\u0006 וודאי הסכימו חכמים לדעתו.","ועוד שואלים: \u0003והא פליג\u0004 \u0005[והרי חולק]\u0006 \u0003ר' עקיבא\u0004 האומר שהבדלה היא ברכה רביעית לעצמה, ואם כן יש בכל זאת מחלוקת בדבר!","ועונים על כך: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל השנה כולה מי עבדינן\u0004 \u0005[האם עושים אנו]\u0006 בענין זה \u0003כר' עקיבא, דהשתא ניקו ונעביד כוותיה\u0004 \u0005[שעכשיו\u0006 ביום טוב שחל במוצאי שבת, \u0005נקום ונעשה כמותו]?!\u0006 כי \u0003כל השנה כולה מאי טעמא לא עבדינן\u0004 \u0005[מה טעם אין אנו עושים]\u0006 \u0003כר' עקיבא\u0004 — \u0003משום דתמני סרי תקון\u0004 \u0005[ששמונה עשרה\u0006 ברכות \u0005תיקנו],\u0006 \u0003תשסרי\u0004 \u0005[תשע עשרה]\u0006 \u0003לא תקון\u0004 \u0005[תיקנו],\u0006 \u0003הכא נמי שב תקון\u0004 \u0005[כאן גם כן שבע תיקנו],\u0006 \u0003תמני\u0004 \u0005[שמונה]\u0006 \u0003לא תקון\u0004 \u0005[תיקנו],\u0006 ולכן אין אנו מתחשבים כלל בדעתו החולקת של ר' עקיבא.","על השאלות הללו \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא בתשובה, כי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003\"הלכה\u0004 כר' אליעזר \u0003\"אתמר\u0004 \u0005[נאמר]\u0006 בשם ר' יוחנן, (שמכאן אפשר היה להסיק שיש מחלוקת בדבר), אלא ש\u0003\"מטין\u0004 את הדין לשיטת ר' אליעזר\" \u0003אתמר\u0004 \u0005[נאמר]\u0006 מפי ר' יוחנן.","\u0003דאתמר\u0004 \u0005[ש\u0006אכן \u0005נאמר]\u0006 שבענין זה קיימת מחלוקת חכמים, ש\u0003רב יצחק בר אבדימי אמר משום\u0004 \u0005[בשם]\u0006 \u0003רבנו\u0004 (רב): \u0003הלכה\u0004 כר' אליעזר, \u0003ואמרי לה\u0004 \u0005[ו\u0006יש ה\u0005אומרים אותה\u0006 שמועה\u0005]\u0006 באופן שונה, שכך נאמר: \u0003\"מטין\u0004 לדעת ר' אליעזר\".","ואילו \u0003ר' יוחנן אמר\u0004 שאין כאן מחלוקת \u0003ומודים\u0004 חכמים לר' אליעזר. \u0003ור' חייא בר אבא אמר\u0004 שנקבע ש\u0003נראין\u0004 דברי ר' אליעזר.","על חילוקי דעות אלו \u0003אמר ר' זירא: נקוט\u0004 (החזק) דברים אלה של \u0003ר' חייא בר אבא בידך,\u0004 משום ש\u0003דייק\u0004 בהלכה \u0003וגמר שמעתא מפומא דמרה שפיר\u0004 \u0005[ולמד הלכה מפי בעליה,\u0006 מי שאמרה, היטב] \u0003כ\u0004פי שעשה החכם \u0003רחבא\u0004 מהעיר \u0003פומבדיתא,\u0004 שמפורסם היה רחבא בדיוק השלם בו מסר את הדברים כפי ששמעם מרבו.","ודוגמא לכך מביאים מדבריו, שכן \u0003אמר רחבא\u0004 שכך \u0003אמר ר' יהודה: הר הבית סטיו כפול היה, והיה סטיו לפנים מסטיו.\u0004 שהשתמש רחבא בלשון רבו בתיאור מבנה המקדש ואת שורות האיצטבות הנמצאות בתוכו, שורה לפנים משורה, אולם לא השתמש במלה השגורה איצטבה כי אם \"סטיו\" ששמע מרבו.","פסק הלכה בדברים אלה \u0003אמר רב יוסף: אנא\u0004 \u0005[אני]\u0006 \u0003לא האי ידענא\u0004 \u0005[\u0006את \u0005זה יודע אני]\u0006 \u0003ולא האי ידענא\u0004 \u0005[\u0006את \u0005זה יודע אני],\u0006 \u0003אלא מ\u0004תוך דברי \u0003רב ושמואל ידענא, דתקינו לן מרגניתא\u0004 \u0005[אני יודע, שתיקנו לנו \"מרגלית\"]\u0006 \u0003בבבל,\u0004 והם תיקנו נוסח המשלב בתוכו את הברכה הראשונה של החג עם ברכת ההבדלה, בדומה לדעת חכמים הכוללים את ברכת ההבדלה בברכה הראשונה שלאחר שלש הברכות הראשונות הקבועות.","שכך תיקנו לומר: \u0003\"ותודיענו ה' אלהינו את משפטי צדקך ותלמדנו לעשות חקי רצונך, ותנחילנו זמני ששון וחגי נדבה, ותורישנו קדושת שבת וכבוד מועד וחגיגת הרגל. בין קדושת שבת לקדושת יום טוב הבדלת, ואת יום השביעי מששת ימי המעשה קדשת. הבדלת וקדשת את עמך ישראל בקדושתך. ותתן לנו\" וכו'.\u0004","לסיום דיני התפילה במסכת מובאים דברים אחדים בנושאים שונים הקשורים בתפילה. במשנה זו מדובר על חידושים מסוימים בנוסח התפילה שיש להשתיק את שליח הציבור המנסה לאומרם, שכן תוכנם נוטה למינות. ש\u0003האומר\u0004 בתחינתו: כשם ש\u0003על קן ציפור יגיעו רחמיך,\u0004 שציווית לשלח את האם ולא לקחתה עם האפרוחים (דברים כב, ו-ז) כן תרחם עלינו — משתקים אותו. \u0003ו\u0004כן האומר \u0003\"על טוב יזכר שמך\",\u0004 וכן הכופל ואומר פעמיים \u0003\"מודים, מודים\"\u0004 — \u0003משתקין אותו.\u0004","נזכרו במשנתנו שלושה מקרים בהם משתקים את שליח הציבור, ומבררים: \u0003בשלמא\u0004 \u0005[בשלום,\u0006 נניח] שהאומר \u0003\"מודים, מודים\" משתקין אותו — משום דמיחזי\u0004 \u0005[שנראה]\u0006 הדבר \u0003כשתי רשויות,\u0004 שכן כפילת ההודאה נשמעת כאמונה בשניים, שיש להודות לכל אחד מהם לחוד. \u0003ו\u0004כן משתקים את האומר \u0003\"על טוב יזכר שמך\" נמי\u0004 \u0005[גם כן]\u0006 מובן, משום ש\u0003משמע\u0004 מכאן שהוא מודה לה' רק \u0003על הטובה ולא על הרעה, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 ש\u0003חייב אדם לברך על הרעה כשם שמברך על הטובה. אלא\u0004 זה האומר \u0003\"על קן צפור יגיעו רחמיך\" מאי טעמא\u0004 \u0005[מה טעם]\u0006 משתקים אותו?","\u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בהסברת בעיה זו \u0003תרי אמוראי במערבא\u0004 \u0005[שני אמוראים בארץ ישראל],\u0006 \u0003רבי יוסי בר אבין ורבי יוסי בר זבידא: חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שטעם הדבר הוא \u0003מפני שמטיל קנאה במעשה בראשית,\u0004 שנראה כמתרעם על ה' שמפלה כאילו לטובה יצור אחד משאר יצוריו. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שטעם הדבר הוא \u0003מפני שעושה מדותיו של הקדוש ברוך הוא\u0004 ביטוי של \u0003רחמים, ואינן אלא גזרות\u0004 מלך שיש לקיימן בלא לחקור בטעמיהן.","מסופר על \u0003ההוא דנחית קמיה\u0004 \u0005[\u0006אדם \u0005אחד שירד\u0006 לפני התיבה \u0005לפני]\u0006 \u0003רבה, ואמר\u0004 בתפילתו: \u0003אתה חסת על קן צפור, חוס ורחם עלינו. אמר רבה: כמה ידע האי צורבא מרבנן לרצויי למריה\u0004 \u0005[יודע תלמיד חכם זה לרצות לאדוניו,\u0006 לה']! \u0003ואמר ליה\u0004 [לו] \u0003אביי: והא\u0004 \u0005[והרי]\u0006 משנה מפורשת היא שהאומר כן \u0003משתקין אותו תנן\u0004 \u0005[שנינו]!\u0006","\u0003ומסבירים כי רבה נמי\u0004 \u0005[גם כן]\u0006 לא שאמר שלא כמשנה זו, אלא ש\u0003לחדודי\u0004 \u0005[לחדד]\u0006 את \u0003אביי הוא דבעי\u0004 \u0005[שרצה].\u0006 שלא אמר רבה הערתו זו כדי לשבח אותו תלמיד חכם אלא על מנת לבחון את אביי בן אחיו, להמריצו לומר מה שהוא יודע מן המשנה בענין זה.","בהקשר זה להוספות על נוסח חכמים בתפילות, מסופר על \u0003ההוא דנחית קמיה\u0004 \u0005[אחד שירד לפני התיבה]\u0006 לפני \u0003ר' חנינא,\u0004 והאריך בתפילה ו\u0003אמר \"האל הגדול הגבור והנורא והאדיר והעזוז והיראוי, החזק והאמיץ והודאי והנכבד\".\u0004","\u0003המתין לו\u0004 ר' חנינא \u0003עד\u0004 ש\u0003סיים תפילתו. כי\u0004 \u0005[כאשר]\u0006 \u0003סיים אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סיימתינהו לכולהו שבחי דמרך\u0004 \u0005[סיימת\u0006 בכך \u0005את כל שבחי ריבונך]?!\u0006 \u0003למה לי כולי האי\u0004 \u0005[כל זאת]?\u0006 \u0003אנן הני תלת דאמרינן, אי לאו דאמרינהו\u0004 \u0005[אנו, שלשת\u0006 שבחים \u0005אלו,\u0006 \"הגדול הגבור והנורא\", \u0005[שאומרים אנו אם לא שאמרם]\u0006 \u0003משה רבנו באורייתא\u0004 \u0005[בתורה],\u0006 \u0003ואתו\u0004 \u0005[ובאו]\u0006 \u0003אנשי כנסת הגדולה ותקנינהו\u0004 \u0005[ותיקנום]\u0006 \u0003בתפלה\u0004 — \u0003לא הווינן\u0004 \u0005[היינו]\u0006 \u0003יכולין למימר להו\u0004 \u0005[לומר אותם],\u0006 \u0003ואת אמרת כולי האי ואזלת\u0004 \u0005[ואתה אמרת והלכת כל זאת]!\u0006 \u0003משל, למלך בשר ודם שהיו לו אלף אלפים דינרי זהב והיו מקלסין\u0004 (משבחים) אותו \u0003בשל כסף, והלא גנאי הוא לו!\u0004 וכל השבחים שבני-האדם יכולים לשבח את ה' אינם אלא כשבח של דינרי כסף אחדים לגבי אלף אלפי דינרי זהב — אין בהם תוספת כבוד כלל.","\u0003ו\u0004מביאים אגב כך, עוד מה ש\u0003אמר ר' חנינא\u0004 מדברים הנוגעים בעיקרי האמונה: \u0003הכל בידי שמים, חוץ מיראת שמים.\u0004 שביד האדם יכולת הבחירה החפשית לעבוד את ה', או שלא לעשות כן. וראיה לדבר, \u0003ש\u0004כן \u0003נאמר: \"ועתה ישראל מה ה' אלהיך שואל מעמך כי אם ליראה\u0004 את ה' אלהיך ללכת בכל דרכיו ולאהבה אותו ולעבוד את ה' אלהיך בכל לבבך ובכל נפשך\" (דברים י, יב) הרי שדברים אלה צריך ה' לשאול מן האדם, לפי שהבחירה בידי האדם בלבד.","על פסוק זה שואלים: נאמר בו \"מה ה' אלהיך שואל מעמך כי אם ליראה\", ועל כך תמהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003יראת שמים מילתא זוטרתא\u0004 \u0005[דבר קטן]\u0006 \u0003היא?\u0004 שנאמר בו לשון זו (\"מה... כי אם\"), \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חנינא משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחאי: אין לו להקדוש ברוך הוא בבית גנזיו אלא אוצר של יראת שמים, שנאמר \"יראת ה' היא אוצרו\"\u0004 (ישעיהו לג, ו) שהדבר היחידי שה' מחשיב אותו ואוצר אותו הריהו יראת שמים בלבד.","על כך משיבים: \u0003אין, לגבי\u0004 \u0005[כן, אצל]\u0006 \u0003משה מילתא זוטרתא\u0004 \u0005[דבר קטן]\u0006 \u0003היא.\u0004 שכך \u0003אמר ר' חנינא\u0004 כ\u0003משל: ל\u0004דבר: \u0003אדם שמבקשים ממנו כלי גדול, ויש לו\u0004 — \u0003דומה עליו ככלי קטן\u0004 משום שהדבר נמצא כבר בידו. ולהיפך, אפילו כלי \u0003קטן\u0004 שמבקשים מאדם \u0003ואין לו ברשותו — דומה עליו ככלי גדול.\u0004 על כן, משה רבינו יכול היה לומר \"מה ה' שואל מעמך כי אם ליראה\", שבעיניו היה זה דבר קטן.","במשנה שנינו הלכה שהאומר \u0003מודים מודים\u0004 — \u0003משתקין אותו\".\u0004","על כך הוסיף ו\u0003אמר ר' זירא\u0004 שגם \u0003כל ה\u0004כופל בקריאת שמע ו\u0003אומר \"שמע שמע\"\u0004 — \u0003כאומר \"מודים מודים\" דמי\u0004 \u0005[נחשב].\u0006","\u0003מיתיבי\u0004 \u0005[שואלים]\u0006 על כך: והרי שנינו בברייתא: \u0003הקורא את שמע וכופלה\u0004 — \u0003הרי זה מגונה,\u0004 ואפשר לדייק מכאן ש\u0003מגונה הוא דהוי\u0004 \u0005[הינו],\u0006 ואולם \u0003שתוקי לא משתקינן ליה\u0004 \u0005[להשתיק אין משתיקים אותו]!\u0006","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 משום ש\u0003הא\u0004 \u0005[זה]\u0006 ששנינו בכופל את שמע שהוא מגונה בלבד, אך אין משתיקים אותו, מדובר \u0003דאמר מילתא מילתא ותני לה\u0004 \u0005[שאומר מלה מלה ושונה אותה],\u0006 שאז הוא רק מכער את קריאת שמע. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' זירא שהכופל את שמע משתקים אותו, מדובר \u0003דאמר פסוקא פסוקא ותני ליה\u0004 \u0005[שאומר פסוק פסוק ושונה אותו],\u0006 שנראה כמאמין בשתי רשויות.","על הלכה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי\u0004 בשאלה: \u0003ודילמא מעיקרא\u0004 \u0005[ושמא מתחילה]\u0006 \u0003לא כוון דעתיה\u0004 \u0005[דעתו],\u0006 \u0003ולבסוף כוון דעתיה\u0004 \u0005[דעתו],\u0006 ולכן הוא חוזר ואומר את הפסוק בכוונה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי:"],["\u0003חברותא כלפי שמיא מי איכא\u0004 \u0005[האם יש חברות כלפי שמים ]?!\u0006 שיכול אדם לזלזל בדבריו ולאומרם בכל אופן שירצה?! \u0003אי\u0004 \u0005[אם ]\u0006 \u0003לא כוון דעתיה מעיקרא\u0004 \u0005[דעתו מתחילה]\u0006 — \u0003מחינן ליה במרזפתא דנפחא\u0004 \u0005[מכים אותו בקורנס של נפחים]\u0006 \u0003עד דמכוין דעתיה\u0004 \u0005[שמכוון דעתו].\u0006 שכה בלתי נכונה היא דרך התנהגות כזו.","משנה זו והבאה אחריה עניינן שליח הציבור. \u0003(האומר: \"יברכוך טובים\"\u0004 — \u0003הרי זה דרכי מינות). העובר לפני התיבה, וטעה\u0004 — \u0003יעבור אחר תחתיו\u0004 מיד, \u0003ולא יהא\u0004 השני \u0003סרבן באותה שעה\u0004 מטעמי נימוס, כי מאחר שהופסקה התפילה באמצעה ראוי לו להזדרז ככל האפשר. \u0003מהיכן הוא מתחיל? מתחלת הברכה שטעה זה.\u0004","על מנת למנוע מן הכהנים לטעות בתפילתם אמרו כי \u0003העובר לפני התיבה לא יענה \"אמן\" אחר הכהנים\u0004 המברכים את העם, \u0003מפני הטרוף\u0004 (הבלבול), כי מאחר שלא היה בידו סידור תפילה תנתק אמירת ה\"אמן\" את סדר התפילה ויתחיל בברכה אחרת. \u0003ו\u0004מטעם זה אף \u0003אם אין שם כהן אלא הוא\u0004 — \u0003לא ישא את כפיו\u0004 לברך את העם, שמא יתבלבל. \u0003ו\u0004אולם \u0003אם הבטחתו\u0004 (מובטח לו) \u0003שהוא נושא את כפיו, וחוזר לתפלתו\u0004 בלא להתבלבל — \u0003רשאי\u0004 לברך.","במשנה נאמר שהבא למלא את מקומו של מי שטעה באמצע התפילה אין לו לסרב. ועל כן מובאת \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 כשמציעים לאדם שיהא \u0003עובר לפני התיבה\u0004 — \u0003צריך לסרב\u0004 בתחילה, מפני הנימוס, שלא יראה כלהוט אחר הדבר. \u0003ואם אינו מסרב\u0004 ונענה מייד לכך — הריהו \u0003דומה לתבשיל שאין בו מלח,\u0004 כלומר שהתנהגותו חסרת טעם. \u0003ו\u0004אולם \u0003אם מסרב יותר מדי\u0004 — אף זה אינו ראוי, שכן \u0003דומה\u0004 הוא בכך \u0003לתבשיל שהקדיחתו מלח\u0004 (שהוסיפו בו מלח יותר מדי). אלא \u0003כיצד הוא עושה,\u0004 מהי הדרך הראויה: כאשר מבקשים ממנו \u0003פעם ראשונה\u0004 — \u0003יסרב, ב\u0004פעם \u0003שניה\u0004 — \u0003מהבהב\u0004 (רוצה ואינו רוצה), כפתיל זה שהתחילה האש לאחוז בו ועדיין אינו בוער. וכשמבקשים פעם \u0003שלישית\u0004 — \u0003פושט את רגליו, ויורד\u0004 לפני התיבה.","אגב כך מובא מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003שלשה\u0004 דברים הם ש\u0003רובן\u0004 (אם מרבה בהם) — הרי זה \u0003קשה\u0004 (מזיק), \u0003ו\u0004אילו \u0003מיעוטן\u0004 (אם משתמש בהם במעט) — הרי זה \u0003יפה\u0004 (מועיל), \u0003ואלו הם: שאור\u0004 בבצק, \u0003ומלח\u0004 בתבשיל, \u0003וסרבנות\u0004 שמתוך נימוס.","במשנה נאמר כי הטועה בתפילתו, זה הבא במקומו מתחיל מתחילת אותה ברכה שבה אירעה הטעות. אולם דבר זה יש להבינו לא בדיוק כלשונו, שכך \u0003אמר רב הונא: טעה\u0004 המתפלל \u0003בשלש ראשונות,\u0004 ואפילו בשלישית — \u0003חוזר לראש\u0004 (ראשית) התפילה, כי שלוש ברכות אלה הן יחידה אחת. כמו כן אם טעה \u0003באמצעיות\u0004 — \u0003חוזר ל\"אתה חונן\"\u0004 שהיא הראשונה בברכות אלו. ואם טעה \u0003ב\u0004אחת משלוש הברכות ה\u0003אחרונות\u0004 — \u0003חוזר ל\"עבודה\"\u0004 (\"רצה\") שהיא תחילתן.","\u0003ורב אסי\u0004 חולק על רב הונא בנקודה אחת, שכן \u0003אמר: אמצעיות אין להן סדר,\u0004 ולכן אם טעה באחת מהן יכול הוא להשלימה במקום בו נזכר.","\u0003מתיב\u0004 \u0005[הקשה]\u0006 \u0003רב ששת\u0004 מן הברייתא. שנאמר בה: \u0003מהיכן הוא חוזר\u0004 — \u0003מתחלת הברכה שטעה זה.\u0004 ואם כן הוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב הונא\u0004 שאמר שאף בברכות האמצעיות חוזר לתחילתן.","על כך \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב הונא\u0004 שה\u0003אמצעיות כולהו חדא ברכתא נינהו\u0004 \u0005[כולן ברכה אחת הן],\u0006 וחזרה מתחילת הברכה משמעה — הברכה הראשונה.","חלוקה דומה של תפילת שמונה עשרה \u0003אמר רב יהודה: לעולם\u0004 (הנכון והרצוי תמיד) הוא ש\u0003אל ישאל אדם צרכיו\u0004 בתפילתו \u0003לא בשלש ראשונות, ולא בשלש אחרונות, אלא באמצעיות.\u0004 שכן \u0003אמר ר' חנינא\u0004 שבברכות \u0003ראשונות\u0004 — \u0003דומה\u0004 המתפלל \u0003לעבד שמסדר שבח לפני רבו\u0004 (אדונו). בברכות ה\u0003אמצעיות\u0004 — הריהו \u0003דומה לעבד שמבקש פרס\u0004 (הספקת צרכיו) \u0003מרבו.\u0004 ואילו בברכות ה\u0003אחרונות\u0004 — הריהו \u0003דומה לעבד ש\u0004כבר \u0003קבל פרס מרבו, ו\u0004הריהו עתה \u0003נפטר\u0004 (נפרד) \u0003והולך לו.\u0004","ועוד בעניני התפילה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בתלמיד אחד שירד לפני התיבה\u0004 כשליח ציבור \u0003בפני ר' אליעזר, והיה מאריך יותר מדאי. אמרו לו תלמידיו\u0004 בתלונה: \u0003כמה ארכן הוא זה! אמר להם: כלום מאריך\u0004 תלמיד זה בתפילתו \u0003יותר ממשה רבינו\u0004 בתפילתו, \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \"ואתנפל לפני ה' \u0003את ארבעים היום ואת ארבעים הלילה\u0004 אשר התנפלתי\"?! (דברים ט, כה), הרי שאין קיצבה לאריכות תפילה.","\u0003ושוב\u0004 (ועוד) \u0003מעשה בתלמיד אחד שירד לפני התיבה בפני ר' אליעזר, והיה מקצר יותר מדאי. אמרו לו תלמידיו\u0004 בתרעומת: \u0003כמה קצרן הוא זה! אמר להם: כלום מקצר\u0004 הוא בתפילתו \u0003יותר ממשה רבינו, דכתיב\u0004 \u0005[שנאמר]\u0006 בו, בתפילתו על רפואת מרים אחותו מצרעתה: \"ויצעק משה אל ה' לאמר \u0003אל נא רפא נא לה\"\u0004 (במדבר יב, יג). שודאי לא קיצר תלמיד זה בתפילתו יותר ממילים ספורות אלו.","ואגב הזכרת פסוק זה, מביאים מה ש\u0003אמר ר' יעקב אמר רב חסדא: כל המבקש רחמים\u0004 (המתפלל) \u0003על חבירו\u0004 — \u0003אין צריך להזכיר שמו\u0004 בתפילה, וראיה לדבר \u0003ש\u0004כן \u0003נאמר\u0004 בתפילתו של משה על מרים אחותו \u0003\"אל נא רפא נא לה\", ולא קמדכר\u0004 \u0005[ואין הוא מזכיר]\u0006 את \u0003שמה\u0004 של \u0003מרים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003אלו\u0004 הן ה\u0003ברכות\u0004 בתפילת שמונה עשרה \u0003שאדם שוחה\u0004 (משתחווה) \u0003בהן: ב\"אבות\"\u0004 (ברכה ראשונה), \u0003תחלה וסוף. ב\"הודאה\"\u0004 (\"מודים\") \u0003תחלה וסוף. ואם בא\u0004 (ברצונו) \u0003לשוח בסוף כל ברכה וברכה\u0004 מברכות שמונה עשרה, \u0003ובתחלת כל ברכה וברכה\u0004 — \u0003מלמדין אותו שלא ישחה.\u0004 שלא יוסיף על תקנת חכמים.","\u0003אמר ר' שמעון בן פזי\u0004 שכך \u0003אמר ר' יהושע בן לוי משום\u0004 \u0005[בשם]\u0006 התנא \u0003בר קפרא:\u0004 דברים אלה שאמרנו בענין ההשתחוואה בסוף כל ברכה וברכה נוהגים רק ב\u0003הדיוט\u0004 (סתם אדם), ו\u0003כמו שאמרנו,\u0004 שמלמדים אותו שלא יעשה כן."],["ואולם \u0003כהן גדול\u0004 ראוי לו שישתחווה \u0003בסוף כל ברכה וברכה, והמלך —\u0004 ב\u0003תחלת כל ברכה וברכה וסוף כל ברכה וברכה.\u0004 לפי שככל שהוא גדול יותר ראוי לו להרבות יותר בסימני כניעה. על כך \u0003אמר ר' יצחק בר נחמני: לדידי מפרשא\u0004 \u0005[לי בעצמי פורש]\u0006 \u0003לי מיניה\u0004 \u0005[ממנו]\u0006 מ\u0003ר' יהושע בן לוי\u0004 עצמו בדרך אחרת: \u0003הדיוט\u0004 דינו \u0003כמו שאמרנו,\u0004 ואילו ה\u0003כהן גדול\u0004 משתחוה ב\u0003תחלת כל ברכה וברכה,\u0004 ו\u0003המלך\u0004 — \u0003כיון שכרע\u0004 בתחילת הברכה \u0003שוב אינו זוקף\u0004 עד שיסיים תפילתו. וראיה מן הכתוב, \u0003ש\u0004כן \u0003נאמר: \"ויהי ככלות שלמה להתפלל\u0004 אל ה' את כל התפילה והתחינה הזאת \u0003קם מלפני מזבח ה' מכרע על ברכיו\u0004 וכפיו פרושות השמים\" (מלכים א ח, נד). מאחר שהוזכרה כריעת שלמה מובאת חלוקה בין הסוגים השונים של כריעות. \u0003תנו רבנן\u0004 \u0005שנו חכמים\u0006 בברייתא \u0005:\u0006 ה\u0003קידה\u0004 — הריהי כריעה \u0003על אפים,\u0004 שהקד כופף עצמו כלפי הארץ, \u0003ש\u0004כן \u0003נאמר: \"ותקד בת שבע אפים ארץ\"\u0004 (שם א, לא). ואילו \u0003כריעה\u0004 — הריהי כריעה \u0003על ברכים, ש\u0004כן \u0003נאמר\u0004 בשלמה לאחר תפילתו \"קם מלפני מזבח ה' \u0003מכרע על ברכיו\".\u0004 ואילו \u0003השתחואה\u0004 — \u0003זו\u0004 כריעה שיש בה \u0003פשוט\u0004 (פשיטת ) \u0003ידים ורגלים,\u0004 בהכנעה מלאה. וראיה לדבר \u0003ש\u0004כן \u0003נאמר\u0004 בדברי יעקב ליוסף לאחר חלומותיו: \u0003\"הבוא נבוא אני ואמך ואחיך להשתחות לך ארצה\"\u0004 (בראשית לז, י).","","","ועוד בדינים אלה של כריעה \u0003אמר רב חייא בריה\u0004 \u0005בנו\u0006 של \u0003רב הונא: חזינא להו\u0004 \u0005[ראיתי אותם ]\u0006 את \u0003אביי ורבא דמצלו אצלויי\u0004 \u0005[שהיו מטים עצמם],\u0006 ולא היו משתחווים ממש על הארץ בתפילתם.","ועוד בענין הכריעות בתפילה, שואלים: \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003הכורע בהודאה\u0004 (ברכת \"מודים\" בתפילת עמידה) — \u0003הרי זה משובח. ו\u0004אולם \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 הכורע בהודאה — \u0003הרי זה מגונה,\u0004 והרי זו סתירה בין ברייתות!","ומתרצים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 שאין כאן סתירה, אלא, \u0003הא\u0004 \u0005[\u0006בברייתא \u0005זו\u0006 המשבחת את הכורע בהודאה\u0005]\u0006 מדובר בכריעה \u0003בתחלה\u0004 של הברכה, ואילו \u0003הא\u0004 \u0005[\u0006בברייתא \u0005זו\u0006 המגנה את הכורע בהודאה\u0005]\u0006 מדובר בכריעה \u0003לבסוף\u0004 הברכה.","ונמסר ש\u0003רבא כרע\u0004 \u0005[היה כורע]\u0006 \u0003ב\u0004ברכת \u0003הודאה תחלה וסוף. אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]:\u0006 \u0003אמאי קא עביד מר הכי?\u0004 \u0005[מדוע עושה אדוני כך?]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 כך \u0003חזינא\u0004 \u0005[ראיתי]\u0006 את \u0003רב נחמן דכרע\u0004 \u0005[שכורע\u0006 בברכת ההודאה\u0005]\u0006 \u0003ו\u0004כך גם \u0003חזינא ליה\u0004 \u0005[ראיתי אותו]\u0006 את \u0003רב ששת דקא עבד הכי\u0004 \u0005[שהוא עושה כך].\u0006","","","","","","","","","","","","","","","","","","","","","","\u0003ו\u0004אולם \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]\u0006 ש\u0003הכורע בהודאה\u0004 — \u0003הרי זה מגונה!\u0004 תירץ רבא: בברייתא \u0003ההיא\u0004 מדובר \u0003בהודאה שב\"הלל\",\u0004 כשאומר \"הודו לה'\", שבה אין ראוי לכרוע. ומוסיפים ושואלים על הנהגתו זו של רבא: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 האומרת במפורש: \u0003הכורע בהודאה ובהודאה של \"הלל\"\u0004 — \u0003הרי זה מגונה.\u0004 הרי ש\"הודאה\" בסתם איננה הודאה של \"הלל\", ובודאי היא ברכת ההודאה שבתפילה, ונאמר אף בה שהכורע בה הריהו מגונה! אף קושיה זו נדחית: \u0003כי תניא\u0004 \u0005[כאשר שנויה]\u0006 הברייתא \u0003ההיא\u0004 הריהי עוסקת \u0003בהודאה\u0004 שב\u0003ברכת המזון (הברכה השניה הפותחת ב\"נודה\").\u0004 בסיום הלכות תפילה מדברת המשנה על צדדים בתפילה שאינם שייכים לצד המעשה. \u0003המתפלל ו\u0004נמצא ש\u0003טעה\u0004 בתפילתו — \u0003סימן רע\u0004 הוא \u0003לו,\u0004 להראותו שאין תפילתו מקובלת. \u0003ואם שליח צבור הוא\u0004 הטועה — הרי זה \u0003סימן רע לשולחיו, מפני ששלוחו של אדם כמותו.\u0004 ומעין דברים אלה \u0003אמרו עליו על ר' חנינא בן דוסא שהיה מתפלל על החולים, ו\u0004והיה \u0003אומר\u0004 מיד לאחר תפילתו: \u0003\"זה חי,\u0004 ויבריא ממחלתו\" \u0003ו\"זה מת\".\u0004 וכש\u0003אמרו לו\u0004 בשאלה: \u0003מנין אתה יודע? אמר להם: אם שגורה תפלתי בפי\u0004 — שאני מתפלל בקלות ובלי תקלות \u0003יודע אני שהוא מקובל\u0004 והתפילה עלתה לרצון. \u0003ואם לאו\u0004 — \u0003יודע אני שהוא מטורף,\u0004 שהושלכה התפילה ולא נתקבלה. נאמר במשנה שהטועה בתפילתו הריהו סימן רע, ושואלים: \u0003אהייא\u0004 \u0005[על איזו]\u0006 ברכה מברכות התפילה נאמרו דברים אלה? \u0003אמר רב חייא\u0004 שכך \u0003אמר רב ספרא משום חד דבי רב\u0004 \u0005[בשם\u0006 חכם \u0005אחד מבית המדרש]\u0006 של \u0003רבי: ב\u0004ברכת \u0003\"אבות\"\u0004 (הברכה הראשונה בתפילת העמידה). ו\u0003איכא דמתני לה אברייתא\u0004 \u0005[יש ששונים אותה,\u0006 את המסורת הזו, \u0005על ברייתא]\u0006 ובנושא שונה. שכן שנינו בברייתא ש\u0003המתפלל צריך שיכוין את לבו ב\u0004כל הברכות שבתפילה \u0003כולן, ואם אינו יכול לכוין בכולן\u0004 — \u0003יכוין את לבו\u0004 לפחות \u0003באחת\u0004 מהן. ועל ברייתא זו \u0003אמר ר' חייא\u0004 שכך \u0003אמר רב ספרא משום חד דבי רב\u0004 \u0005[בשם\u0006 חכם \u0005אחד מבית המדרש]\u0006 של \u0003רבי:\u0004 הכוונה במה ששנינו \"באחת\" — \u0003ב\u0004ברכת \u0003\"אבות\".\u0004 שנינו במשנה ש\u0003אמרו עליו על ר' חנינא\u0004 בן דוסא שהיה נותן סימן מתי התפילה מקובלת ומתי איננה מקובלת, אם שגורה תפלתו אם לאו. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 מהו המקור ממנו למד ר' חנינא סימן זה? \u0003אמר ר' יהושע בן לוי,\u0004 שכך \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בורא ניב שפתים שלום שלום לרחוק ולקרוב אמר ה' ורפאתיו\"\u0004 (ישעיהו נז, יט), שאם ניתן למתפלל דיבור סדור ורהוט (\"ניב שפתים\") הרי זה לו לסימן שתפילתו על החולה מקובלת, והוא יירפא (\"אמר ה' ורפאתיו\"). ובסיום דברים אלה מובא מה ש\u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן\u0004 בשכר הצדיקים: \u0003כל הנביאים כולן לא נתנבאו\u0004 בנבואות הנחמה שלהם \u0003אלא למשיא בתו לתלמיד חכם\u0004 מתוך הערכת חכמתו, \u0003ו\u0004כן \u0003לעושה פרקמטיא\u0004 (מסחר) \u0003ל\u0004מען \u0003תלמיד חכם, ו\u0004כן \u0003למהנה תלמיד חכם מנכסיו\u0004 באופן אחר. \u0003אבל תלמידי חכמים עצמן\u0004 — לא פירשו הנביאים כלל את גודל שכרם, ועליהם נאמר \"ומעולם לא שמעו לא האזינו \u0003עין לא ראתה אלהים זולתך יעשה למחכה לו\"\u0004 (שם סד, ג). \u0003ו\u0004מאותו פסוק עצמו \u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: כל\u0004 נבואות \u0003הנביאים כולן\u0004 על שינוי סדרי העולם באחרית הימים \u0003לא נתנבאו אלא לימות המשיח, אבל לעולם הבא\u0004 שהוא דרגה וזמן גבוהים יותר, עליהם נאמר \u0003\"עין לא ראתה אלהים זולתך\". ו\u0004מציינים כי \u0003פליגא\u0004 \u0005[חלוקה]\u0006 אימרה זו על \u0003שמואל,\u0004 שכן \u0003אמר שמואל: אין\u0004 הבדל \u0003בין העולם הזה לימות המשיח אלא שעבוד מלכויות בלבד.\u0004 שבימות המשיח יהיו ישראל עצמאיים ולא יהיו משועבדים לשאר מלכויות, אבל סדרי העולם ישארו כמו שהם. וראיה הביא לדבריו מן הכתוב, \u0003ש\u0004כן \u0003נאמר: \"כי לא יחדל אביון מקרב הארץ\"\u0004 (דברים טו, יא), הרי שסדרי העולם קבועים הם ולא ישתנו. \u0003ו\u0004עוד \u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: כל הנביאים כולן\u0004 בנבואות הנחמה שאמרו \u0003לא נתנבאו אלא לבעלי תשובה, אבל צדיקים גמורים\u0004 עליהם נאמר \u0003\"עין לא ראתה אלהים זולתך\". ו\u0004מציינים ששיטה זו \u0003פליגא\u0004 \u0005[חלוקה]\u0006 על שיטת \u0003ר' אבהו\u0004 הסבור שבעלי תשובה עדיפים על צדיקים, שכך \u0003אמר ר' אבהו: במקום\u0004 (בדרגה) \u0003שבעלי תשובה עומדים\u0004 — \u0003צדיקים גמורים אינם עומדין, ש\u0004כן \u0003נאמר: \"שלום שלום לרחוק ולקרוב\", \"לרחוק\" ברישא\u0004 \u0005[בראש,\u0006 בתחילה], כלומר קודם ניתן השלום לבעל התשובה שהיה רחוק, \u0003והדר\u0004 \u0005וחוזר\u0006 אחר כך\u0005]\u0006 ונותן השלום \u0003\"לקרוב\",\u0004 שהוא הצדיק הגמור. \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: מאי\u0004 \u0005[מה]\u0006 הכוונה בביטוי \u0003\"רחוק\"\u0004 — זה \u0003שהיה רחוק מדבר עבירה מעיקרא\u0004 \u0005[מתחילה]\u0006 (והוא הצדיק הגמור), ולו נאמר קודם שלום. \u0003ומאי\u0004 \u0005[ומה]\u0006 הכוונה בביטוי \u0003\"קרוב\"\u0004 — זה \u0003שהיה קרוב לדבר עבירה, ונתרחק ממנו השתא\u0004 \u0005[עכשיו]\u0006 שחזר בתשובה. ולבעל תשובה נאמר שלום לאחר שנאמר לצדיק. ר' יוחנן אמר מקודם שיש מתן שכר שעליו נאמר \"עין לא ראתה\" ושואלים: \u0003מאי\u0004 \u0005[מהו\u0006 הדבר\u0005]\u0006 בו נאמר מקרא זה \u0003\"עין לא ראתה\"? אמר ר' יהושע בן לוי: זה יין המשומר בענביו מששת ימי בראשית,\u0004 ועל כן לא ראתה אותו עדיין שום עין. ואילו \u0003ר' שמואל בר נחמני אמר\u0004 כי הכוונה היא: \u0003זה עדן, שלא שלטה בו\u0004 מעולם \u0003עין כל בריה.\u0004 \u0003שמא תאמר: אדם הראשון היכן היה?\u0004 שהרי היה בגן עדן, וראה איפוא את עדן! לכך יש להשיב: אדם הראשון היה רק \u0003בגן\u0004 של עדן, אך לא בעדן עצמו. \u0003ושמא תאמר: הוא גן, הוא עדן\u0004 ואין הבדל ביניהם, \u0003תלמוד לומר: \"ונהר יוצא מעדן להשקות את הגן\"\u0004 (בראשית ב, י), הרי שכל אחד מהם דבר לעצמו הוא, \u0003גן לחוד ועדן לחוד.\u0004 ומתוך שסופר במשנתנו בר' חנינא בן דוסא, מספרים עוד בשבחי תפילתו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה שחלה בנו של רבן גמליאל. שגר\u0004 (שלח) רבן גמליאל \u0003שני תלמידי חכמים אצל ר' חנינא בן דוסא\u0004 כדי \u0003לבקש עליו רחמים\u0004 (שיתפלל עליו לרפואתו). \u0003כיון שראה אותם\u0004 ר' חנינא בן דוסא שהם באים אליו, \u0003עלה לעלייה\u0004 שבגג ביתו, \u0003ובקש עליו רחמים. בירידתו אמר להם\u0004 לשליחים: \u0003לכו,\u0004 יכולים אתם לשוב לרבן גמליאל, מפני \u0003שכבר חלצתו חמה\u0004 (עזב אותו החום) והבריא. \u0003אמרו לו\u0004 השליחים: מנין אתה יודע, \u0003וכי נביא אתה?! אמר להן: לא נביא אנכי ולא בן נביא אנכי\u0004 (עיין עמוס ז, יד), \u0003אלא כך מקובלני\u0004 כסימן: \u0003אם שגורה תפלתי בפי\u0004 — \u0003יודע אני שהוא מקובל, ואם לאו\u0004 — \u0003יודע אני שהוא מטורף.\u0004 ומסופר כי \u0003ישבו\u0004 השליחים הללו \u0003וכתבו\u0004 לעצמם \u0003וכוונו\u0004 (רשמו במדויק) \u0003אותה שעה\u0004 שאמר להם את הדברים. \u0003ו\u0004מסופר כי \u0003כשבאו\u0004 השליחים הללו \u0003אצל רבן גמליאל\u0004 וסיפרו לו את כל שעבר עליהם, והראו לו את הזמן בו נאמר להם שהבריא בנו, \u0003אמר להם: העבודה\u0004 (לשון שבועה, בעבודת המקדש), \u0003שלא חסרתם ולא הותרתם\u0004 על הזמן בו קרה הדבר, \u0003אלא כך היה מעשה\u0004 בדיוק \u0003באותה שעה חלצתו חמה ושאל לנו\u0004 (וביקש מאתנו) \u0003מים לשתות.\u0004 \u0003ושוב\u0004 (ועוד) \u0003מעשה בר' חנינא בן דוסא שהלך ללמוד תורה אצל ר' יוחנן בן זכאי, וחלה בנו של ר' יוחנן בן זכאי. אמר לו: חנינא בני, בקש עליו רחמים ויחיה. הניח\u0004 ר' חנינא בן דוסא את \u0003ראשו בין ברכיו\u0004 להתבוננות והתיחדות \u0003ובקש עליו רחמים, וחיה\u0004 בנו של ר' יוחנן בן זכאי. \u0003אמר ר' יוחנן בן זכאי\u0004 על עצמו: \u0003אילמלי הטיח בן זכאי את ראשו בין ברכיו כל היום כולו\u0004 — \u0003לא היו משגיחים עליו. אמרה לו אשתו: וכי חנינא גדול ממך? אמר לה: לאו, אלא\u0004 מפני מה תפילתו נשמעת יותר מתפילתי, משום ש\u0003הוא דומה כעבד לפני המלך\u0004 היכול להיכנס תמיד ולבקש מן המלך דברים שונים. \u0003ו\u0004אילו \u0003אני דומה כשר לפני המלך\u0004 היכול להיכנס רק בהזמנה ולבקש על דברים כלליים וגדולים ביותר. \u0003ו\u0004עוד \u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן\u0004 בדיני תפילה: \u0003אל יתפלל אדם אלא בבית שיש בו חלונות,\u0004 משום שאז הוא רואה את השמים ויכול לכוון לבו. וראיה לדבר, \u0003ש\u0004כן \u0003נאמר\u0004 שכך נהג דניאל בתפילתו: \u0003\"וכוין פתיחן ליה בעיליתיה\u0004 \u0005[וחלונות פתוחים לו בעלייתו]\u0006 \u0003נגד ירושלם\"\u0004 (דניאל ו, יא).","ומעין דברים אלה על המקום הראוי לתפילה \u0003אמר רב כהנא: חציף עלי מאן דמצלי בבקתא\u0004 \u0005[חצוף בעיני מי שמתפלל בשדה].\u0006 \u0003ו\u0004עוד \u0003אמר רב כהנא\u0004 בנוסח דומה בעניינו של המתפלל באופן שאינו ראוי: \u0003חציף עלי מאן דמפרש חטאיה\u0004 \u0005[חצוף בעיני מי שמפרש\u0006 את \u0005חטאו,\u0006 ומגלהו לרבים\u0005],\u0006 וראיה לדבר מן הכתוב, \u0003שנאמר: \"אשרי נשוי פשע כסוי חטאה\"\u0004","",""],["במשנה זו מבואר מה הן הברכות שמברכים לפני האוכל, על מאכלים שונים. \u0003כיצד מברכין על הפירות? על\u0004 כל \u0003פירות האילן הוא אומר: \"בורא פרי העץ\", חוץ מן היין\u0004 שאף שמקורו בפירות האילן, גפן, מכל מקום מחמת חשיבותו ברכתו שונה מזו של שאר פירות האילן, \u0003שעל היין הוא אומר: \"בורא פרי הגפן\"; ועל פירות הארץ הוא אומר: \"בורא פרי האדמה\", חוץ מן הפת,\u0004 שאף היא בשל חשיבותה ברכתה שונה, \u0003שעל הפת הוא אומר: \"המוציא לחם מן הארץ\"; ועל הירקות\u0004 (עשבים וירקות עלים) \u0003הוא אומר: \"בורא פרי האדמה\". ר' יהודה אומר\u0004 שיש לחלק גם בין פירות האדמה למיניהם, ועל ירקות אלה, אף שגם הם מפירות הארץ, כיון שטבעם שונה יש לברך \u0003\"בורא מיני דשאים\".\u0004","על עצם יסודן של הברכות שואלים בגמרא: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 מה המקור לחובת הברכה בכלל לפני האכילה? ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006 בספרא: נאמר בדיני הנטיעות שבשנה רביעית \u0003\"קדש הלולים לה'\"\u0004 (ויקרא יט, כד), וכתוב זה \u0003מלמד ש\u0004הם \u0003טעונים ברכה\u0004 (הלל לה') \u0003לפניהם ולאחריהם,\u0004 לשני הילולים. \u0003מכאן אמר ר' עקיבא: אסור לאדם שיטעום כלום קודם שיברך,\u0004 כי בלי ה\"הלל\" על המאכל, הרי הוא כקודש האסור בהנאה.","על כך שואלים: \u0003והאי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"קדש הלולים\" להכי הוא דאתא?\u0004 \u0005[לכך הוא שבא\u0006 הכתוב ללמדנו\u0005]?\u0006 והלא \u0003האי מיבעי ליה\u0004 \u0005[\u0006כתוב \u0005זה צריך אותו]\u0006 כדי ללמוד דברים אחרים; \u0003חד\u0004 \u0005[\u0006דבר \u0005אחד]\u0006 ש\u0003אמר רחמנא\u0004 (ה'): \u0003אחליה והדר אכליה\u0004 \u0005[חללהו ואחר כך אכלהו],\u0006 שבמדרש זה מתפרש \"הילולים\" כמו חילולים. \u0003ואידך\u0004 \u0005[ו\u0006הדבר \u0005האחר,\u0006 משמעות אחרת\u0005]\u0006 שרק \u0003דבר הטעון שירה,\u0004 כלומר, דבר העולה על המזבח וטעון שירה עם עלייתו, והוא יין בעת ניסוכו בלבד, הוא ה\u0003טעון חלול, ו\u0004אילו דבר \u0003שאינו טעון שירה,\u0004 וכגון שאר מיני אילנות \u0003אין טעון חלול. וכ\u0004שיטת \u0003ר' שמואל בר נחמני\u0004 ש\u0003אמר\u0004 בשם \u0003ר' יונתן,\u0004 ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מנין שאין אומרים שירה\u0004 במקדש \u0003אלא על היין\u0004 בשעת ניסוכו על המזבח? — מתוך \u0003שנאמר: \"ותאמר להם הגפן החדלתי את תירושי המשמח אלהים ואנשים\u0004 והלכתי לנוע על העצים\" (שופטים ט, יג), ומסביר \u0003אם\u0004 אמנם היין \u0003אנשים משמח,\u0004 ואולם \u0003אלהים במה משמח?\u0004 אלא יש ללמוד \u0003מכאן שאין אומרים שירה אלא על היין,\u0004 והרי שהיין משמח גם בעבודת ה' במקדש. על כל פנים המלה נדרשת כבר לענין אחר!","אמנם \u0003הניחא למאן דתני\u0004 \u0005[זה נוח,\u0006 מובן, \u0005למי ששנה]\u0006 בדיני ערלה השנויים במשניות בכל פעם לשון \u0003\"נטע רבעי\",\u0004 שלדעתו כל האילנות (הנטעים) כולם בשנה הרביעית לנטיעתם צריכים חילול. \u0003אלא למאן דתניא\u0004 \u0005[למי ששנה]\u0006 בכל המשניות לשון \u0003\"כרם רבעי\" מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי הוא לומד הלכה זו מן הדרשה \"הילול\" — חילול, שרק היין שיש בו תהילה יש בו חילול. \u0003דאתמר\u0004 \u0005[שנאמר,\u0006 ששנינו\u0005]\u0006 שנחלקו החכמים \u0003ר' חייא ור' שמעון ברבי, חד תני\u0004 \u0005[אחד שנה]\u0006 לשון \u0003\"כרם רבעי\", וחד תני\u0004 \u0005[ואחד,\u0006 האחר \u0005שנה]\u0006 לשון \u0003\"נטע רבעי\",\u0004","\u0003ולמאן דתני\u0004 \u0005[ול\u0006דעת \u0005מי ששנה]\u0006 לשון \u0003\"כרם רבעי\" הניחא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 \u0003אי יליף\u0004 \u0005[זה נוח אם\u0006 נאמר ש\u0005הוא לומד]\u0006 \u0003גזרה שוה,\u0004 ולכן איננו צריך ללמוד הלכה זו מן הביטוי \"הילולים\". \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 הדבר נלמד ממה ש\u0003נאמר כאן\u0004 בדיני ערלה \"ובשנה החמישית תאכלו את פריו \u0003להוסיף לכם תבואתו\u0004 אני ה' אלהיכם\" (ויקרא יט, כה), \u0003ונאמר להלן\u0004 בדיני כלאיים נאמר \u0003\"\u0004לא תזרע כרמך כלאיים פן תקדש המלאה...אשר תזרע \u0003ותבואת הכרם\"\u0004 (דברים כב, ט), ומשוויון המלים אפשר ללמוד: \u0003מה להלן\u0004 בדיני כלאיים המדובר הוא ב\u0003כרם\u0004 בלבד, \u0003אף כאן\u0004 בדיני ערלה המדובר הוא ב\u0003כרם\u0004 בלבד. ולשיטה זו \u0003אייתר ליה חד \"הלול\"\u0004 \u0005[מיותר,\u0006 נשאר \u0005לו \"הילול\" אחד]\u0006 \u0003לברכה,\u0004 שמאחר שהוא יודע שדיני נטע רבעי אינם אלא בגפן על ידי גזירה שווה, אפשר שילמד מן המלה \"הילולים\" להצריך ברכה.","\u0003ואי\u0004 \u0005[\u0006אולם \u0005אם]\u0006 \u0003לא יליף\u0004 \u0005[אינו לומד]\u0006 \u0003גזרה שוה\u0004 זו, הרי הוא לומד הלכה זו מן הריבוי \"הילולים\", ואם כן מצוות \u0003ברכה\u0004 לפני האכילה \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 יתר על כן: \u0003ואי נמי יליף\u0004 \u0005[ואם גם כן\u0006 נאמר \u0005שהוא לומד]\u0006 \u0003גזרה שוה, אשכחן\u0004 \u0005[מצאנו]\u0006 מכאן ראיה לחובת ברכה \u0003לאחריו,\u0004 אחר האכילה, וכפי שנאמר \"ואכלת ושבעת וברכת\" ואולם ראיה על \u0003לפניו מנין?\u0004 שהרי מ\"הילול\" אחד למדים אנו לעצם דין חילול נטע רבעי.","על כך עונים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 שכן אפשר לתרץ \u0003דאתיא\u0004 \u0005[שבא,\u0006 נלמד הדבר\u0005]\u0006 \u0003ב\u0004דרך \u0003קל וחומר,\u0004 והוא: אם \u0003כשהוא שבע\u0004 לאחר האוכל — \u0003מברך\u0004 עליו, לפניו \u0003כשהוא\u0004 עדיין \u0003רעב\u0004 — \u0003לא כל שכן.\u0004","ומעירים: בדרך לימוד זו \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ראיה לחובת ברכה על תבואת ה\u0003כרם,\u0004 ואולם על חובת ברכה ב\u0003שאר מינין מנין?\u0004","ומשיבים: \u0003דיליף\u0004 \u0005[ש\u0006הוא \u0005לומד\u0006 זאת\u0005]\u0006 בדרך \"מה מצינו\" \u0003מכרם: מה\u0004 פרי ה\u0003כרם\u0004 הוא \u0003דבר שנהנה\u0004 ממנו \u0003וטעון ברכה, אף כל דבר שנהנה ממנו\u0004 — \u0003טעון ברכה.\u0004","ראיה זו דוחים: \u0003איכא למפרך\u0004 \u0005[יש לפרוך,\u0006 לשבור\u0005]\u0006 את הראיה ולהראות שיש צד מיוחד בכרם: \u0003מה לכרם שכן\u0004 דינו חמור יותר שכן הוא \u0003חייב בעוללות,\u0004 והרי שיש לו דין מיוחד שלא כלשאר הפירות, ואין ממנה אם כן ראיה לכולם!","על כך משיבים: אם כן \u0003קמה\u0004 של תבואה \u0003תוכיח,\u0004 שכן האוכל לחם חייב לברך אחריו מן התורה, אף על פי שאין בתבואה דין עוללות. הוכחה זו דוחים באותה דרך: גם דמה דינה התייחד משאר הפירות, שהרי \u0003מה לקמה שכן חייבת בחלה,\u0004 שיש להפריש מן העיסה מתנה מיוחדת \"חלה\", מה שאין כן במזונות אחרים, ואין אם כן להוכיח ממנה!","על כך עונים: בענין זה \u0003כרם יוכיח\u0004 שאין בו דין חלה ואף על פי כן יש לברך על פריו. ועל כן אפשר לסכם: \u0003וחזר הדין\u0004 (שיקול זה) אל הנקודה הראשונה שבה התחלנו בהוכחה. אלא מעתה נלמד משני הדברים יחד: \u0003לא ראי זה כראי זה\u0004 \u0005[אין דבר זה\u0006 נראה ונידון \u0005כדבר האחר]\u0006 \u0003ולא ראי זה כראי זה,\u0004 ואולם \u0003הצד השוה שבהם: דבר שנהנה וטעון ברכה,\u0004 ומכאן נגיע לכלל: \u0003וכל דבר שנהנה\u0004 — \u0003טעון ברכה.\u0004","ושוב דוחים: \u0003מה להצד השוה שבהם\u0004 שאף הוא מצומצם ואין ללמוד ממנו, שגם בכרם וגם בתבואה יש דבר המייחד אותם משאר הנאות העולם, \u0003שכן יש בו צד מזבח;\u0004 שמן הגפן והתבואה מקריבים קרבנות, ובשל כך טעונות הן גם ברכה. \u0003ו\u0004אמנם לפי זה \u0003אתי נמי\u0004 \u0005[יבוא\u0006 יילמד \u0005גם כן]\u0006 \u0003זית דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003צד מזבח,\u0004 שאף ממנו מעלים לקרבן המנחה, אך לא לדברים אחרים.","באותו פרט עצמו שואלים: \u0003ו\u0004כי \u0003זית בצד מזבח אתי\u0004 \u0005[בא,\u0006 נלמד\u0005]?\u0006 והרי \u0003זית בהדיא כתיב ביה\u0004 \u0005[במפורש כתוב בו]\u0006 לשון \u0003\"כרם\", דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ויבער מגדיש ועד קמה ועד כרם זית!\"\u0004(שופטים טו, ה), וכשם שלמדנו מן המלה \"כרם\" לגבי פרי הגפן כך יכולים אנו ללמוד גם על הזית. \u0003אמר רב פפא:\u0004 אף על פי כן אין הדברים דומים, כי \u0003\"כרם זית\" אקרי\u0004 \u0005[נקרא]\u0006 ואולם \u0003\"כרם\" סתמא לא אקרי\u0004 \u0005[סתם אינו נקרא],\u0006 ובמקום שכתוב \"כרם\" הכוונה היא לגפן בלבד.","וחוזרים לענייננו, \u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 מה שהקשינו קודם: \u0003מה להצד השוה שבהן שכן יש בהן צד מזבח! אלא\u0004 למדים בדרך אחרת, \u0003דיליף לה\u0004 \u0005[לומד\u0006 הוא \u0005אותה]\u0006 \u0003משבעת המינין,\u0004 שאחרי שמדבר הכתוב בהם נאמר \"ואכלת ושבעת וברכת\", ומהם נלמד לכל שאר דברי מאכל שיש אף בהם חובת ברכה, בדרך זו: \u0003מה שבעת המינין\u0004 הם \u0003דבר שנהנה\u0004 מאכילתם \u0003וטעון ברכה, אף כל דבר\u0004 מאכל אחר \u0003שנהנה\u0004 באכילתו יהא \u0003טעון ברכה.\u0004","ושוב דוחים: \u0003מה לשבעת המינין שכן חייבין בבכורים,\u0004 ואולם שאר פירות שאינם חייבים בביכורים מנין לנו שחייבים הם בברכה? \u0003ועוד\u0004 אפשר להקשות: \u0003התינח\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 שיודעים אנו חיוב ברכה \u0003לאחריו,\u0004 ואולם חיוב ברכה \u0003לפניו מנין\u0004 לנו?","אף על שאלה משיבים: \u0003הא לא קשיא\u0004 \u0005[\u0006דבר \u0005זה אינו קשה]\u0006 \u0003דאתי\u0004 \u0005[ש\u0006כן הוא \u0005בא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר\u0004 בדרך זו: אם \u0003כשהוא שבע\u0004 — \u0003מברך, כשהוא רעב\u0004 — \u0003לא כל שכן\u0004 שיצטרך לברך לפני אכילתו. בכל אופן ראיה גמורה לא נמצאה בשיטה זו.","ולא זו בלבד, אלא \u0003ולמאן דתני\u0004 \u0005[ול\u0006שיטת \u0005החכם השונה]\u0006 בדיני ערלה לשון \u0003\"נטע רבעי\",\u0004 וכולל בהלכות אלה את כל סוגי הצמחים שבעולם, \u0003התינח\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 לגבי \u0003כל דבר נטיעה\u0004 (כל שהוא עשוי וניתן לנטיעה), ואולם בענין דברים \u0003דלאו בר\u0004 \u0005[שלא בני]\u0006 \u0003נטיעה\u0004 הם, \u0003כגון בשר ביצים ודגים מנא ליה\u0004 \u0005[מנין לו]?\u0006 \u0003אלא\u0004 יש לחזור מכל ההסברים הקודמים ולומר שהברכה שמברכים על המאכלות בכלל \u0003סברא הוא\u0004 ש\u0003אסור לו לאדם שיהנה מן העולם הזה בלא ברכה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אסור לו לאדם שיהנה מן העולם הזה\u0004 שהוא רכוש הקדוש ברוך הוא \u0003בלא ברכה\u0004 קודם שנהנה. \u0003וכל הנהנה מן העולם הזה בלא ברכה\u0004 הרי זה כאילו \u0003מעל\u0004 בקדשים. ועל כך הוסיפו \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]?\u0006 — \u0003ילך אצל חכם.\u0004","על דבר זה תמהים: \u0003ילך אצל חכם?! מאי עביד ליה? הא עביד ליה איסורא\u0004 \u0005[מה יעשה לו\u0006 החכם? \u0005הרי עשה\u0006 כבר \u0005איסור],\u0006 ומה יועיל אז החכם? \u0003אלא אמר רבא\u0004, כך צריך להבין: \u0003ילך אצל חכם מעיקרא\u0004 \u0005[מתחילה]\u0006 עוד בימי ילדותו \u0003וילמדנו ברכות כדי שלא יבא\u0004 בעתיד \u0003לידי מעילה\u0004 כעין \u0003זו\u0004 בעולמו של הקדוש ברוך הוא.","ומעין זה \u0003אמר רב יהודה אמר שמואל: כל הנהנה מן העולם הזה בלא ברכה כאילו נהנה מקדשי שמים.\u0004 וראיה לכך ממה \u0003שנאמר: \"לה' הארץ ומלואה\u0004 תבל ויושבי בה\u0003\"\u0004 (תהלים כד, א). אותו רעיון מבטא ר' לוי בדרך אחרת. ש\u0003ר' לוי רמי\u0004 \u0005[השליך,\u0006 הקשה ממקור אחד על משנהו\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד: \u0003\"לה' הארץ ומלואה\", ו\u0004מצד אחר \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקור אחר: \u0003\"השמים שמים לה' והארץ נתן לבני אדם\"\u0004 (שם קטו, טז), והרי זו סתירה בין הנאמר בשני הכתובים למי היא הארץ! והוא עצמו מתרץ: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003כאן\u0004 בפסוק שנאמר שהעולם לה' הרי זה \u0003קודם ברכה\u0004"],["ואילו \u0003כאן\u0004 שנאמר שהארץ לבני אדם, הרי זה \u0003לאחר ברכה.\u0004","\u0003אמר ר' חנינא בר פפא: כל הנהנה מן העולם הזה בלא ברכה\u0004 — \u0003כאילו גוזל להקדוש ברוך הוא וכנסת ישראל. שנאמר: \"גוזל אביו ואמו ואומר אין פשע חבר הוא לאיש משחית\"\u0004 (משלי כח, כד). \u0003ואין\u0004 משמעות לשון \u0003\"אביו\" אלא הקדוש ברוך הוא, שנאמר: \"הלא הוא אביך קנך\u0004 הוא עשך ויכוננך\u0003\"\u0004 (דברים לב, ו). \u0003ואין\u0004 משמעות לשון \u0003\"אמו\" אלא כנסת ישראל, שנאמר: \"שמע בני מוסר אביך ואל תטוש תורת אמך\"\u0004 (משלי א, ח). שבגלל הזכרת התורה מפי האם מבינים כי \"אמך\" היא אומתך — כנסת ישראל.","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המשך הכתוב \u0003\"חבר הוא לאיש משחית\"? אמר ר' חנינא בר פפא:\u0004 אדם כזה \u0003חבר הוא לירבעם בן נבט שהשחית את ישראל לאביהם שבשמים,\u0004 היה חוטא ומחטיא את הרבים. ואדם כזה אף הוא בכלל זה.","בקשר לדברים האחרונים מביאים את מה ש\u0003ר' חנינא בר פפא רמי\u0004 \u0005[השליך,\u0006 הקשה ממקור אחד על משנהו\u0005]:\u0006 מצד אחד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ולקחתי דגני בעתו\u0004 ותירושי במועדו\u0003\"\u0004 (הושע ב, יא), \u0003ו\u0004מצד אחר \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב כהבטחה \u0003\"ואספת דגנך\u0004 ותירושך ויצהרך\u0003\"\u0004 (דברים יא, יד), והרי זו סתירה בין הנאמר בשני הכתובים למי הוא הדגן!","ומתרץ: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 כשמבטיח ה' לישראל שיאספו את דגנם הרי זה \u0003בזמן שישראל עושין רצונו של מקום\u0004 (הקדוש ברוך הוא), \u0003ו\u0004אילו \u0003כאן\u0004 שמשמע מהכתוב שהדגן של הקדוש ברוך הוא, הרי זה \u0003בזמן שאין ישראל עושין רצונו של מקום,\u0004 שאז הוא נוטל מהם את הדגן ומראה להם שהוא שלו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 זה שנאמר \u0003\"ואספת דגנך\" מה תלמוד לומר?\u0004 מה בא כתוב זה ללמדנו? — \u0003לפי שנאמר ביהושע\": \"לא ימוש ספר התורה הזה מפיך\u0004 והגית בו יומם ולילה\u0003\"\u0004 (יהושע א, ח), \u0003יכול\u0004 המשמעות המעשית של \u0003דברים\u0004 אלו \u0003ככתבן,\u0004 שיעסוק אדם כל ימיו בתורה בלבד, \u0003תלמוד לומר: \"ואספת דגנך\"\u0004 תירושך ויצהרך \u0003\"\u0004— \u0003הנהג בהם מנהג דרך ארץ,\u0004 שיש לנהוג כדרך העולם ולהקדיש זמן אף למלאכה, אלו \u0003דברי ר' ישמעאל.\u0004","ו\u0003ר' שמעון בן יוחאי אומר: אפשר\u0004 יעשו אנשים כך ויהא \u0003אדם חורש בשעת חרישה, וזורע בשעת זריעה, וקוצר בשעת קצירה, ודש בשעת דישה, וזורה בשעת הרוח\u0004 (כי רק כאשר הרוח נושבת אפשר לזרות תבואה ולהפרידה מן המוץ) ויהא עסוק תמיד, ו\u0003תורה מה תהא עליה? אלא\u0004 על האדם להקדיש עצמו לתורה, ולוותר על זמן העבודה בתחומים אחרים. ש\u0003בזמן שישראל עושין\u0004 את \u0003רצונו של מקום\u0004 — \u0003מלאכתן נעשית על ידי אחרים, שנאמר: \"ועמדו זרים ורעו צאנכם\u0004 ובני נכר איכריכם וכרמיכם\u0003\"\u0004 (ישעיהו סא, ה), \u0003ובזמן שאין ישראל עושין רצונו של מקום\u0004 בשלמות — \u0003מלאכתן נעשית על ידי עצמן, שנאמר: \"ואספת דגנך\"\u0004 וגו'. \u0003ולא עוד אלא\u0004 אם חוטאים \u0003ש\u0004אף \u0003מלאכת אחרים נעשית על ידן, שנאמר: \"ועבדת את אויבך\u0004 אשר ישלחנו ה' בך ברעב ובצמא ובעירום ובחוסר כל \u0003\"\u0004(דברים כח, מח).","על מחלוקת זו \u0003אמר אביי\u0004 כסיכום: אף שיש מקום לשתי הדעות, בכל זאת היו \u0003הרבה\u0004 ש\u0003עשו כר' ישמעאל,\u0004 שגם למדו תורה וגם עבדו לפרנסתם, \u0003ועלתה בידן,\u0004 שעל אף שעסקו בדברים אחרים פרט לעיסוקם בתורה, נתקיים לימודם. והרבה שעשו \u0003כר' שמעון בן יוחאי,\u0004 שרק למדו תורה ולא עסקו לפרנסתם בשום דבר אחר, \u0003ולא עלתה בידן\u0004 לשמור על לימודם, ונזקקו לעזבו לגמרי.","וכן בדרך דומה \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא לרבנן\u0004 \u0005[לחכמים]\u0006 שהיו באים לבית מדרשו: \u0003במטותא מינייכו\u0004 \u0005[בבקשה מכם],\u0006 \u0003ביומי\u0004 \u0005[בימי]\u0006 חודש \u0003ניסן וביומי\u0004 \u0005[ובימי]\u0006 חודש \u0003תשרי\u0004 זמן העבודה החקלאית \u0003לא תתחזו קמאי, כי היכי\u0004 \u0005[אל תראו לפני,\u0006 אלא עסקו בעבודתכם, \u0005כדי]\u0006 ש\u0003לא תטרדו במזונייכו כולא שתא\u0004 \u0005[במזונותיכם כל השנה\u0006 כולה\u0005].\u0006","כסיכום לאותם הדברים \u0003אמר רבה בר בר חנה אמר ר' יוחנן משום\u0004 (בשם) התנא \u0003ר' יהודה בר' אלעאי: בא וראה שלא כדורות הראשונים דורות האחרונים,\u0004 הנופלים מהם במעלתם; \u0003דורות הראשונים עשו\u0004 את \u0003תורתן קבע ו\u0004את \u0003מלאכתן עראי\u0004 (ארעי), ולמעשה \u0003זו וזו,\u0004 התורה והמלאכה, \u0003נתקיימה בידן.\u0004 ואילו \u0003דורות האחרונים שעשו\u0004 את \u0003מלאכתן קבע ותורתן עראי, זו וזו לא נתקיימה בידן.\u0004","\u0003ו\u0004מעין דברים אלה \u0003אמר רבה בר בר חנה אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' יהודה בר' אלעאי: בא וראה שלא כדורות הראשונים דורות האחרונים;\u0004 ב\u0003דורות הראשונים היו\u0004 אנשים \u0003מכניסין\u0004 את \u0003פירותיהן\u0004 לחצר \u0003דרך טרקסמון\u0004 \u0005[שער ראשי]\u0006 \u0003כדי לחייבן במעשר,\u0004 ואילו \u0003דורות אחרונים מכניסין פירותיהן דרך גגות, דרך חצרות דרך קרפיפות\u0004 \u0005[חצרות גדורות]\u0006 ולא דרך השער, \u0003כדי לפטרן מן המעשר,\u0004 וכפי ש\u0003אמר ר' ינאי: אין הטבל\u0004 (תבואה שלא עושרה) \u0003מתחייב במעשר עד שיראה\u0004 את \u0003פני הבית\u0004 (פתח הכניסה והיציאה) ויוכנס לבית דרך שם, וכפי \u0003שנאמר\u0004 בנוסח שאומרים בשעת וידוי המעשר: \u0003\"בערתי הקדש מן הבית\"\u0004 (דברים כו, יג), הרי שחיוב מעשר חל על תבואה שלא החליטו עדיין למי תיאכל רק כשמכניסים את התבואה לבית עצמו.","\u0003ור' יוחנן אמר: אפילו\u0004 ההכנסה ל\u0003חצר קובעת\u0004 להחשיב את הפירות כמוגמרים ולחייבם בשל כך במעשר, \u0003שנאמר\u0004 בדיני מעשר: \u0003\"\u0004ונתת ללוי לגר ליתום ולאלמנה \u0003ואכלו בשעריך ושבעו\"\u0004 (שם, שם, יב).","שנינו במשנה שעל פירות האילן מברך \"בורא פרי העץ\" \u0003חוץ מן היין\u0004 שאף שמקורו בפירות האילן נתייחדה לו הברכה לעצמו \"בורא פרי הגפן\". ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003יין\u0004 שנתייחדה לו ברכה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דאשתני, לעלויא אשתני\u0004 \u0005[שהשתנה לעילוי,\u0006 לטובה, מן הפרי שממנו נעשה, \u0005השתנה]\u0006 בשל כך גם כן \u0003לברכה, והרי שמן\u0004 אף \u0003דאשתני לעלויא\u0004 \u0005[שהשתנה לעילוי]\u0006 \u0003ו\u0004אף על פי כן \u0003לא אשתני\u0004 \u0005[השתנה]\u0006 \u0003לברכה,\u0004 וכפי ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל, וכן אמר ר' יצחק\u0004 שכך \u0003אמר ר' יוחנן: שמן זית מברכין עליו \"בורא פרי העץ\"\u0004 כמו על הזית עצמו ולא יותר.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 כתשובה: \u0003התם\u0004 \u0005[שם]\u0006 במקרה של שמן \u0003משום דלא\u0004 (שאי) \u0003אפשר\u0004 למצוא לו ברכה מתאימה, כי \u0003היכי נבריך\u0004 \u0005[כיצד נברך],\u0006 אם \u0003נבריך\u0004 \u0005[נברך]\u0006 \u0003\"בורא פרי הזית\"\u0004 הרי \u0003פירא גופיה\u0004 \u0005[הפרי עצמו]\u0006 \u0003\"זית\" אקרי\u0004 \u0005[נקרא],\u0006 והוא אשר נברא, ואולם השמן הוא תוצר הפרי שנעשה בידי אדם, ולשון זו אינה מתאימה לו. ואי אפשר לברך במקביל ל\"בורא פרי הגפן\", שכן הענבים עצמם הם פרי הבריאה, בניגוד לשמן.","ומקשים: בכל זאת אפשר למצוא נוסחה, \u0003ונבריך עליה\u0004 \u0005[ונברך עליו]\u0006 \u0003\"בורא פרי עץ זית\"\u0004 שתקביל מבחינת עניינה לברכת היין. \u0003אלא אמר מר זוטרא\u0004 הסבר אחר: הטעם שלא ייחדו ברכה לשמן הוא ש\u0003חמרא\u0004 \u0005[יין]\u0006 — \u0003זיין\u0004 \u0005[מזין],\u0006 \u0003משחא\u0004 \u0005[שמן]\u0006 — \u0003לא זיין\u0004 \u0005[אינו מזין].\u0006","על כך מקשים: \u0003ומשחא לא זיין\u0004 \u0005[ו\u0006כי \u0005שמן אינו מזין]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003הנודר מן המזון,\u0004 מי שקיבל על עצמו בנדר שלא לאכול מזון — \u0003מותר\u0004 הוא \u0003במים ומלח\u0004 שאינם נחשבים כמזון. \u0003והוינן\u0004 \u0005[ועסקנו]\u0006 \u0003בה\u0004 בהלכה זו: מכאן אפשר להסיק כי \u0003מים ומלח\u0004 בלבד \u0003הוא\u0004 ש\u0003לא אקרי\u0004 \u0005[נקראו]\u0006 \u0003\"מזון\", הא\u0004 \u0005[הרי]\u0006 \u0003כל\u0004 שאר \u0003מילי אקרי\u0004 \u0005[הדברים נקראו]\u0006 \u0003\"מזון\"\u0004 \u0005[הרי שכל דבר נקרא מזון],\u0006","ואם כן\u0003נימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר כי תהיה\u0006 זו \u0005קושיא חמורה]\u0006 על \u0003רב ושמואל דאמרי\u0004 \u0005[שאמרו]\u0006 \u0003אין מברכין \"בורא מיני מזונות\" אלא ב\u0004אכילת \u0003חמשת המינין\u0004 של תבואה \u0003בלבד,\u0004 שרק הם קרויים \"מזון\". \u0003ואמר רב הונא\u0004 שם כתירוץ, שיש לומר שמדובר במקרה מסויים: \u0003באומר\u0004 הנודר בלשון \u0003\"כל הזן עלי\u0004 יהא באיסור\u0003\",\u0004 ולכן כל דבר הזן את האדם (אף שאין לקרוא לו \"מזון\") נכלל בהגדרה זו מלבד מים ומלח.","\u0003אלמא משחא זיין\u0004 \u0005[הרי\u0006 ש\u0005שמן מזין],\u0006 ואין לומר שהיין לבדו מזין. \u0003אלא\u0004 הבדל אחר בין יין לשמן, \u0003חמרא\u0004 \u0005[יין]\u0006 — \u0003סעיד\u0004 \u0005[סועד],\u0006 \u0003ומשחא\u0004 \u0005[והשמן]\u0006 — \u0003לא סעיד\u0004 \u0005[אינו סועד],\u0006 כלומר, היין לא רק מזין, אלא אף נותן הרגשת שובע. על כך שואלים: \u0003וחמרא מי סעיד\u0004 \u0005[והיין האם\u0006 הוא \u0005סועד,\u0006 משביע\u0005]\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא הוה שתי חמרא\u0004 \u0005[היה שותה יין]\u0006 \u0003כל מעלי יומא דפסחא\u0004 \u0005[ערב פסח]\u0006 \u0003כי היכי דנגרריה ללביה, וניכול\u0004 \u0005[כדי שיגרור,\u0006 יגרה, \u0005את ליבו,\u0006 תאבונו, \u0005ויאכל]\u0006 \u0003מצה טפי\u0004 \u0005[יותר]\u0006 בתיאבון בליל הסדר. והרי שהיין רק מגרה את התיאבון ואולם אינו משביע. ומשיבים: \u0003טובא\u0004 \u0005[הרבה]\u0006 — \u0003גריר\u0004 \u0005[גורר,\u0006 מגרה\u0005],\u0006 \u0003פורתא\u0004 \u0005[מעט]\u0006 — \u0003סעיד\u0004 \u0005[משביע].\u0006","ושוב שואלים: \u0003ומי סעיד\u0004 \u0005[והאם\u0006 היין \u0005סועד]\u0006 \u0003כלל?! והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויין ישמח לבב אנוש\u0004 להצהיל פנים משמן \u0003ולחם לבב אנוש יסעד\"\u0004 (תהלים קד, טו), והרי ש\u0003נהמא\u0004 \u0005[לחם]\u0006 \u0003הוא דסעיד\u0004 \u0005[שסועד]\u0006 את הלב ואילו \u0003חמרא לא סעיד\u0004 \u0005[יין אינו סועד]!\u0006 \u0003אלא\u0004 יש לומר כי מפסוק זה אין ראיה, כי \u0003חמרא אית ביה תרתי\u0004 \u0005[היין יש בו שתי\u0006 מעלות\u0005]:\u0006 \u0003סעיד\u0004 \u0005[סועד]\u0006 \u0003ומשמח,\u0004 ואילו \u0003נהמא מסעד סעיד, שמוחי לא\u0004 \u0005[הלחם סועד, לשמח אינו]\u0006 \u0003משמח.\u0004","ומאחר שיש כאן כל המעלות הללו שואלים: \u0003אי הכי נבריך עליה\u0004 \u0005[נברך עליו,\u0006 לאחר שתייתו\u0005]\u0006 \u0003שלש ברכות,\u0004 כמו שמברכים ברכת מזון שלמה לאחר אכילת לחם! ומשיבים: \u0003לא קבעי אינשי סעודתייהו עלויה\u0004 \u0005[אין אנשים קובעים סעודתם עליו],\u0006 שאין אנשים עושים ארוחה שתהא רובה יין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא: אי\u0004 \u0005[אם]\u0006 \u0003קבע עלויה סעודתיה מאי?\u0004 \u0005[עליו סעודתו מה]\u0006 דינו? האם יצטרך אז לברך כמו אחרי הלחם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 פתרון לשאלתך תדע רק \u0003לכשיבא אליהו ויאמר אי הוי קביעותא\u0004 \u0005[אם היא קביעות],\u0006 כי זהו ספק שאין אנו יכולים להכריע בו. \u0003השתא מיהא\u0004 \u0005[עכשיו בכל אופן,\u0006 לפני שבא אליהו] \u0003בטלה דעתו אצל כל אדם,\u0004 ואנו רואים בו יוצא דופן, ולא יחוייב לברך ברכת מזון שלימה.","מקודם הובאה ההלכה שעל שמן זית מברכים \"בורא פרי העץ\" ומעתה באים לדון בהלכה זו \u0003גופא\u0004 \u0005[לעצמה].\u0006 \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל, וכן אמר ר' יצחק\u0004 שכך \u0003אמר ר' יוחנן: שמן זית מברכין עליו \"בורא פרי העץ\"\u0004 כמו על הזית עצמו ולא יותר. והשאלה היא \u0003היכי דמי\u0004 \u0005[איך בדיוק היה הדבר],\u0006 \u0003אילימא דקא שתי ליה משתה\u0004 \u0005[אם נאמר ששתה אותו]\u0006 כמו שהוא — \u0003אוזוקי מזיק ליה\u0004 \u0005[הריהו מזיק לו,\u0006 לשותה\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השותה שמן של תרומה\u0004 (שלא ידע שהיא תרומה) — \u0003משלם את הקרן,\u0004 אותו סכום שהזיק, \u0003ואינו משלם את החומש\u0004 (חמישית ערך הנזק, הנוספת כרגיל כקנס כאשר מחזירים מעילה בדברים מקודשים), שבמקרה זה נחשב האיש כמזיק בלבד, ולא כנהנה מן הקודש. מה שאין כן \u0003הסך\u0004 את גופו ב\u0003שמן של תרומה\u0004 — \u0003משלם קרן וחומש,\u0004 משום שנהנה. ומכאן למדנו ששתיית שמן אין בה הנאה ואף גורמת נזק לשותה.","\u0003אלא\u0004 צריך להסביר \u0003דקא אכיל ליה\u0004 \u0005[שאוכל אותו]\u0006 את השמן, \u0003על ידי\u0004 שהוא טובל בו פת לחם. ואולם \u0003אי הכי, הויא ליה\u0004 \u0005[אם כן, תהיה לה]\u0006 \u0003פת עיקר והוא,\u0004 השמן, \u0003טפל. ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005],\u0006 \u0003זה הכלל: כל שהוא עיקר ועמו טפלה\u0004 בדברי אכילה — \u0003מברך על העיקר\u0004 כראוי לו \u0003ופוטר את הטפלה\u0004 בלי ברכה מיוחדת. ובמקרה זה יש איפוא לברך רק על הלחם ולא על השמן! \u0003אלא\u0004 צריך לומר \u0003דקא שתי ליה\u0004 \u0005[שהוא שותה אותו]\u0006 \u0003על ידי אניגרון\u0004 וכפי ש\u0003אמר רבה בר שמואל: \"אניגרון\"\u0004 פירושו — \u0003מיא דסלקא\u0004 \u0005[מי סלק],\u0006 ואילו \u0003\"אנסיגרון\"\u0004 הוא \u0003מיא\u0004 \u0005[מים]\u0006"],["\u0003דכולהו שלקי\u0004 \u0005[של כל השלקים,\u0006 ירקות שלוקים\u0005],\u0006 ובאניגרון מוסיפים כמות ידועה של שמן.","ואולם גם כאן אפשר להקשות ש\u0003אם כן הוה ליה\u0004 \u0005[הריהו]\u0006 ה\u0003אניגרון עיקר ושמן טפל, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005],\u0006 \u0003זה הכלל: כל שהוא עיקר ועמו טפלה, מברך על העיקר\u0004 כראוי לו \u0003ופוטר\u0004 אף \u0003את הטפלה\u0004 באותה ברכה, ויש לברך איפוא רק על האניגרון!","ומתרצים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בחושש בגרונו,\u0004 שהיה לו כאב גרון, והוא שוטף את גרונו בשמן, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדומה לכך: \u0003החושש בגרונו לא יערענו\u0004 \u0005[יגרגר]\u0006 \u0003בשמן תחלה\u0004 (לכתחילה) \u0003בשבת,\u0004 שלא יכניסנו לפיו מלכתחילה כדי להשהותו בתוך גרונו לצורך רפואה, משום שאסור להשתמש ברפואות בשבת. \u0003אבל נותן שמן הרבה לתוך אניגרון ובולע אותו\u0004 אף לכתחילה. ומאחר שרגילים לשתות שמן לבדו או על ידי טפלה (אניגרון) לשם רפואה, יש לברך על שתיה זו \"בורא פרי העץ\".","על כך מקשים מצד אחר: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שיש לברך! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון\u0004 ש\u0003לרפואה קא מכוין\u0004 \u0005[הוא מתכוון]\u0006 ש\u0003לא לבריך עליה\u0004 \u0005[יברך עליו]\u0006 \u0003כלל,\u0004 שהרי אין מברכים לפני שתיית רפואה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבמקרה זה \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003הנאה מיניה, בעי ברוכי\u0004 \u0005[ממנו, צריך לברך\u0006 עליו\u0005].\u0006","ומבררים: \u0003קמחא דחיטי\u0004 \u0005[קמח חיטים],\u0006 אם אכלו כמות שהוא, מה יש לברך עליו? ובכך נחלקו הדעות: \u0003רב יהודה אמר\u0004 שמברך \u0003\"בורא פרי האדמה\", ורב נחמן אמר\u0004 שמברך \u0003\"שהכל נהיה בדברו\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: לא תפלוג עליה\u0004 \u0005[אל תחלוק עליו]\u0006 על \u0003רב יהודה,\u0004 כי \u0003ר' יוחנן ושמואל קיימי כוותיה\u0004 \u0005[עומדים כמותו,\u0006 בשיטתו\u0005]\u0006 אף על פי שדברו בנושא אחר. ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל, וכן אמר ר' יצחק\u0004 שכך \u0003אמר ר' יוחנן: שמן זית מברכים עליו \"בורא פרי העץ\". אלמא\u0004 \u0005[מכאן]:\u0006 \u0003אף על גב דאשתני\u0004 \u0005[אף על פי שהשתנה]\u0006 — \u0003במלתיה קאי\u0004 \u0005[בדברו,\u0006 בברכתו \u0005הוא עומד,\u0006 נשאר\u0005],\u0006 שהרי מברכים על השמן כשם שמברכים על הזית עצמו, אף על פי שהשתנה ממה שהיה בתחילה. \u0003והכא נמי אף על גב דאשתני\u0004 \u0005[וכאן גם כן אף על פי שהשתנה]\u0006 — \u0003במלתיה קאי\u0004 \u0005[בדברו,\u0006 בברכתו \u0005הוא עומד,\u0006 נשאר\u0005],\u0006 וכשם שמברכים על פרי האדמה, כך יש לברך על הקמח שנעשה ממנו.","על כך השיב: \u0003מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 — \u0003לית ליה עלויא אחרינא\u0004 \u0005[אין לו עילוי אחר],\u0006 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003אית ליה עלויא אחרינא\u0004 \u0005[יש לו עילוי אחר],\u0006 \u0003בפת\u0004 לחם, ומאחר שהשמן הוא המוצר המוגמר של הזית — יש לברך עליו כמו על העץ עצמו, ואולם קמח החיטים יש לו עילוי — כשהוא נעשה אחר כך לחם, ואם כן אינו אלא מוצר גולמי שאינו ראוי לא לברכת החיטה, ולא לברכה שעל הלחם כי אם \"שהכל\" בלבד.","על כך שואלים: \u0003וכי אית ליה עלויא אחרינא לא מברכינן עליה\u0004 \u0005[וכאשר יש לו עילוי אחר אין מברכים עליו]\u0006 \u0003\"בורא פרי האדמה\" אלא \"שהכל\"? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' זירא אמר רב מתנא אמר שמואל\u0004 ש\u0003אקרא חייא וקמחא דשערי מברכינן עלייהו\u0004 \u0005[על דלעת חיה,\u0006 לא מבושלת, \u0005וקמח שעורים מברכים עליהם]\u0006 \u0003\"שהכל נהיה בדברו\". מאי לאו דחיטי\u0004 \u0005[האם לא\u0006 נסיק מכאן \u0005ש\u0006בשל \u0005חיטים]\u0006 מברכים אנו עליהם \u0003\"בורא פרי האדמה\",\u0004 שאם על קמח שעורים, שאיננו כרגיל מאכל אדם, מברכים \"שהכל\", קמח חיטים ודאי ראוי לברכת \"בורא פרי האדמה\"!","טענה זו דוחים: \u0003לא, דחיטי נמי\u0004 \u0005[\u0006קמח \u0005של חיטים גם כן]\u0006 מברכים עליו \u0003\"שהכל נהיה בדברו\".\u0004","על כך שואלים: \u0003ולשמעינן דחיטי\u0004 \u0005[ושישמיענו\u0006 דין קמח \u0005חיטים]\u0006 \u0003וכל שכן\u0004 שנדע מכאן לגבי הברכה \u0003דשערי\u0004 \u0005[של\u0006 קמח \u0005שעורים]!\u0006","על כך משיבים: \u0003אי אשמעינן דחיטי הוה אמינא\u0004 \u0005[אם היה משמיע לנו ב\u0006קמח \u0005חיטים הייתי אומר]\u0006 כי \u0003הני מילי דחיטי\u0004 \u0005[דברים אלו אמורים\u0006 דווקא בקמח \u0005של חיטים],\u0006 \u0003אבל דשערי\u0004 \u0005[בשל שעורים]\u0006 \u0003לא לבריך עליה\u0004 \u0005[יברך עליו]\u0006 \u0003כלל, קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 ועל כן היה צורך ללמדנו שצריך לברך אף לפני אכילת קמח זה.","על הסבר זה מקשים: \u0003ומי גרע\u0004 \u0005[והאם גרוע]\u0006 הוא \u0003ממלח וזמית, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 ש\u0003על המלח ועל הזמית אומר\u0004 האוכל \u0003\"שהכל נהיה בדברו\",\u0004 וכל שכן קמח שעורים. קושיה זו נדחית: אף על פי כן \u0003אצטריך\u0004 \u0005[צריך]\u0006 לומר את ההלכה בענין קמח שעורים, כי \u0003סלקא דעתך אמינא\u0004 \u0005[\u0006היה \u0005עולה על דעתך לומר]\u0006 כי \u0003מלח וזמית עביד אינש דשדי לפומיה\u0004 \u0005[עשוי אדם שישליך לפיו]\u0006 לעיתים, \u0003אבל קמחא דשערי\u0004 \u0005[קמח שעורים]\u0006 \u0003הואיל וקשה לקוקיאני\u0004 \u0005[תולעי מעיים],\u0006 שהוא עשוי להזיק ולגרום להתפתחות אותם תולעים, ולכך הייתי אומר כי לומר את ההלכה בענין קמח שעורים ראוי היה ש\u0003לא לבריך עליה\u0004 \u0005[יברך עליו]\u0006 \u0003כלל,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 לאוכל \u0003הנאה מיניה\u0004 \u0005[ממנו]\u0006 על כן \u0003בעי ברוכי\u0004 \u0005[צריך לברך].\u0006","שאלה אחרת בדבר ברכה נשאלה ביחס ל\u0003קורא,\u0004 שהוא הקרום הדק המצפה את ענפיו הצעירים של הדקל שנהגו לעתים לפושטו מן הענף ולאכלו. ובכך נחלקו. \u0003רב יהודה אמר\u0004 כי יש לברך עליו \u0003\"בורא פרי האדמה\", ו\u0004אילו \u0003שמואל\u0004 רבו של רב יהודה \u0003אמר\u0004 שיש לברך עליו \u0003\"שהכל נהיה בדברו\".\u0004","ומסבירים את שיטותיהם: \u0003רב יהודה אמר\u0004 כי יש לברך עליו \u0003\"בורא פרי האדמה\",\u0004 שכן הריהו \u0003פירא\u0004 \u0005[פרי],\u0006 וצריך לברך עליו אם כן כעל כל פרי אחר. \u0003ו\u0004אילו \u0003שמואל אמר\u0004 שיש לברך עליו \u0003\"שהכל נהיה בדברו\", הואיל וסופו להקשות\u0004 (להתקשות) ויש לראותו אם כן כחלק מן העץ ולא כפרי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא, כוותך מסתברא\u0004 \u0005[גדול השיניים\u0006 (רה\"ג), \u0005כמותך מסתבר]\u0006 לומר, \u0003דהא\u0004 \u0005[שהרי]\u0006 אף ה\u0003צנון סופו להקשות\u0004 אם מניחים אותו באדמה, \u0003ו\u0004בכל זאת \u0003מברכינן עליה\u0004 \u0005[מברכים אנו עליו]\u0006 כשהוא רך \u0003\"בורא פרי האדמה\". ו\u0004מכל מקום, על אף שבח זה, מוכיחים כי \u0003לא היא\u0004 (אין הדבר כן), \u0003צנון נטעי אינשי אדעתא דפוגלא\u0004 \u0005[צנון זורעים אנשים על דעת,\u0006 מתוך כוונה, לאכול את \u0005הצנון הרך],\u0006 \u0003דקלא לא נטעי אינשי אדעתא דקורא\u0004 \u0005[דקל אין אנשים נוטעים על דעת\u0006 לאכול \u0005את קרומי הענף],\u0006 וסיב הדקל אינו אלא מאכל מקרי שאינו יכול להחשב פרי הדקל.","על כך שואלים: \u0003וכל היכא\u0004 \u0005[מקום]\u0006 ש\u0003לא נטעי אינשי אדעתא דהכי\u0004 \u0005[נוטעים אנשים על דעת כן]\u0006 \u0003לא מברכינן עליה\u0004 \u0005[מברכים אנו עליו]?\u0006 \u0003והרי צלף, דנטעי אינשי אדעתא דפרחא\u0004 \u0005[שנוטעים אנשים מתוך כוונה לאכול\u0006 את \u0005הפרי],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 ש\u0003על מיני נצפה\u0004 (שם אחר לצלף), \u0003על העלין ועל התמרות\u0004 (הענפים הצעירים) \u0003אומר\u0004 האוכל \u0003\"בורא פרי האדמה\", ו\u0004אילו \u0003על האביונות\u0004 (פרי הצלף) \u0003ועל הקפריסין\u0004 (ניצני פרי זה) \u0003אומר \"בורא פרי העץ\".\u0004 הרי שאף על העלים והתמרות הטפלים לפרי מברכים בכל זאת \"בורא פרי האדמה\" ולא \"שהכל\"!","על כך \u0003אמר רב נחמן בר יצחק\u0004 כי בכל זאת יש הבדל, \u0003צלף נטעי אינשי אדעתא דשותא\u0004 \u0005[צלף נוטעים אנשים על דעת\u0006 שיאכלו את \u0005העלים],\u0006 \u0003דקלא לא נטעי אינשי אדעתא דקורא\u0004 \u0005[דקל אין אנשים נוטעים על דעת\u0006 שיאכלו את \u0005הסיב]\u0006 ואין איפוא הוכחה מן הצלף על הדקל. ומסכמים: \u0003ואף על גב דקלסיה\u0004 \u0005[ואף על פי ששבחו]\u0006 \u0003שמואל לרב יהודה,\u0004 מכל מקום \u0003הלכתא כוותיה\u0004 \u0005[הלכה כמו]\u0006 \u0003שמואל.\u0004","ואגב הדיון בצלף מביאים הלכה נוספת בצלף. \u0003אמר רב יהודה אמר רב: צלף של ערלה בחוצה לארץ\u0004 (שבה דיני הערלה אינם אלא מדברי סופרים) \u0003זורק את האביונות\u0004 (שהם עיקר פריו של הצלף) \u0003ואוכל את הקפריסין.\u0004 ומעלים השאלה: \u0003למימרא\u0004 \u0005[האמם נאמר]\u0006 נסיק מכאן כי ה\u0003אביונות\u0004 הם \u0003פירי\u0004 \u0005[פירות]\u0006 ממש של הצלף \u0003ו\u0004אילו \u0003קפריסין לאו פירי\u0004 \u0005[אינם פרי]?\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים על כך,\u0006 אנו מביאים מקור סותר\u0005]\u0006 ממה ששנינו: \u0003על מיני נצפה על העלים ועל התמרות אומר \"בורא פרי האדמה\", ועל האביונות ועל הקפריסין אומר \"בורא פרי העץ\",\u0004 והרי שהקפריסין הינם פרי הצלף!","ומשיבים: \u0003הוא,\u0004 רב, ש\u0003אמר\u0004 ופסק \u0003כ\u0004שיטתו של \u0003ר' עקיבא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 ה\u0003צלף מתעשר\u0004 (חייב בהפרשת מעשרות) מכל הגדל עליו, מן ה\u0003תמרות ואביונות וקפריסין,\u0004 כי כל אלה נחשבים לפירותיו. ו\u0003ר' עקיבא אומר: אין מתעשר אלא אביונות בלבד, מפני ש\u0004רק \u0003הוא\u0004 נחשב \u0003פרי.\u0004 ולשיטה זו שרק האביונות הם פרי אסר רב לאכול רק את האביונות בשנות הערלה של הצלף.","ושואלים: אם כן הוא, מדוע פסק רב כן בענין ערלה, \u0003ונימא\u0004 \u0005[ויאמר]\u0006 בפשטות: \u0003\"הלכה כר' עקיבא\",\u0004 ומתוך זה ניתן להסיק כן הלכה למעשה אף לגבי ערלה! ומשיבים: \u0003אי אמר\u0004 \u0005[אילו\u0006 היה רב \u0005אומר]\u0006 \u0003\"הלכה כר' עקיבא\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003אפילו בארץ\u0004 ישראל הלכה כמותו, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בנוסח זה, שכלל הוא בדיני ערלה ש\u0003כל המיקל בארץ\u0004 — \u0003הלכה כמותו בחוצה לארץ, אבל בארץ\u0004 — \u0003לא,\u0004 אין הלכה כמותו.","על כך שואלים: אם כן \u0003ונימא\u0004 \u0005[ויאמר]\u0006 רב בפשטות: \u0003\"הלכה כר' עקיבא בחוצה לארץ\",\u0004 ש\u0003כל המיקל בארץ\u0004 — \u0003הלכה כמותו בחוצה לארץ\u0004 ומשיבים: \u0003אי אמר הכי, הוה אמינא\u0004 \u0005[אם היה אומר כך, הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 אמורים דווקא \u0003גבי\u0004 \u0005[אצל,\u0006 ביחס\u0005]\u0006 ל\u0003מעשר אילן,\u0004 שאפילו \u0003בארץ גופא\u0004 \u0005[עצמה]\u0006 אינו אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003אבל גבי\u0004 \u0005[אצל,\u0006 ביחס\u0005]\u0006 ל\u0003ערלה,\u0004 ש\u0003בארץ\u0004 היא אסורה \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003אימא\u0004 \u0005הייתי אומר]\u0006 כי \u0003בחוצה לארץ נמי\u0004 \u0005[גם כן]\u0006 \u0003נגזור\u0004 ונאסור את הפירות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף בערלה הלכה כר' עקיבא.","ובענין זה מסופר: \u0003רבינא אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003מר בר רב אשי דקא זריק\u0004 \u0005[שהוא זורק]\u0006 \u0003אביונות וקאכיל\u0004 \u0005[ואוכל]\u0006 \u0003קפריסין\u0004 של צלף ערלה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא למר בר רב אשי: \u0003מאי דעתך\u0004 \u0005[מה דעתך]\u0006 שאתה אוכל את הקפריסין, האם משום שאתה נוהג \u0003כ\u0004שיטת \u0003ר' עקיבא\u0004 שהוא \u0003מיקל, ולעביד מר\u0004 \u0005[ויעשה,\u0006 ינהג \u0005אדוני]\u0006 \u0003כ\u0004דעת \u0003בית שמאי דמקילי טפי\u0004 \u0005[המקילים יותר]!\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בענין דין כלאים ב\u0003צלף,\u0004 ש\u0003בית שמאי אומרים\u0004 שהצלף הוא \u0003כלאים בכרם,\u0004 ואיסור זריעת ירקות בכרם כולל את הצלף. \u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 ש\u0003אין\u0004 הצלף \u0003כלאים בכרם.\u0004 ואולם \u0003אלו ואלו מודים ש\u0004הצלף \u0003חייב בערלה.\u0004","ולפני סיכום הבעיה לענייננו, מעירים בהבהרת המשנה עצמה: \u0003הא גופא קשיא\u0004 \u0005[\u0006משנה \u0005זו עצמה קשה]\u0006 בשל סתירה פנימית בה: מצד אחד \u0003אמרת\u0004 בענין \u0003צלף\u0004 כי \u0003בית שמאי אומרים\u0004 שהוא \u0003כלאים בכרם, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מין ירק הוא, והדר תני\u0004 \u0005[וחזר ושנה]:\u0006 \u0003אלו ואלו מודים שחייב בערלה, אלמא\u0004 \u0005[מכאן]\u0006 \u0003מין אילן הוא!\u0004","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה],\u0006 שכן \u0003בית שמאי ספוקי מספקא להו, ועבדי הכא לחומרא והכא לחומרא\u0004 \u0005[מסופקים הם, ו\u0006הם \u0005עושים\u0006 נוהגים \u0005כאן להחמיר וכאן להחמיר],\u0006 שמאחר שלא החליטו בית שמאי אם הצלף הוא אילן או ירק, הריהם פוסקים לגביו לחומרה גם כאילן וגם כירק. \u0003מכל מקום לבית שמאי הוה ליה\u0004 \u0005[הריהו]\u0006 הצלף רק \u0003ספק ערלה, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 כהלכה מוסכמת: \u0003ספק ערלה\u0004 — \u0003בארץ ישראל\u0004 הוא \u0003אסור\u0004 באכילה, \u0003ובסוריא\u0004 הוא \u0003מותר\u0004 ואין חוששים לספק. \u0003ובחוצה לארץ יורד\u0004 בעל השדה הנכרי"],["\u0003ולוקח\u0004 מפירות הערלה — \u0003ובלבד שלא יראנו\u0004 היהודי \u0003לוקט.\u0004 ואם כן אפשר לנהוג בחוצה לארץ כדעת בית שמאי שהצלף לדעתם רק ספק ערלה, ועל כן אפשר לאכול גם את אביונות הצלף ללא חשש!","ומשיבים: הכלל שנוהגים בחוץ לארץ כדעת המקל בארץ, הרי זה כגון שעומדת דעת \u0003ר' עקיבא במקום\u0004 דעת \u0003ר' אליעזר,\u0004 שהם חולקים ודעת ר' עקיבא להקל, שאז \u0003עבדינן כותיה\u0004 \u0005[עושים אנו כמותו],\u0006 \u0003ו\u0004אולם כשעומדת דעת \u0003בית שמאי במקום\u0004 דעת \u0003בית הלל\u0004 — \u0003אינה\u0004 ודבריהם נדחו לגמרי מן ההלכה ואינם נחשבים.","באותו ענין עצמו עוסקים עתה בנקודה אחרת: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 ההלכה שהקפריסין אסורים בערלה מן הטעם שהקפריסין \u0003נעשה שומר לפרי, ורחמנא אמר\u0004 \u0005[והתורה אמרה]:\u0006 \u0003\"\u0004וכי תבואו אל הארץ ונטעתם כל עץ מאכל \u0003וערלתם ערלתו את פריו\"\u0004 (ויקרא יט, כג), ואנו דורשים כי \u0003\"את פריו\"\u0004 משמעו — \u0003את הטפל לפריו, ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — \u0003שומר לפרי,\u0004 אותו חלק בצמח השומר את הפרי ומכאן מקור ישיר לאסור את הקפריסין בערלה משום שומרי הפרי.","\u0003אמר רבא: היכא אמרינן\u0004 \u0005[היכן,\u0006 באיזה מקרה \u0005אומרים אנו]\u0006 ש\u0003נעשה שומר לפרי\u0004 — זהו דווקא \u0003היכא דאיתיה\u0004 \u0005[היכן שישנו]\u0006 \u0003בין בתלוש בין במחובר,\u0004 ואולם \u0003הכא במחובר\u0004 — \u0003איתיה\u0004 \u0005[ישנו],\u0006 \u0003בתלוש\u0004 — \u0003ליתיה\u0004 \u0005[אינו],\u0006 ומאחר שהשומר נופל מן הפרי כשהוא תלוש, שוב אינו נקרא \"שומר\".","\u0003איתיביה\u0004 \u0005[הקשה עליו]\u0006 \u0003אביי\u0004 ממה ששנינו בדיני טומאה: \u0003פיטמא של\u0004 פרי ה\u0003רמון מצטרפת\u0004 לשיעורו של הרימון והם נחשבים כדבר אחד לענין מדידת הכמות המינימלית העשויה לקבל טומאה. \u0003ו\u0004אולם \u0003הנץ שלו\u0004 (פרח הרימון) \u0003אין מצטרף. מדקאמר\u0004 \u0005[ממה שאמר]\u0006 ש\u0003הנץ שלו אין מצטרף, אלמא דלאו\u0004 \u0005[מכאן שלא]\u0006 \u0003אוכל הוא,\u0004 אלא טפל בלבד. \u0003ו\u0004אף על פי כן \u0003תנן\u0004 \u0005[שנה]\u0006 בדיני \u0003ערלה\u0004: \u0003קליפי רמון והנץ שלו, קליפי אגוזים והגרעינין\u0004 כולם \u0003חייבין בערלה.\u0004 הרי שקנה המידה שעל פיו אנו קובעים מה נחשב כשומר לפרי ומצטרף לאוכל לדיני טומאה אינו קובע בדיני ערלה, וכפי שאנו רואים במקרה של נץ הרימון. ועל כן הקפריסין אף אם אינם נחשבים כשומר לפרי בדיני טומאה, עדיין אפשר שהם מצטרפים לו לדיני ערלה!","\u0003אלא אמר רבא\u0004 הסבר אחר: \u0003היכא אמרינן\u0004 \u0005[היכן אנו אומרים]\u0006 ש\u0003נעשה להו\u0004 \u0005[להם]\u0006 \u0003שומר לפירי\u0004 \u0005[לפירות]\u0006 — הרי זה \u0003היכא דאיתיה\u0004 \u0005[היכן שישנו],\u0006 השומר \u0003בשעת גמר\u0004 בישול \u0003פירא\u0004 \u0005[הפרי],\u0006 ואולם \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003קפרס\u0004 (=יחידה אחת של קפריסין) \u0003ליתיה\u0004 \u0005[איננו]\u0006 \u0003בשעת גמר פירא\u0004 \u0005[הפרי]\u0006 והוא נושר עוד לפני גמר בישול הפרי.","גם על הסבר זה מקשים: \u0003איני\u0004 \u0005[וכן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן אמר רבה בר אבוה: הני מתחלי\u0004 \u0005[אותן עטיפות התמרים]\u0006 של \u0003ערלה\u0004 — \u0003אסירי\u0004 \u0005[אסורות],\u0006 \u0003הואיל ונעשו שומר לפירי. ו\u0004אולם אותן עטיפות \u0003שומר לפירי אימת הוי\u0004 \u0005[מתי הן],\u0006 כלומר, ממתי מתחילות הן לשמש כשומר לפרי — \u0003בכופרא\u0004 \u0005[בעוד הפרי צעיר],\u0006 \u0003ו\u0004בכל זאת \u0003קא קרי ליה\u0004 \u0005[הוא קורא לו,\u0006 להם\u0005]\u0006 \u0003\"שומר לפירי\u0004 \u0005[לפירות]\u0006\u0003\",\u0004 הרי ששומר לפרי אינו צריך להשאר עד גמר בישולו של הפרי, ושוב יש לשאול מפני מה אין משווים את הקפריסין לפירות הצלף?!","על כך מסבירים כי \u0003רב נחמן סבר לה\u0004 \u0005[סבור הוא]\u0006 להלכה \u0003כ\u0004שיטת \u0003ר' יוסי, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 ש\u0003ר' יוסי אומר\u0004 ש\u0003סמדר\u0004 (הענבים בשלב הראשון של היותם פירות, מיד לאחר שנופלים פרחי הגפן) \u0003אסור\u0004 משום ערלה \u0003מפני שהוא\u0004 נחשב כבר כ\u0003פרי\u0004 ולשיטה זו גם עטיפות התמרים, אף על פי שהן בשלב ראשון של חניטתם נחשבים לערלה. \u0003ופליגי רבנן עליה\u0004 \u0005[וחלוקים חכמים עליו]\u0006 והם סבורים כי הסמדר איננו פרי, ועל כן גם עטיפות התמרים אינן פרי וכמו כן גם הקפריסין.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על הלכה זו\u0005]\u0006 \u0003רב שימי מנהרדעא: ובשאר אילני\u0004 \u0005[אילנות],\u0006 פרט לענבים \u0003מי פליגי רבנן עליה\u0004 \u0005[האם חלוקים חכמים עליו]\u0006 במה שלדעתו הפרי אף בשלב הראשון של הבשלתו נקרא \"פרי\"? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 בתורה נאמר ביחס לפירות הגדלים בשביעית \"והיתה שבת הארץ לכם לאכלה\" (ויקרא כה, ו) ולמדו חכמים \"לאכלה\" — ולא להפסד. ומכיון שאסור להפסיד פירות שביעית, דנים \u0003מאימתי אין קוצצין את האילנות בשביעית\u0004 (בשנת השמיטה) כיון שבכך הוא גורם להשחתה — \u0003בית שמאי אומרים: כל האילנות משיוציאו,\u0004 כלומר, מאותו זמן שבו נופלת התפרחת, ומתגלים הפירות בשלב הראשוני שלהם. \u0003ובית הלל אומרים\u0004 שיש לחלק בין סוגי האילנות, \u0003החרובין\u0004 אסורים להיקצץ \u0003משישרשרו\u0004 — כשפרי החרוב מקבל צורה הדומה קצת לשרשרת. \u0003והגפנים משיגרעו\u0004 (יבואר להלן), \u0003והזיתים משיניצו, ושאר כל האילנות משיוציאו.\u0004","\u0003ואמר רב אסי:\u0004 \"שיגרעו\" הכתוב במשנה יש להבין: \u0003הוא בוסר, הוא גרוע, הוא פול הלבן.\u0004 עוד בטרם בירור הענין תמהים: \u0003פול הלבן סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 כיצד אפשר לדבר על פול הלבן בגפנים? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ש\u0003שיעורו\u0004 של הבוסר \u0003כפול הלבן.\u0004 ועל כל פנים \u0003מאן שמעת ליה דאמר\u0004 \u0005[את מי שמעת שאומר]\u0006 כי \u0003בוסר אין\u0004 \u0005[כן]\u0006 נחשב לפרי, ואילו \u0003סמדר לא\u0004 — הלא הם \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' יוסי, \u0003וקתני\u0004 \u0005[ושנינו]\u0006 שלדעת חכמים אלה \u0003שאר כל האילנות\u0004 — \u0003משיוציאו,\u0004 הרי שאף הם מסכימים שהפרי מתחילת חניטתו אסור משום ערלה, וחוזרים אנו אם כן לשאלה הראשונה מדוע הקפריסין מותרים?","\u0003אלא אמר רבא\u0004 פירוש אחר: \u0003היכא אמרינן דהוי\u0004 \u0005[היכן אנו אומרים שהוא]\u0006 \u0003שומר לפרי\u0004 — \u0003היכא דכי שקלת ליה\u0004 \u0005[היכן שאם אתה נוטל אותו]\u0006 את ה\u0003שומר, מיית פירא\u0004 \u0005[מת הפרי],\u0006 \u0003הכא כי שקלת ליה\u0004 \u0005[כאן\u0006 בצלף, \u0005כאשר אתה מוריד אותו],\u0006 את הקפרס — \u0003לא מיית פירא\u0004 \u0005[מת הפרי],\u0006","ואכן \u0003הוה עובדא ושקלוה לנץ דרמונא\u0004 \u0005[היה מעשה ונטלו,\u0006 הורידו, \u0005את נץ הרימון],\u0006 \u0003ויבש רמונא\u0004 \u0005[הרימון],\u0006 \u0003ושקלוה לפרחא דביטיתא\u0004 \u0005[ונטלו, את פרח פרי הצלף]\u0006 — \u0003ואיקיים ביטיתא\u0004 \u0005[והתקיים פרי הצלף]\u0006 ולא מת, וזו הסיבה שקפריסין אינם נחשבים כשומר לפרי.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כמר בר רב אשי דזריק\u0004 \u0005[שזרק]\u0006 \u0003את האביונות ואכיל\u0004 \u0005[ואכל]\u0006 \u0003את הקפריסין. ומ\u0004כיון ש\u0003לגבי ערלה לאו פירא נינהו\u0004 \u0005[אינם\u0006 נחשבים \u0005כפירות],\u0006 \u0003לגבי ברכות נמי לאו פירא נינהו\u0004 \u0005[גם כן אינם\u0006 נחשבים \u0005כפרי],\u0006 \u0003ולא מברכינן עליה\u0004 \u0005[ואין אנו מברכים עליו]\u0006 \u0003\"בורא פרי העץ\" אלא \"בורא פרי האדמה\".\u0004","שאלה מה לברך התעוררה גם לגבי \u0003פלפלי\u0004 \u0005[פלפלים].\u0006 \u0003רב ששת אמר:\u0004 האוכל פלפלים צריך לברך \u0003\"שהכל\",\u0004 ואילו \u0003רבא אמר: לא כלום,\u0004 אינו צריך לברך כלל. \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 שאכילת פלפלים אינה נחשבת, ש\u0003אמר: כס פלפלי ביומא דכפורי\u0004 \u0005[כסס,\u0006 כרסם, \u0005פלפלים ביום הכיפורים]\u0006 — \u0003פטור, כס זנגבילא ביומא דכפורי\u0004 \u0005[כסס זנגביל ביום הכיפורים]\u0006 — \u0003פטור,\u0004 שאכילת הפירות החריפים הללו אינה מנהג בני אדם, ואינה נחשבת לאכילה, האסורה מן התורה ביום הכיפורים.","על כך \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא ש\u0003היה ר' מאיר אומר\u0004 על הפסוק \"וכי תבואו אל הארץ ונטעתם כל עץ מאכל וערלתם ערלתו את פריו\" (ויקרא יט, כג): ממשמע שנאמר \u0003\"וערלתם ערלתו את פריו\"\u0004 וכי \u0003איני יודע שעץ מאכל הוא? אם כן מה תלמוד לומר\u0004 (מה מלמדנו הכתוב) \u0003\"כל עץ מאכל\"\u0004 — \u0003להביא עץ שטעם עצו ופריו שוה. ואיזהו?\u0004 — \u0003זה הפלפלין. ללמדך שהפלפלין\u0004 ואפילו החלק העצי שבהם ראויים לאכילה, ולפיכך הם \u0003חייבין בערלה, וללמדך שאין ארץ ישראל חסרה כלום,\u0004 וכפי \u0003שנאמר: \"ארץ אשר לא במסכנת תאכל בה לחם לא תחסר כל בה\"\u0004 (דברים ח, ט), והרי שהפלפלים ראויים לאכילה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 שיש לחלק, \u0003הא\u0004 \u0005[זה]\u0006 שרואים מדברי ר' מאיר שהפלפלים ראויים לאכילה הרי זה \u0003ברטיבתא\u0004 \u0005[ברטובה],\u0006 בעוד הפלפלים רכים שאז הם ראויים לאכילה. ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו לענין יום הכיפורים שאין כסיסתם נחשבת לאכילה, הרי זה \u0003ביבשתא\u0004 \u0005[ביבישה],\u0006 שכשמכרסם פלפלים יבשים אין אכילתו אכילה, ואינה טעונה ברכה.","אגב הזכרת ענין כסיסת הפלפלים ביום כיפור מביאים את מה ש\u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003למרימר:\u0004 מפני מה \u0003כס זנגבילא ביומא דכפורי\u0004 \u0005[הכוסס זנגביל ביום הכיפורים]\u0006 \u0003פטור? והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבא: האי המלתא דאתיא מבי הנדואי\u0004 \u0005[אותו זנגביל הבא מהודו]\u0006 — \u0003שריא\u0004 \u0005[מותר]\u0006 באכילה, \u0003ומברכינן עליה\u0004 \u0005[ומברכים אנו עליו]\u0006 \u0003\"בורא פרי האדמה\".\u0004 ומתוך שלענין ברכה רואים אנו שהוא נחשב כראוי לאכילה, כך צריך להיות הדין גם לגבי כסיסתו ביום הכיפורים! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שיש לברך עליו הרי זה \u0003ברטיבתא\u0004 \u0005[ב\u0006זנגביל \u0005רטוב,\u0006 טרי\u0005],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו לענין כסיסתו ביום הכיפורים שאינה נחשבת כאכילה הרי זה \u0003ביבשתא\u0004 \u0005[ביבש].\u0006","וכן שאלו בדבר ברכת \u0003חביץ קדרה\u0004 (מאכל העשוי מתערובת קמח שמן ודבש) \u0003וכן דייסא.\u0004 ונחלקו הדעות, \u0003רב יהודה אמר\u0004 שמברכים עליהם \u0003\"שהכל נהיה בדברו\"\u0004 ואילו \u0003רב כהנא אמר\u0004 שמברכים עליהם \u0003\"בורא מיני מזונות\".\u0004 ומבארים: \u0003בדייסא גרידא\u0004 \u0005[בלבד]\u0006 בלי דבר \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שמברכים עליה \u0003\"בורא מיני מזונות\". כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 הרי זה \u0003בדייסא\u0004 שמוסיפים לה דבש, \u0003כעין\u0004 מה שעושים ב\u0003חביץ קדרה,\u0004 ש\u0003רב יהודה אמר\u0004 שמברכים עליו \u0003\"שהכל\",\u0004 שהוא \u0003סבר דובשא\u0004 \u0005[סבור\u0006 ש\u0005הדבש]\u0006 \u0003עיקר,\u0004 ועליו מברכים \"שהכל\". ו\u0003רב כהנא אמר\u0004 שמברכים עליו \u0003\"בורא מיני מזונות\".\u0004 כיון שהוא \u0003סבר סמידא\u0004 \u0005[סבור\u0006 ש\u0005הסולת]\u0006 \u0003עיקר,\u0004 ועליה כעל כל שאר דברים הנעשים מתבואה מברכים \"בורא מיני מזונות\". \u0003אמר רב יוסף: כותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב כהנא מסתברא\u0004 \u0005[מסתבר]\u0006 לומר, שכן \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כל שיש בו מחמשת המינין\u0004 של דגן \u0003מברכין עליו \"בורא מיני מזונות\"\u0004 אף שהוא מעורב בדברים אחרים.","בהלכה על ברכת חמשת המינים, מבררים את הענין \u0003גופא\u0004 \u0005[לגופו].\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 ש\u0003כל\u0004 מאכל \u0003שיש בו מחמשת המינין מברכין עליו \"בורא מיני מזונות\". ואיתמר נמי\u0004 \u0005[ונאמר גם כן]\u0006 במקום אחר ש\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 ש\u0003כל\u0004 מאכל \u0003שיש בו מחמשת המינין מברכין עליו \"בורא מיני מזונות\".\u0004 ולכאורה תמוה הדבר, שכן שני מאמרים אלה הינם חזרה על אותה הלכה!","על כן מסבירים: \u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 החזרה, שכן \u0003אי אשמעינן\u0004 \u0005[אילו היה משמיע לנו]\u0006 רק ש\u0003כל שהוא\u0004 מחמשת המינים חייב בברכת מזונות \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003משום דאיתיה בעיניה\u0004 \u0005[ש\u0006הדגן \u0005ישנו בעינו],\u0006 \u0003אבל על ידי תערובות\u0004 — \u0003לא\u0004 יברכו עליו \"בורא מיני מזונות\"."],["על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003\"כל שיש בו\u0004 מחמשת המינים \u0003\"\u0004— ואפילו בתערובת. \u0003ו\u0004מצד שני: \u0003אי אשמעינן\u0004 \u0005[אילו היה משמיע לנו]\u0006 \u0003\"כל שיש בו\u0004 מחמשת המינים \u0003\"\u0004— \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי דווקא \u0003כל שיש בו\u0004 מ\u0003חמשת המינים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מברכים עליו \"בורא מיני מזונות\", אף בתערובת, \u0003אבל\u0004 כל שיש בו מ\u0003אורז ודוחן\u0004 — \u0003לא\u0004 יברכו עליו \"בורא מיני מזונות\", \u0003משום\u0004 שהם קיימים באותו מאכל \u0003על ידי תערובת. אבל\u0004 אם האורז או הדוחן \u0003איתיה בעיניה\u0004 \u0005[ישנו בעינו]\u0006 — \u0003נימא\u0004 \u0005[נאמר]\u0006 כי \u0003אפילו אורז ודוחן נמי\u0004 \u0005[גם כן]\u0006 \u0003מברכין עליו \"בורא מיני מזונות\"\u0004 שאף הם מין דגן. ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי דווקא \u0003כל שהוא מחמשת המינים הוא\u0004 ש\u0003מברכין עליו \"בורא מיני מזונות\", לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003אורז ודוחן,\u0004 ש\u0003אפילו\u0004 כאשר \u0003איתיה בעיניה\u0004 \u0005[ישנו בעינו]\u0006 גם כן \u0003לא מברכינן\u0004 \u0005[אין אנו מברכים]\u0006 עליו \u0003\"בורא מיני מזונות\".\u0004","אגב הדברים אליהם הגענו למסקנה, שואלים: \u0003ו\u0004על \u0003אורז ודוחן לא מברכינן\u0004 \u0005[אין אנו מברכים]\u0006 \u0003\"בורא מיני מזונות\"? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הביאו לפניו פת אורז ופת דוחן\u0004 — \u0003מברך עליו תחלה וסוף כמעשה קדרה\u0004 (כתבשיל מבצק), \u0003ו\u0004הרי \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מעשה קדרה תניא\u0004 \u0005[שנינו\u0006 בבריתא\u0005]\u0006 ש\u0003בתחלה,\u0004 לפני האוכל, \u0003מברך עליו \"בורא מיני מזונות\", ולבסוף,\u0004 אחר האוכל, \u0003מברך עליו ברכה אחת מעין שלש.\u0004 והרי שמברכים על האורז \"בורא מיני מזונות\"!","הוכחה זאת נדחית: אמנם האורז הוא \u0003כמעשה קדרה ו\u0004אולם \u0003לא כמעשה קדרה\u0004 בכל. ומפרטים: דינו \u0003כמעשה קדרה\u0004 בכך ש\u0003מברכין עליו תחלה וסוף, ולא כמעשה קדרה\u0004 ש\u0003אילו במעשה קדרה\u0004 מברכים \u0003בתחלה \"בורא מיני מזונות\" ולבסוף ברכה מעין שלש, ואילו הכא\u0004 \u0005[כאן\u0006 באורז\u0005]\u0006 \u0003בתחלה מברך עליו \"שהכל נהיה בדברו\", ולבסוף \"בורא נפשות רבות וחסרונן על כל מה שבראת...\".\u0004","ומקשים: \u0003ו\u0004כי \u0003אורז לאו\u0004 \u0005[לא]\u0006 \u0003מעשה קדרה הוא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אלו הן מעשה קדרה: חילקא\u0004 (חיטים שנשברו כל אחת לשתים לצורך דייסה), \u0003טרגיס\u0004 (חיטים שנכתשו על מנת שתישבר כל אחת לשלוש), \u0003סולת, זריז\u0004 (חיטים כתושות אחת לארבע), \u0003וערסן\u0004 (אחת לחמש), \u0003ואורז.\u0004 הרי שהאורז נמנה עם פרורי החיטה כמעשה קדרה!","על כך עונים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו,\u0006 של \u0005מי היא]\u0006 — של \u0003ר' יוחנן בן נורי היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יוחנן בן נורי אומר: אורז מין דגן הוא\u0004 לכל דבר, \u0003ו\u0004על כן \u0003חייבין על חמוצו\u0004 (אם נעשה חמץ) \u0003כרת\u0004 בפסח אם אוכלים חמץ אורז בזדון, \u0003ו\u0004כן \u0003אדם\u0004 שאפה מצה מקמח האורז \u0003יוצא בו ידי חובתו\u0004 במצות מצה \u0003בפסח, אבל\u0004 דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא\u0004 כן.","על כך מקשים: \u0003ורבנן לא\u0004 \u0005[ו\u0006כי דעת \u0005חכמים אינה\u0006 כן\u0005]\u0006 לענין ברכות?! \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003הכוסס את החטה מברך עליה \"בורא פרי האדמה\".\u0004 ואולם אם \u0003טחנה, אפאה ובשלה,\u0004 שעשאה לחם ואחר כך בישל את הלחם, יש להבחין בין שני מקרים; \u0003בזמן שהפרוסות קיימות,\u0004 שלא נימוחו בעת הבישול, אזי \u0003בתחלה,\u0004 לפני האוכל, \u0003מברך עליה \"המוציא לחם מן הארץ\", ולבסוף,\u0004 לאחר האוכל \u0003מברך עליה שלש ברכות\u0004 כמו הברכות שעל הלחם. ו\u0003אם אין הפרוסות קיימות,\u0004 שנימוחו בעת הבישול, \u0003בתחלה מברך עליה \"בורא מיני מזונות\", ולבסוף מברך עליה ברכה אחת מעין שלש\u0004 (\"על המחיה...\").","ולענין אורז, \u0003הכוסס את האורז מברך עליו \"בורא פרי האדמה\".\u0004 ואם \u0003טחנו\u0004 ו\u0003אפאו ו\u0004אחר כך \u0003בשלו, אף על פי שהפרוסות קיימות, בתחלה מברך עליו \"בורא מיני מזונות\", ולבסוף\u0004 הוא \u0003מברך עליו ברכה אחת מעין שלש.\u0004","ומעתה דנים בתוספתא זו, \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא],\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שדעת \u0003ר' יוחנן בן נורי היא\u0004 שהוא \u0003אמר\u0004 שה\u0003אורז מין דגן הוא,\u0004 אם כן במקרה זה לשיטתו \u0003\"המוציא לחם מן הארץ\"\u0004 בתחילה \u0003ושלש ברכות\u0004 לבסוף \u0003בעי ברוכי\u0004 \u0005[צריך\u0006 היה \u0005לברך]\u0006 \u0003כעל לחם ממש!\u0004","\u0003אלא לאו, רבנן\u0004 \u0005[האם לא,\u0006 שיטת \u0005חכמים]\u0006 \u0003היא\u0004 שאינם סבורים שהאורז מין דגן הוא ואף על פי כן שנינו שמברך עליו \"בורא מיני מזונות\", \u0003ו\u0004הרי זו אם כן \u0003תיובתא\u0004 \u0005[קושיא חמורה]\u0006 על \u0003רב ושמואל!\u0004","ומעירים: אכן זו \u0003תיובתא\u0004 \u0005[קושיא חמורה],\u0006 ונדחו דבריהם.","קודם לכן שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בתוספתא ש\u0003הכוסס את החטה מברך עליה \"בורא פרי האדמה\".\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שהכוסס את החיטה מברך \u0003\"בורא מיני זרעים\"!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן מחלוקת תנאים היא; \u0003הא\u0004 \u0005[\u0006שיטה \u0005זו]\u0006 שהובאה שצריך לברך \"בורא מיני זרעים\", זו דעת \u0003ר' יהודה\u0004 היא. \u0003והא\u0004 \u0005[ו\u0006שיטה \u0005זו]\u0006 שצריך לברך \"בורא פרי האדמה\", שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ועל ירקות אומר\u0004 האוכלם \u0003\"בורא פרי האדמה\", ר' יהודה אומר: \"בורא מיני דשאים\"\u0004 הרי שר' יהודה מייחד לכל סוג צמחים ברכה אופיינית, ובוודאי, לשיטתו, הוא מבחין גם בין פרי האדמה בכלל, לבין זרעים.","עוד שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה תוספתא ש\u0003הכוסס את האורז\u0004 חי, \u0003מברך עליו \"בורא פרי האדמה\". טחנו, אפאו\u0004 לפת \u0003ו\u0004אחר כך \u0003בשלו, אף על פי שהפרוסות קיימות, בתחלה מברך עליו \"בורא מיני מזונות\", ולבסוף\u0004 מברך עליו \u0003ברכה אחת מעין שלש.\u0004","על כך הקשו: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שבמקרה כגון זה \u0003לבסוף\u0004 אינו מברך \u0003ולא כלום\u0004 מאותן ברכות אותן מברך על פירות ארץ ישראל, אלא \"בורא נפשות\"! \u0003אמר רב ששת: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שאין זו סתירה אלא שיטות שונות של תנאים; \u0003הא\u0004 \u0005[\u0006שיטה \u0005זו]\u0006 לפיה מברך ברכה אחת מעין שלוש, \u0003רבן גמליאל\u0004 היא, \u0003והא\u0004 \u0005[ו\u0006שיטה \u0005זו]\u0006 לפיה אינו מברך אלא \"בורא נפשות\", שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005],\u0006 \u0003זה הכלל: כל שהוא משבעת המינים\u0004 של דגן ופירות שנשתבחה בהם ארץ ישראל, \u0003רבן גמליאל אומר\u0004 שמברכים לאחריהם \u0003שלש ברכות,\u0004 שהן ברכת המזון השלמה. \u0003וחכמים אומרים\u0004 שדי ב\u0003ברכה אחת מעין שלש. ו\u0004מסופר","\u0003מעשה ברבן גמליאל והזקנים\u0004 חכמי דורו \u0003שהיו מסובין בעלייה ביריחו, והביאו לפניהם כותבות\u0004 (תמרים), \u0003ואכלו, ונתן רבן גמליאל רשות לר' עקיבא לברך\u0004 עליהם לאחר האכילה. \u0003קפץ\u0004 (כלומר, הזדרז) \u0003וברך ר' עקיבא ברכה אחת מעין שלש. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבן גמליאל\u0004 לר' עקיבא: \u0003עקיבא, עד מתי אתה מכניס ראשך בין המחלוקת,\u0004 שהרי בדבר שעשית נחלקו החכמים! \u0003אמר לו\u0004 ר' עקיבא: \u0003רבינו, אף על פי שאתה אומר כן וחבריך אומרים כן\u0004 והנכם חולקים זה על זה, מכל מקום \u0003למדתנו רבינו\u0004 כלל כי כאשר קיימת מחלוקת בהלכה בין \u0003יחיד\u0004 ל\u0003רבים\u0004 — \u0003הלכה כ\u0004שיטת ה\u0003רבים,\u0004 ואף שאתה הנשיא, מכל מקום ראוי לנהוג כדעת הרבים שהלכה כמותם לפי כלל זה.","גירסה שונה במקצת על מחלוקת רבן גמליאל וחכמים \u0003ר' יהודה אומר משמו\u0004 של ר' עקיבא. \u0003כל\u0004 דבר \u0003שהוא משבעת המינים\u0004"],["\u0003ולא מין דגן הוא,\u0004 אלא אחד מן הפירות, \u0003או מין דגן\u0004 הוא אלא ש\u0003לא עשאו פת,\u0004 בכך נחלקו; \u0003רבן גמליאל אומר\u0004 שמברכים עליו \u0003שלש ברכות\u0004 (ברכת המזון), \u0003וחכמים אומרים\u0004 שמברך \u0003ברכה אחת.\u0004 ו\u0003כל שאינו לא משבעת המינין ולא מין דגן, כגון פת אורז ודוחן, רבן גמליאל אומר\u0004 שמברכים עליו לאחר אכילתו \u0003ברכה אחת מעין שלש, וחכמים אומרים\u0004 שאין מברך עליו \u0003ולא כלום\u0004 מאותן ברכות (שלוש ברכות או שלוש מעין אחת), אלא \"בורא נפשות\" בלבד. ואם כן התוספתא האומרת שאחר האורז מברכים ברכה מעין שלוש הריהי כשיטת רבן גמליאל על פי גירסת ר' יהודה.","על כך מקשים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת,\u0006 הסברת\u0005]\u0006 את התוספתא — \u0003כרבן גמליאל,\u0004 אם כן \u0003אימא סיפא דרישא\u0004 \u0005[אמור,\u0006 עיין, \u0005בסיום תחילתה],\u0006 בקטע המסיים את חלקה הראשון של תוספתא זו, שנאמר בו שאף פת העשויה מחיטה, \u0003אם אין הפרוסות קיימות\u0004 — \u0003בתחלה מברך עליה \"בורא מיני מזונות\", ולבסוף מברך עליה ברכה אחת מעין שלש.\u0004 והלכה זו \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר ששיטת \u0003רבן גמליאל\u0004 היא, \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי אם על \u0003כותבות ו\u0004על \u0003דייסא אמר רבן גמליאל\u0004 שמברכים \u0003שלש ברכות\u0004 שלמות, אם כן, \u0003אם אין הפרוסות קיימות מיבעיא\u0004 \u0005[צריך,\u0006 לומר\u0005]\u0006 שיברכו כעל לחם?!","\u0003אלא פשיטא רבנן\u0004 \u0005[פשוט\u0006 הוא, שהתוספתא כשיטת \u0005חכמים],\u0006 ואולם \u0003אי הכי קשיא דרבנן אדרבנן\u0004 \u0005[אם כך קשה מ\u0006דברי \u0005חכמים על\u0006 דברי \u0005חכמים\u0006 עצמם\u0005],\u0006 שיש סתירה בין המקורות! ומתרצים; \u0003אלא לעולם\u0004 יש לפרש שהתוספתא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003ותני\u0004 \u0005[ושנה]\u0006 תקן את הגירסה ואמור \u0003גבי\u0004 \u0005[אצל,\u0006 ביחס\u0005]\u0006 ל\u0003אורז\u0004 כי \u0003לבסוף אינו מברך עליו ולא כלום\u0004 כאמור בברייתא.","ובענין הברכות על דייסות שונות, \u0003אמר רבא: האי ריהטא דחקלאי דמפשי ביה קמחא\u0004 \u0005[אותה תערובת סולת ודבש של חקלאים ש\u0006הם \u0005מרבים בה קמח],\u0006 \u0003מברך\u0004 עליה \u0003\"בורא מיני מזונות\". מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — לפי \u0003דסמידא\u0004 \u0005[שהסולת]\u0006 \u0003עיקר\u0004 בתערובת. אבל אותו מאכל באופן שעושים בני העיר \u0003מחוזא, דלא מפשי ביה קמחא\u0004 \u0005[שאין מרבים בו קמח]\u0006 \u0003מברך עליו \"שהכל\" מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — לפי שבה \u0003דובשא\u0004 \u0005[הדבש]\u0006 \u0003עיקר. והדר\u0004 \u0005[וחזר]\u0006 ו\u0003אמר רבא: אידי ואידי\u0004 \u0005[אלה ואלה],\u0006 גם של החקלאים וגם של בני העיר מברכים עליהם \u0003\"בורא מיני מזונות\".\u0004 שכן \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כל שיש בו מחמשת המינים\u0004 אפילו איננו עיקר \u0003מברכין עליו \"בורא מיני מזונות\".\u0004","\u0003אמר רב יוסף: האי חביצא דאית ביה\u0004 \u0005[אותו תבשיל שיש,\u0006 שמכניסים, \u0005בו]\u0006 \u0003פרורין\u0004 של לחם הגדולים \u0003כזית\u0004 — \u0003בתחלה מברך עליו \"המוציא לחם מן הארץ\", ולבסוף מברך עליו שלש ברכות,\u0004 כדרך שמברך על לחם. ואותו מרק שיש בו פירורי לחם אלא \u0003דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003פרורין\u0004 שגודלם \u0003כזית\u0004 — \u0003בתחלה מברך עליו \"בורא מיני מזונות\", ולבסוף ברכה אחת מעין שלש,\u0004 כמו על מעשה קדרה.","ו\u0003אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אמרתי אותה]\u0006 את ההלכה הזו — ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה\u0004 הכהן \u0003עומד ומקריב\u0004 בפעם הראשונה \u0003מנחות בירושלים\u0004 — \u0003אומר \"ברוך שהחיינו וקימנו והגיענו לזמן הזה\",\u0004 על שהגיע לקיים בפעם הראשונה מצוה זו של הקרבת קרבן (רש\"י). \u0003נטלן\u0004 למנחות כדי \u0003לאכלן\u0004 — \u0003מברך \"המוציא לחם מן הארץ\". ותני עלה\u0004 \u0005[ושנוי עליה]\u0006 על ענין המנחות: \u0003וכולן,\u0004 כל המנחות, \u0003פותתן\u0004 ב\u0003כזית\u0004 (שהיה מפורר את כל המנחות לפתיתים—פירורים בגודל כזית בערך), ומכאן שמאכל של פירורי לחם שגודלם כזית יש לברך עליו \"המוציא\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003אלא מעתה,\u0004 לפי שיטה זו \u0003ל\u0004דעת ה\u0003תנא דבי ר' ישמעאל\u0004 ש\u0003אמר במנחות: פורכן\u0004 (מפוררן לפירורים קטנים) \u0003עד שמחזירן לסלתן,\u0004 כפי שהיו מתחילה, \u0003הכי נמי דלא בעי ברוכי\u0004 \u0005[האם גם כן,\u0006 תאמר \u0005שאינו צריך לברך]\u0006 \u0003\"המוציא לחם מן הארץ\"?! וכי תימא הכי נמי\u0004 \u0005[ואם תאמר\u0006 כי \u0005כן הוא]\u0006 ועל מנחות אלה אין לברך ברכת \"המוציא\", \u0003והתניא\u0004 \u0005[והרי שנינו]\u0006 בהמשך הדברים: \u0003לקט מכולן,\u0004 מכל פירורי המנחות \u0003כזית ואכלן, אם חמץ הוא\u0004 (אם היתה זו מנחת חמץ כמו בלחמי תודה) — הריהו \u0003ענוש כרת\u0004 אם אכל בפסח, \u0003ואם\u0004 מנחת \u0003מצה הוא\u0004 — \u0003אדם יוצא בו ידי חובתו בפסח\u0004 כמצה. ומכאן שפירורי לחם, בלי להתחשב בגודלם, נחשבים תמיד ללחם.","על כך משיב רב יוסף שאין הדבר כן, ואין לברך על פירורים כעל לחם, אלא \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בשערסן,\u0004 שבלל אותן במים ועשאם שוב לחם, על כך מקשים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כן אמור\u0006 את \u0005הסוף],\u0006 ששנינו בו, \u0003והוא,\u0004 כלומר, דברים אלו באוכל פירורים אמורים דווקא \u0003שאכלן בכדי אכילת פרס,\u0004 כלומר, שאכל את כל הפירורים (המצטרפים לשיעור כזית) במשך זמן שבו אפשר לאכול פרס — חצי כיכר לחם. \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003ב\u0004אופן \u0003שערסן,\u0004 כשגבלן יחד, \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"שאכלן\"\u0004 אינו מתאים, ו\u0003\"שאכלו\" מיבעי ליה\u0004 \u0005[היה לו\u0006 לומר\u0005],\u0006","שהרי זה לחם אחד ולא פירורים. \u0003אלא\u0004 יש להסביר בדרך שונה ולומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בבא מלחם גדול,\u0004 כשכל אחד מהפירורים הוא חלק מלחם גדול שהיה עליו חיוב של ברכת \"המוציא\" קודם, אבל פירורים מתחילתם מברך עליהם כעל לחם רק אם שיעורם בכזית ויותר.","אחר שכל הראיות שהובאו לשיטה זו ונגדה בטלו, שואלים: \u0003מאי הוה עלה\u0004 \u0005[מה היה עליה,\u0006 על הלכה זו]? כיצד יש לפסוק בענין זה? \u0003אמר רב ששת: האי\u0004 \u0005[זו]\u0006 ה\u0003חביצא, אף על גב דלית ביה\u0004 \u0005[אף על פי שאין בו]\u0006 \u0003פרורין\u0004 שגודלם \u0003כזית\u0004 — \u0003מברך עליו \"המוציא לחם מן הארץ\". אמר רבא: והוא\u0004 דווקא באופן \u0003דאיכא עליה תוריתא דנהמא\u0004 \u0005[שיש עליו,\u0006 על התבשיל הזה, \u0005מראה לחם]\u0006 ולא נמחו הפירורים לגמרי.","בעיה אחרת היתה ביחס ל\u0003טרוקנין,\u0004 שעליהם נאמר ש\u0003חייבין ב\u0004הפרשת \u0003חלה,\u0004 כלומר, שעשייתם נחשבת כעשיית לחם. \u0003ו\u0004אולם \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן\u0004 ש\u0003טרוקנין פטורים מן החלה.\u0004 אגב פסק ההלכה בענין הטרוקנין, שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003טרוקנין? אמר אביי:\u0004 טרוקנין הם \u0003כובא דארעא\u0004 (מאכל הנעשה על ידי הכנסת תערובת דלילה של מים וקמח במישרין אל תוך הכירה) ואיננו לחם ממש.","\u0003ו\u0004כן \u0003אמר אביי: טריתא פטורה מן החלה\u0004. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003טריתא?\u0004 על כך היו דעות שונות. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהוא \u0003גביל מרתח\u0004 \u0005[גיבול\u0006 מים וקמח ששופכים לכירה כשהיא מוסקת ו\u0005רותחת].\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שזהו \u0003נהמא דהנדקא,\u0004 שהוא לחם העשוי מבצק שכורכים אותו על שיפוד ואופים אותו כשהוא משוח בשמן או במי ביצים באופן זה בתנור. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שטריתא הריהו \u0003לחם העשוי לכותח,\u0004 שהוא לחם מיוחד שאפו שלא כרגיל על מנת להחמיץ אותו אחר כך ביותר, ולהשתמש בו כמרכיב בתבלין הבבלי הקרוי כותח.","וכן \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: לחם העשוי לכותח פטור מן החלה.\u0004 על כך מקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במקום אחר ש\u0003חייב בחלה!\u0004 ומתרצים: \u0003התם כדקתני טעמא\u0004 \u0005[שם כפי ששנינו\u0006 מהו \u0005הטעם]\u0006 ש\u0003ר' יהודה אומר שיש לחלק בלחם העשוי לכותח בין סוגים שונים, שמעשיה\u0004 (דרך עשייתה) \u0003מוכיחין עליה לשם מה נעשתה. עשאן\u0004"]]};
